# PyArrow can be imported transitively by pandas/Streamlit during dataframe
# serialization. Prefer the system allocator on macOS/Python 3.13 to avoid
# observed native crashes in Arrow's mimalloc allocator.
os.environ.setdefault("ARROW_DEFAULT_MEMORY_POOL", "system")


def _prefer_pyarrow_system_memory_pool() -> None:
    try:
        import pyarrow as pa
    except ImportError:
        return
    try:
        supported_backends = set(pa.supported_memory_backends())
    except (AttributeError, TypeError):
        return
    if "system" not in supported_backends:
        return
    try:
        pa.set_memory_pool(pa.system_memory_pool())
    except (AttributeError, RuntimeError, ValueError):
        return


_prefer_pyarrow_system_memory_pool()

