def _normalize_graph_max_points(value: Any) -> int:
    try:
        selected = int(value)
    except (TypeError, ValueError):
        return DEFAULT_GRAPH_MAX_POINTS
    if selected <= min(GRAPH_MAX_POINTS_OPTIONS):
        return min(GRAPH_MAX_POINTS_OPTIONS)
    if selected >= max(GRAPH_MAX_POINTS_OPTIONS):
        return max(GRAPH_MAX_POINTS_OPTIONS)
    return min(GRAPH_MAX_POINTS_OPTIONS, key=lambda option: abs(option - selected))


def _normalize_gain_y_min(value: Any) -> int:
    try:
        selected = int(value)
    except (TypeError, ValueError):
        return DEFAULT_GAIN_Y_MIN_DB
    return min(GAIN_Y_MIN_OPTIONS, key=lambda option: abs(option - selected))


def _normalize_gain_y_max(value: Any) -> int:
    try:
        selected = int(value)
    except (TypeError, ValueError):
        return DEFAULT_GAIN_Y_MAX_DB
    return min(GAIN_Y_MAX_OPTIONS, key=lambda option: abs(option - selected))


def _coerce_int_prefix(value: Any, default: int) -> int:
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, float) and np.isfinite(value):
        return int(value)
    match = re.search(r"-?\d+", str(value))
    if match:
        return int(match.group(0))
    return int(default)


def _normalize_phase_gain_mask(value: Any) -> str:
    text = str(value).strip()
    if text in PHASE_GAIN_MASK_OPTIONS:
        return text
    try:
        numeric = float(text.replace("dB", "").strip())
    except (TypeError, ValueError):
        return DEFAULT_PHASE_GAIN_MASK
    return min(PHASE_GAIN_MASK_OPTIONS[1:], key=lambda option: abs(float(option.split()[0]) - numeric))


def _phase_gain_mask_threshold_db(value: Any | None = None) -> float | None:
    label = _normalize_phase_gain_mask(
        st.session_state.get("phase_gain_mask", DEFAULT_PHASE_GAIN_MASK) if value is None else value
    )
    if label == "Off":
        return None
    return float(label.split()[0])


def _normalize_fir_fit_weighting_label(value: Any) -> str:
    text = str(value).strip()
    if text in FIR_FIT_WEIGHTING_OPTIONS:
        return text
    normalized = text.lower()
    if normalized in FIR_FIT_WEIGHTING_LABELS:
        return FIR_FIT_WEIGHTING_LABELS[normalized]
    return DEFAULT_FIR_FIT_WEIGHTING


def _fir_fit_weighting_config_value(value: Any) -> str:
    return FIR_FIT_WEIGHTING_VALUES[_normalize_fir_fit_weighting_label(value)]


