def _target_filter_registry_adapters() -> dict[str, dict[str, Any]]:
    adapters = getattr(ui_schema, "TARGET_FILTER_REGISTRY_ADAPTERS", None)
    return adapters if isinstance(adapters, dict) else _FALLBACK_TARGET_FILTER_REGISTRY_ADAPTERS


def _current_theme_mode() -> str:
    try:
        theme_type = str(st.context.theme.get("type") or "").lower()
    except (AttributeError, TypeError):
        theme_type = ""
    return "dark" if theme_type == "dark" else "light"


def _altair_chart_stretch(chart: Any) -> None:
    try:
        st.altair_chart(chart, width="stretch")
    except TypeError as exc:
        if "unexpected keyword argument 'width'" not in str(exc):
            raise
        st.altair_chart(chart)


def _prepared_download(label: str, prepare: Any, *, key: str, **kwargs: Any) -> None:
    st.download_button(display_text(label), data=prepare, key=key, on_click="ignore", **kwargs)


