SELECTION_PREVIEW_STATE_KEY = "_selection_preview_request"
SELECTION_PREVIEW_SUPPRESSED_TOKEN_KEY = "_selection_preview_suppressed_token"
SELECTION_PREVIEW_PAGE_KEY = "_selection_preview_active_page"


def _selection_preview_token(page: str, kind: str, record_id: str) -> str:
    return f"{page}|{kind}|{record_id}"


def _clear_selection_preview(*, suppress_current: bool = False) -> None:
    current = st.session_state.get(SELECTION_PREVIEW_STATE_KEY)
    if suppress_current and isinstance(current, dict):
        token = str(current.get("token", ""))
        if token:
            st.session_state[SELECTION_PREVIEW_SUPPRESSED_TOKEN_KEY] = token
    st.session_state.pop(SELECTION_PREVIEW_STATE_KEY, None)


def _sync_selection_preview_page(active_page: str) -> bool:
    previous_page = str(st.session_state.get(SELECTION_PREVIEW_PAGE_KEY, ""))
    page_changed = previous_page != active_page
    if page_changed:
        _clear_selection_preview()
        st.session_state[SELECTION_PREVIEW_PAGE_KEY] = active_page
    current = st.session_state.get(SELECTION_PREVIEW_STATE_KEY)
    if isinstance(current, dict) and str(current.get("kind", "")) in {
        "project",
        "linear_fir_preset",
    }:
        # Project and Linear FIR row selections remain editor/list
        # selections only. Their useful result is the normal Live Result.
        _clear_selection_preview()
    return page_changed


def _offer_selection_preview(
    *,
    page: str,
    kind: str,
    record_id: str,
    name: str,
    subtitle: str = "",
    source_key: str,
    activate_on_page_open: bool = True,
    activate_on_first_selection: bool = False,
) -> None:
    """Activate a read-only preview when a table selection changes.

    Only record identity and display metadata are stored. The renderer reloads
    the selected DB/preset data and never calls an Apply/Load state mutation.
    """
    record_id = str(record_id or "")
    if not record_id:
        return
    token = _selection_preview_token(page, kind, record_id)
    last_key = f"_selection_preview_last_{source_key}"
    has_seen_selection = last_key in st.session_state
    previous_token = str(st.session_state.get(last_key, ""))
    selection_changed = has_seen_selection and previous_token != token
    st.session_state[last_key] = token
    page_just_opened = bool(st.session_state.get("_selection_preview_page_just_opened", False))
    current = st.session_state.get(SELECTION_PREVIEW_STATE_KEY)
    current_token = str(current.get("token", "")) if isinstance(current, dict) else ""
    suppressed_token = str(st.session_state.get(SELECTION_PREVIEW_SUPPRESSED_TOKEN_KEY, ""))
    should_activate = (
        current_token == token
        or (activate_on_first_selection and not has_seen_selection)
        or (selection_changed and token != suppressed_token)
        or (activate_on_page_open and page_just_opened and token != suppressed_token)
    )
    if not should_activate:
        return
    st.session_state[SELECTION_PREVIEW_STATE_KEY] = {
        "page": page,
        "kind": kind,
        "record_id": record_id,
        "name": str(name or "Selected item"),
        "subtitle": str(subtitle or ""),
        "source_key": source_key,
        "token": token,
    }
    if suppressed_token and suppressed_token != token:
        st.session_state.pop(SELECTION_PREVIEW_SUPPRESSED_TOKEN_KEY, None)


def _response_max_frequency(response: SpeakerResponse | None) -> float | None:
    if response is None:
        return None
    frequency = np.asarray(response.frequency, dtype=float)
    valid = frequency[np.isfinite(frequency) & (frequency > 0)]
    if valid.size == 0:
        return None
    return float(np.max(valid))


def _limit_response_to_nyquist(
    response: SpeakerResponse | None,
    sample_rate: int,
) -> tuple[SpeakerResponse | None, int, float | None]:
    if response is None:
        return None, 0, None
    nyquist = float(sample_rate) / 2.0
    frequency = np.asarray(response.frequency, dtype=float)
    gain = np.asarray(response.gain_db, dtype=float)
    phase = None if response.phase_deg is None else np.asarray(response.phase_deg, dtype=float)
    finite = np.isfinite(frequency) & np.isfinite(gain)
    if phase is not None:
        finite &= np.isfinite(phase)
    max_frequency = _response_max_frequency(response)
    keep = finite & (frequency <= nyquist * (1.0 + 1e-6))
    removed = int(np.count_nonzero(finite & ~keep))
    if removed <= 0:
        return response, 0, max_frequency
    if not np.any(keep):
        return None, removed, max_frequency
    return (
        SpeakerResponse(
            frequency=frequency[keep].tolist(),
            gain_db=gain[keep].tolist(),
            phase_deg=None if phase is None else phase[keep].tolist(),
        ),
        removed,
        max_frequency,
    )


def _limit_response_to_nyquist_with_message(
    label: str,
    response: SpeakerResponse | None,
    sample_rate: int,
    source_name: str,
) -> tuple[SpeakerResponse | None, str | None]:
    limited, removed, max_frequency = _limit_response_to_nyquist(response, sample_rate)
    if removed <= 0:
        return limited, None
    source_text = f" ({source_name})" if source_name else ""
    max_text = f"{max_frequency:.0f} Hz" if max_frequency is not None else "unknown"
    return (
        limited,
        f"{label}{source_text}: 現在のSample rate {sample_rate / 1000:.0f} kHzでは"
        f"Nyquist {sample_rate / 2:.0f} Hzを超える{removed}行を読み込み対象外にしました"
        f"（元データ最大 {max_text}）。",
    )


