def _refresh_filter_registry_items_from_state(list_key: str) -> list[dict[str, Any]]:
    spec = FILTER_REGISTRY_ADAPTERS[list_key]
    if list_key == "linear_fir_items" and list_key not in st.session_state:
        backup = st.session_state.get("_linear_fir_domain_backup")
        if isinstance(backup, list) and backup:
            # Streamlit removes widget-associated keys while their page is
            # hidden. Linear FIR filters are domain state, so restore their
            # independent mirror before an absent key becomes an empty layout.
            st.session_state[list_key] = [dict(item) for item in backup if isinstance(item, dict)]
    if list_key == "iir_filter_items":
        raw_items = st.session_state.get(list_key)
        if isinstance(raw_items, list) and any(
            isinstance(item, dict) and "filter_order" not in item
            for item in raw_items
        ):
            normalized_items: list[dict[str, Any]] = []
            for idx, raw_item in enumerate(raw_items):
                if not isinstance(raw_item, dict):
                    continue
                item = dict(raw_item)
                kind = str(item.get("kind", "peq"))
                family = str(item.get("family", "butterworth"))
                raw_order = item.get("order", 2)
                try:
                    filter_order = parse_iir_order(raw_order)
                except (TypeError, ValueError):
                    filter_order = 2
                if kind not in {"high_pass", "low_pass"}:
                    filter_order = 2
                elif family == "linkwitz_riley" and filter_order not in IIR_LINKWITZ_RILEY_ORDERS:
                    filter_order = 4
                elif family == "variable_q":
                    filter_order = 2
                elif filter_order not in (range(1, 9) if family == "elliptic" else IIR_CROSSOVER_ORDERS):
                    filter_order = 2
                item["filter_order"] = filter_order
                item["order"] = idx
                normalized_items.append(item)
            st.session_state[list_key] = normalized_items
    ensure_list_state(list_key, item_type=spec["item_type"])
    items = list_items(list_key, include_disabled=True, sort_by_order=True)
    if list_key == "linear_fir_items":
        st.session_state["_linear_fir_domain_backup"] = [dict(item) for item in items]
    return items


def _items_for(list_key: str) -> list[dict[str, Any]]:
    return _refresh_filter_registry_items_from_state(list_key)


def _replace_registry_state(list_key: str, items: list[dict[str, Any]]) -> None:
    """Replace domain filters and invalidate their previous UI projection together."""
    spec = FILTER_REGISTRY_ADAPTERS[list_key]
    _clear_registry_widget_keys(list_key)
    st.session_state[list_key] = items
    ensure_list_state(list_key, item_type=spec["item_type"])
    st.session_state[spec["count_key"]] = len(items)


def _set_registry_items(list_key: str, raw_items: list[dict[str, Any]]) -> None:
    spec = FILTER_REGISTRY_ADAPTERS[list_key]
    prefix = str(spec["prefix"])
    items = [
        make_list_item(
            spec["item_type"],
            {"indexed_prefix": f"{prefix}_{idx}", **dict(raw_item)},
            item_id=f"{prefix}_{idx}",
            enabled=bool(raw_item.get("enabled", True)),
            order=idx,
        )
        for idx, raw_item in enumerate(raw_items)
    ]
    _replace_registry_state(list_key, items)
    if list_key == "linear_fir_items":
        # This path includes intentional layout changes. Selecting None writes
        # an empty backup, while Hi/Mid/Lo writes the new authoritative layout.
        st.session_state["_linear_fir_domain_backup"] = [dict(item) for item in items]
    _clear_indexed_group_widget_keys(prefix, count_hint=len(items) + 1)
    _invalidate_live_result_cache()


def _linear_fir_profile_from_items(items: list[dict[str, Any]]) -> str:
    has_hp = any(bool(item.get("enabled", True)) and str(item.get("mode", "")) == "hp" for item in items)
    has_lp = any(bool(item.get("enabled", True)) and str(item.get("mode", "")) == "lp" for item in items)
    if has_hp and has_lp:
        return "Mid"
    if has_hp:
        return "Hi"
    if has_lp:
        return "Lo"
    return "None"


def _normalize_linear_fir_profile(value: Any) -> str:
    text = str(value or "None")
    return text if text in LINEAR_FIR_PROFILE_OPTIONS else "None"


def _standalone_iir_only() -> bool:
    return (not bool(st.session_state.get("standalone_fir_enabled", True))
            and st.session_state.get("_active_context_assignment") is None
            and st.session_state.get("band_split_recipe") is None)


def _output_band_split_method_options():
    from utils.band_split_capability import IIR_METHODS
    return IIR_METHODS if _standalone_iir_only() else OUTPUT_BAND_SPLIT_METHODS


def _enforce_standalone_fir_capability() -> None:
    if not _standalone_iir_only():
        return
    from utils.band_split_capability import FIR_TO_IIR, convert_standalone_filters
    items = _items_for("linear_fir_items")
    converted = convert_standalone_filters(items, fir_enabled=False, inherited=False)
    if converted != items:
        _set_registry_items("linear_fir_items", converted)
        _invalidate_live_result_cache()
    for key in ("linear_fir_hp_response", "linear_fir_lp_response",
                "linear_fir_preset_hp_method", "linear_fir_preset_lp_method"):
        previous = st.session_state.get(key, "kaiser")
        method = FIR_TO_IIR.get(previous, previous)
        if method != previous or key not in st.session_state:
            st.session_state[key] = method
            st.session_state.pop(safe_widget_key("__sel_val_", key), None)
    memory = deepcopy(st.session_state.get("linear_fir_profile_memory", {}))
    for profile in memory.values():
        for item in profile.values():
            item["response"] = FIR_TO_IIR.get(item.get("response", "kaiser"), item.get("response"))
    st.session_state["linear_fir_profile_memory"] = memory


def _normalize_output_band_split_method(value: Any) -> str:
    method = str(value or "kaiser").strip().lower()
    if method == "lr2":
        return "linear_phase_lr2"
    if method == "lr4":
        return "kaiser"
    return method if method in OUTPUT_BAND_SPLIT_METHODS else "kaiser"


def _linear_fir_default_state_for_profile(profile: str) -> dict[str, dict[str, Any]]:
    profile = _normalize_linear_fir_profile(profile)
    if profile == "Hi":
        return {
            "hp": {
                "response": "kaiser",
                "fc": LINEAR_FIR_DEFAULT_HIGH_FC_HZ,
                "cycles": LINEAR_FIR_DEFAULT_CYCLES,
                "beta": LINEAR_FIR_DEFAULT_BETA,
            }
        }
    if profile == "Lo":
        return {
            "lp": {
                "response": "kaiser",
                "fc": LINEAR_FIR_DEFAULT_LOW_FC_HZ,
                "cycles": LINEAR_FIR_DEFAULT_CYCLES,
                "beta": LINEAR_FIR_DEFAULT_BETA,
            }
        }
    if profile == "Mid":
        return {
            "hp": {
                "response": "kaiser",
                "fc": LINEAR_FIR_DEFAULT_LOW_FC_HZ,
                "cycles": LINEAR_FIR_DEFAULT_CYCLES,
                "beta": LINEAR_FIR_DEFAULT_BETA,
            },
            "lp": {
                "response": "kaiser",
                "fc": LINEAR_FIR_DEFAULT_HIGH_FC_HZ,
                "cycles": LINEAR_FIR_DEFAULT_CYCLES,
                "beta": LINEAR_FIR_DEFAULT_BETA,
            },
        }
    return {}


def _linear_fir_profile_memory() -> dict[str, dict[str, dict[str, Any]]]:
    memory = st.session_state.setdefault("linear_fir_profile_memory", {})
    return memory if isinstance(memory, dict) else {}


def _linear_fir_current_ui_state() -> dict[str, dict[str, Any]]:
    return {
        "hp": {
            "response": _normalize_output_band_split_method(st.session_state.get("linear_fir_hp_response", "kaiser")),
            "fc": float(st.session_state.get("linear_fir_hp_fc", LINEAR_FIR_DEFAULT_HIGH_FC_HZ)),
            "cycles": float(st.session_state.get("linear_fir_hp_cycles", LINEAR_FIR_DEFAULT_CYCLES)),
            "beta": float(st.session_state.get("linear_fir_hp_beta", LINEAR_FIR_DEFAULT_BETA)),
            "overlap_oct": float(st.session_state.get("linear_fir_hp_overlap_oct", 0.0)),
            "acoustic_target": bool(st.session_state.get("linear_fir_hp_acoustic_target", False)),
            "lr2_auto_taps": any(item.get("mode") == "hp" and item.get("lr2_auto_taps", False) for item in _items_for("linear_fir_items")),
            "uses_base_crossover": any(item.get("mode") == "hp" and item.get("base_crossover_hz") is not None for item in _items_for("linear_fir_items")),
        },
        "lp": {
            "response": _normalize_output_band_split_method(st.session_state.get("linear_fir_lp_response", "kaiser")),
            "fc": float(st.session_state.get("linear_fir_lp_fc", LINEAR_FIR_DEFAULT_LOW_FC_HZ)),
            "cycles": float(st.session_state.get("linear_fir_lp_cycles", LINEAR_FIR_DEFAULT_CYCLES)),
            "beta": float(st.session_state.get("linear_fir_lp_beta", LINEAR_FIR_DEFAULT_BETA)),
            "overlap_oct": float(st.session_state.get("linear_fir_lp_overlap_oct", 0.0)),
            "acoustic_target": bool(st.session_state.get("linear_fir_lp_acoustic_target", False)),
            "lr2_auto_taps": any(item.get("mode") == "lp" and item.get("lr2_auto_taps", False) for item in _items_for("linear_fir_items")),
            "uses_base_crossover": any(item.get("mode") == "lp" and item.get("base_crossover_hz") is not None for item in _items_for("linear_fir_items")),
        },
    }


def _clear_linear_fir_parameter_widget_state() -> None:
    """Let restored profile values seed their widgets on the next render."""
    for settings_key in (
        "linear_fir_hp_fc",
        "linear_fir_hp_cycles",
        "linear_fir_hp_beta",
        "linear_fir_lp_fc",
        "linear_fir_lp_cycles",
        "linear_fir_lp_beta",
        "linear_fir_hp_overlap_oct",
        "linear_fir_lp_overlap_oct",
    ):
        st.session_state.pop(safe_widget_key("__num_val_", settings_key), None)
    for settings_key in ("linear_fir_hp_response", "linear_fir_lp_response"):
        st.session_state.pop(safe_widget_key("__sel_val_", settings_key), None)


def _normalize_linear_fir_mid_ui_state() -> bool:
    """Keep Mid's HP row on the low boundary and LP row on the high boundary."""
    current = _linear_fir_current_ui_state()
    if float(current["hp"]["fc"]) <= float(current["lp"]["fc"]):
        return False

    low_side = current["lp"]
    high_side = current["hp"]
    for field in ("fc", "cycles", "beta", "overlap_oct"):
        st.session_state[f"linear_fir_hp_{field}"] = float(low_side[field])
        st.session_state[f"linear_fir_lp_{field}"] = float(high_side[field])
    st.session_state["linear_fir_hp_response"] = str(low_side["response"])
    st.session_state["linear_fir_lp_response"] = str(high_side["response"])
    _clear_linear_fir_parameter_widget_state()
    return True


def _store_linear_fir_profile_state(profile: str) -> None:
    profile = _normalize_linear_fir_profile(profile)
    memory = _linear_fir_profile_memory()
    current = _linear_fir_current_ui_state()
    if profile == "Hi":
        memory[profile] = {"hp": current["hp"]}
    elif profile == "Lo":
        memory[profile] = {"lp": current["lp"]}
    elif profile == "Mid":
        memory[profile] = {"hp": current["hp"], "lp": current["lp"]}
    else:
        memory[profile] = {}
    st.session_state["linear_fir_profile_memory"] = memory


def _restore_linear_fir_profile_state(profile: str) -> None:
    profile = _normalize_linear_fir_profile(profile)
    memory = _linear_fir_profile_memory()
    state = memory.get(profile) or _linear_fir_default_state_for_profile(profile)
    hp_state = state.get("hp", {})
    lp_state = state.get("lp", {})
    for mode, saved in (("hp", hp_state), ("lp", lp_state)):
        st.session_state[f"linear_fir_{mode}_overlap_oct"] = float(saved.get("overlap_oct", 0.0))
        st.session_state[f"linear_fir_{mode}_acoustic_target"] = bool(saved.get("acoustic_target", False))
    if hp_state:
        st.session_state["linear_fir_hp_response"] = _normalize_output_band_split_method(hp_state.get("response", "kaiser"))
        st.session_state["linear_fir_hp_fc"] = float(hp_state.get("fc", LINEAR_FIR_DEFAULT_HIGH_FC_HZ))
        st.session_state["linear_fir_hp_cycles"] = float(hp_state.get("cycles", LINEAR_FIR_DEFAULT_CYCLES))
        st.session_state["linear_fir_hp_beta"] = float(hp_state.get("beta", LINEAR_FIR_DEFAULT_BETA))
    if lp_state:
        st.session_state["linear_fir_lp_response"] = _normalize_output_band_split_method(lp_state.get("response", "kaiser"))
        st.session_state["linear_fir_lp_fc"] = float(lp_state.get("fc", LINEAR_FIR_DEFAULT_LOW_FC_HZ))
        st.session_state["linear_fir_lp_cycles"] = float(lp_state.get("cycles", LINEAR_FIR_DEFAULT_CYCLES))
        st.session_state["linear_fir_lp_beta"] = float(lp_state.get("beta", LINEAR_FIR_DEFAULT_BETA))

    _enforce_standalone_fir_capability()


def _sync_linear_fir_profile_transition(profile: str) -> str:
    profile = _normalize_linear_fir_profile(profile)
    previous = _normalize_linear_fir_profile(st.session_state.get("linear_fir_active_profile", profile))
    if profile != previous:
        _store_linear_fir_profile_state(previous)
        _restore_linear_fir_profile_state(profile)
        _clear_linear_fir_parameter_widget_state()
        st.session_state["linear_fir_active_profile"] = profile
    else:
        st.session_state.setdefault("linear_fir_active_profile", profile)
    if profile == "Mid":
        _normalize_linear_fir_mid_ui_state()
    st.session_state["linear_fir_profile"] = profile
    return profile


def _linear_fir_first_item(items: list[dict[str, Any]], mode: str) -> dict[str, Any]:
    for item in items:
        if str(item.get("mode", "")) == mode:
            return item
    fc = LINEAR_FIR_DEFAULT_HIGH_FC_HZ if mode == "hp" else LINEAR_FIR_DEFAULT_LOW_FC_HZ
    return {
        "enabled": True,
        "mode": mode,
        "response": "kaiser",
        "fc": fc,
        "cycles": LINEAR_FIR_DEFAULT_CYCLES,
        "beta": LINEAR_FIR_DEFAULT_BETA,
    }


def _linear_fir_cycles_beta_from_item(item: dict[str, Any]) -> tuple[float, float]:
    if "cycles" in item and "beta" in item:
        return (
            max(float(item.get("cycles", LINEAR_FIR_DEFAULT_CYCLES)), 0.01),
            max(float(item.get("beta", LINEAR_FIR_DEFAULT_BETA)), 0.0),
        )
    return LINEAR_FIR_DEFAULT_CYCLES, LINEAR_FIR_DEFAULT_BETA


def _linear_fir_estimated_taps(sample_rate: float, fc: float, cycles: float) -> int | None:
    if not (np.isfinite(sample_rate) and np.isfinite(fc) and np.isfinite(cycles)):
        return None
    if sample_rate <= 0.0 or fc <= 0.0 or cycles <= 0.0:
        return None
    return multiway_kaiser_taps(sample_rate, fc, cycles)


def _linear_fir_tap_caption(label: str, sample_rate: float, fc: float, cycles: float) -> str:
    estimated_taps = _linear_fir_estimated_taps(sample_rate, fc, cycles)
    if estimated_taps is None:
        return f"{label}: estimated taps -"
    duration_ms = estimated_taps / float(sample_rate) * 1000.0
    return f"{label}: estimated {estimated_taps} taps / {duration_ms:.2f} ms"


def _linear_fir_mid_tap_caption(
    sample_rate: float,
    low_fc: float,
    low_cycles: float,
    high_fc: float,
    high_cycles: float,
) -> str:
    low_taps = _linear_fir_estimated_taps(sample_rate, low_fc, low_cycles)
    high_taps = _linear_fir_estimated_taps(sample_rate, high_fc, high_cycles)
    if low_taps is None or high_taps is None:
        return "Mid complement: estimated taps -"
    mid_taps = max(low_taps, high_taps)
    duration_ms = mid_taps / float(sample_rate) * 1000.0
    return (
        f"Mid complement: final {mid_taps} taps / {duration_ms:.2f} ms "
        f"(low-side LP raw {low_taps} -> centered {mid_taps}, "
        f"high-side HP raw {high_taps} -> centered {mid_taps})"
    )


def _linear_fir_raw_items_from_profile(profile: str) -> list[dict[str, Any]]:
    profile = _normalize_linear_fir_profile(profile)
    existing = _items_for("linear_fir_items")
    hp_item = _linear_fir_first_item(existing, "hp")
    lp_item = _linear_fir_first_item(existing, "lp")
    hp_cycles, hp_beta = _linear_fir_cycles_beta_from_item(hp_item)
    lp_cycles, lp_beta = _linear_fir_cycles_beta_from_item(lp_item)
    st.session_state.setdefault("linear_fir_hp_response", _normalize_output_band_split_method(hp_item.get("response", "kaiser")))
    st.session_state.setdefault("linear_fir_lp_response", _normalize_output_band_split_method(lp_item.get("response", "kaiser")))
    hp_raw = {
        "enabled": True,
        "mode": "hp",
        "response": _normalize_output_band_split_method(st.session_state.get("linear_fir_hp_response", hp_item.get("response", "kaiser"))),
        "fc": float(st.session_state.get("linear_fir_hp_fc", hp_item.get("fc", LINEAR_FIR_DEFAULT_HIGH_FC_HZ))),
        "cycles": float(st.session_state.get("linear_fir_hp_cycles", hp_cycles)),
        "beta": float(st.session_state.get("linear_fir_hp_beta", hp_beta)),
    }
    lp_raw = {
        "enabled": True,
        "mode": "lp",
        "response": _normalize_output_band_split_method(st.session_state.get("linear_fir_lp_response", lp_item.get("response", "kaiser"))),
        "fc": float(st.session_state.get("linear_fir_lp_fc", lp_item.get("fc", LINEAR_FIR_DEFAULT_LOW_FC_HZ))),
        "cycles": float(st.session_state.get("linear_fir_lp_cycles", lp_cycles)),
        "beta": float(st.session_state.get("linear_fir_lp_beta", lp_beta)),
    }
    for mode, raw, old in (("hp", hp_raw, hp_item), ("lp", lp_raw, lp_item)):
        overlap = float(st.session_state.get(f"linear_fir_{mode}_overlap_oct", old.get("overlap_oct", 0.0)))
        saved_boundary = _linear_fir_profile_memory().get(profile, {}).get(mode, {})
        raw["acoustic_target"] = bool(st.session_state.get(f"linear_fir_{mode}_acoustic_target", old.get("acoustic_target", False))) and raw["response"] not in {"kaiser", "through"}
        raw["lr2_auto_taps"] = bool(old.get("lr2_auto_taps", saved_boundary.get("lr2_auto_taps", False)))
        is_new = not any(item.get("mode") == mode for item in existing) and not saved_boundary
        if old.get("base_crossover_hz") is not None or overlap != 0.0 or is_new or saved_boundary.get("uses_base_crossover", False):
            from crossover_engine.filters import kaiser_overlap_edges_hz
            raw["base_crossover_hz"] = raw["fc"]
            raw["overlap_oct"] = overlap
            raw["fc"] = kaiser_overlap_edges_hz(raw["fc"], overlap)[1 if mode == "hp" else 0]
    if profile == "Hi":
        return [hp_raw]
    if profile == "Lo":
        return [lp_raw]
    if profile == "Mid":
        if float(hp_raw["fc"]) > float(lp_raw["fc"]):
            hp_raw, lp_raw = (
                {**lp_raw, "mode": "hp"},
                {**hp_raw, "mode": "lp"},
            )
        return [hp_raw, lp_raw]
    return []


def _linear_fir_items_semantic(items: list[dict[str, Any]]) -> list[tuple]:
    compact: list[tuple] = []
    seen: set[str] = set()
    for item in items:
        mode = "hp" if str(item.get("mode", "")) == "hp" else "lp"
        if mode in seen:
            continue
        seen.add(mode)
        compact.append(
            (
                mode,
                _normalize_output_band_split_method(item.get("response", "kaiser")),
                float(item.get("fc", LINEAR_FIR_DEFAULT_HIGH_FC_HZ if mode == "hp" else LINEAR_FIR_DEFAULT_LOW_FC_HZ)),
                *_linear_fir_cycles_beta_from_item(item),
                bool(item.get("enabled", True)),
                item.get("base_crossover_hz"),
                bool(item.get("lr2_auto_taps", False)),
                bool(item.get("acoustic_target", False)),
                float(item.get("overlap_oct", 0.0)),
            )
        )
    return compact


def _sync_linear_fir_registry_from_profile(profile: str) -> None:
    profile = _normalize_linear_fir_profile(profile)
    st.session_state["_linear_fir_domain_profile"] = profile
    next_items = _linear_fir_raw_items_from_profile(profile)
    if _linear_fir_items_semantic(_items_for("linear_fir_items")) != _linear_fir_items_semantic(next_items):
        _set_registry_items("linear_fir_items", next_items)


def _reset_linear_fir_profile() -> None:
    """Reset the active standalone profile through the existing registry path."""
    if st.session_state.get("_active_context_assignment") is not None:
        return
    profile = _normalize_linear_fir_profile(st.session_state.get("linear_fir_profile", "None"))
    if profile not in {"Hi", "Mid", "Lo"}:
        return
    memory = deepcopy(_linear_fir_profile_memory())
    memory.pop(profile, None)
    st.session_state["linear_fir_profile_memory"] = memory
    _set_registry_items("linear_fir_items", [])
    _restore_linear_fir_profile_state(profile)
    _clear_linear_fir_parameter_widget_state()
    _sync_linear_fir_registry_from_profile(profile)
    _invalidate_live_result_cache()
    st.session_state["_pending_live_result_refresh"] = True


def _on_linear_fir_profile_widget_change() -> None:
    """Commit an intentional layout selection before the following rerun."""
    widget_key = safe_widget_key("__sel_val_", "linear_fir_profile")
    profile = _normalize_linear_fir_profile(st.session_state.get(widget_key, "None"))
    profile = _sync_linear_fir_profile_transition(profile)
    _sync_linear_fir_registry_from_profile(profile)


def _seed_linear_fir_profile_widget_from_registry() -> str:
    """Project the persisted Linear FIR filters into the layout selector.

    ``linear_fir_items`` is the domain state. The selector is only a UI mirror,
    so unrelated reruns must never be allowed to write a stale ``None`` value
    back over valid filters. Intentional selector edits are committed first by
    ``_on_linear_fir_profile_widget_change``.
    """
    widget_key = safe_widget_key("__sel_val_", "linear_fir_profile")
    items = _items_for("linear_fir_items")
    inferred_profile = _linear_fir_profile_from_items(items)
    if inferred_profile == "None":
        profile = _normalize_linear_fir_profile(
            st.session_state.get("_linear_fir_domain_profile", inferred_profile)
        )
    else:
        profile = inferred_profile
        st.session_state["_linear_fir_domain_profile"] = profile
    widget_profile = _normalize_linear_fir_profile(st.session_state.get(widget_key, profile))
    if widget_key not in st.session_state or widget_profile != profile:
        _set_setting_and_widget("linear_fir_profile", profile, "__sel_val_")
        st.session_state["linear_fir_active_profile"] = profile
    else:
        st.session_state["linear_fir_profile"] = profile
    return profile


