def _reset_target_edit_state() -> None:
    for key in list(st.session_state.keys()):
        if key.startswith(
            (
                "target_gain_peq_",
                "target_gain_shelf_",
                "target_gain_linear_",
                "target_gain_tilt_",
                "target_gain_lo_tilt_",
                "target_phase_",
                "target_iir_",
            )
        ):
            st.session_state.pop(key, None)
    for list_key in (
        "target_gain_peq_items",
        "target_gain_shelf_items",
        "target_gain_linear_items",
        "target_gain_tilt_items",
        "target_gain_lo_tilt_items",
        "target_phase_peq_items",
        "target_phase_shelf_items",
        "target_phase_tilt_items",
        "target_phase_allpass_items",
        "target_iir_filter_items",
    ):
        _set_registry_items(list_key, [])
    st.session_state["target_gain_peq_count"] = 0
    st.session_state["target_gain_shelf_count"] = 0
    st.session_state["target_gain_linear_count"] = 0
    st.session_state["target_gain_tilt_count"] = 0
    st.session_state["target_gain_lo_tilt_count"] = 0
    _set_plain_setting_and_widget("target_gain_tilt_smoothing_oct", 1.0 / 3.0)
    st.session_state["target_phase_peq_count"] = 0
    st.session_state["target_phase_shelf_count"] = 0
    st.session_state["target_phase_tilt_count"] = 0
    _set_plain_setting_and_widget("target_phase_tilt_smoothing_oct", 1.0 / 3.0)
    st.session_state["target_phase_allpass_count"] = 0
    st.session_state["target_iir_filter_count"] = 0


def _apply_target_edit_payload_to_state(payload: Any) -> None:
    if not isinstance(payload, dict):
        return
    _reset_target_edit_state()
    _set_registry_items(
        "target_gain_peq_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 1.0)),
                "gain_db": float(item.get("gain_db", 0.0)),
            }
            for item in payload.get("gain_peq", [])
        ],
    )
    _set_registry_items(
        "target_gain_shelf_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "mode": str(item.get("mode", "low")),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 1.0)),
                "gain_db": float(item.get("gain_db", 0.0)),
            }
            for item in payload.get("gain_shelf", [])
        ],
    )
    _set_registry_items(
        "target_gain_linear_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "mode": "hp" if str(item.get("mode", "lp")) == "hp" else "lp",
                "response": "lr2",
                "fc": float(item.get("fc", 1000.0)),
                "cycles": float(item.get("cycles", 4.0)),
                "beta": float(item.get("beta", 12.0)),
            }
            for item in payload.get("gain_linear", [])
        ],
    )
    gain_tilt_payload = payload.get("gain_tilt", [])
    _set_registry_items(
        "target_gain_tilt_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "mode": "high",
                "f_start": float(item.get("f_start", 100.0)),
                "f_end": float(item.get("f_end", 20_000.0)),
                "slope_db_per_oct": float(item.get("slope_db_per_oct", 0.0)),
            }
            for item in gain_tilt_payload
            if str(item.get("mode", "high")) != "low"
        ],
    )
    _set_registry_items(
        "target_gain_lo_tilt_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "mode": "low",
                "f_start": float(item.get("f_start", 1.0)),
                "f_end": float(item.get("f_end", 1000.0)),
                "slope_db_per_oct": float(item.get("slope_db_per_oct", 0.0)),
            }
            for item in gain_tilt_payload
            if str(item.get("mode", "high")) == "low"
        ],
    )
    _set_plain_setting_and_widget(
        "target_gain_tilt_smoothing_oct",
        _nearest_auto_edge_option(float(payload.get("gain_tilt_smoothing_oct", 1.0 / 3.0))),
    )
    _set_registry_items(
        "target_phase_peq_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 1.0)),
                "phase_deg": float(item.get("phase_deg", 0.0)),
            }
            for item in payload.get("phase_peq", [])
        ],
    )
    _set_registry_items(
        "target_phase_shelf_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "mode": str(item.get("mode", "low")),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 1.0)),
                "phase_deg": float(item.get("phase_deg", 0.0)),
            }
            for item in payload.get("phase_shelf", [])
        ],
    )
    _set_registry_items(
        "target_phase_tilt_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "f_start": float(item.get("f_start", 100.0)),
                "f_end": float(item.get("f_end", 20_000.0)),
                "slope_deg_per_oct": float(item.get("slope_deg_per_oct", 0.0)),
            }
            for item in payload.get("phase_tilt", [])
        ],
    )
    _set_plain_setting_and_widget(
        "target_phase_tilt_smoothing_oct",
        _nearest_auto_edge_option(float(payload.get("phase_tilt_smoothing_oct", 1.0 / 3.0))),
    )
    _set_registry_items(
        "target_phase_allpass_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "polarity": str(item.get("polarity", "positive")),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 1.0)),
            }
            for item in payload.get("phase_allpass", [])
        ],
    )
    _set_registry_items(
        "target_iir_filter_items",
        [
            {
                "enabled": bool(item.get("enabled", True)),
                "kind": str(item.get("kind", "high_pass")),
                "fc": float(item.get("fc", 1000.0)),
                "q": float(item.get("q", 0.7)),
                "gain_db": float(item.get("gain_db", 0.0)),
                "family": str(item.get("family", "linkwitz_riley")),
                "ripple_db": float(item.get("ripple_db", 0.1)),
                "stop_db": float(item.get("stop_db", 80.0)),
                "filter_order": (
                    parse_iir_order(item.get("filter_order", 4))
                    if not (
                        str(item.get("kind", "high_pass")) == "allpass"
                        and str(item.get("allpass_preset", "lr4")) == "manual"
                        and parse_iir_order(item.get("filter_order", 4)) not in (1, 2)
                    )
                    else 2
                ),
                "allpass_preset": str(item.get("allpass_preset", "lr4")),
                "origin": "manual",
            }
            for item in payload.get("iir_filters", [])
            if str(item.get("kind", "high_pass")) in {"high_pass", "low_pass", "allpass"}
        ],
    )


