def _write_settings_payload(
    path: Path,
    config: DesignConfig,
    snapshot_name: str | None = None,
    raw_speaker_response: SpeakerResponse | None = None,
    raw_target_response: SpeakerResponse | None = None,
    mic_cal_response: SpeakerResponse | None = None,
) -> Path:
    path.parent.mkdir(exist_ok=True)
    path.write_text(
        json.dumps(
            _config_payload(
                config,
                snapshot_name=snapshot_name,
                raw_speaker_response=raw_speaker_response,
                raw_target_response=raw_target_response,
                mic_cal_response=mic_cal_response,
            ),
            ensure_ascii=False,
            indent=2,
            sort_keys=True,
        ),
        encoding="utf-8",
    )
    return path


def _save_current_settings(
    config: DesignConfig,
    raw_speaker_response: SpeakerResponse | None,
    raw_target_response: SpeakerResponse | None,
    mic_cal_response: SpeakerResponse | None,
) -> None:
    try:
        response_refs = _response_asset_refs_for_autosave(
            raw_speaker_response,
            raw_target_response,
            mic_cal_response,
        )
        settings_payload = _config_payload(
            config,
            raw_speaker_response=raw_speaker_response,
            raw_target_response=raw_target_response,
            mic_cal_response=mic_cal_response,
            response_refs=response_refs,
            embed_response_data=False,
        )
    except (OSError, ValueError, RuntimeError, sqlite3.Error) as exc:
        st.warning(ui_message('ui.f4cb3b70e79316', p0=f'{exc}'))
        settings_payload = _config_payload(
            config,
            raw_speaker_response=raw_speaker_response,
            raw_target_response=raw_target_response,
            mic_cal_response=mic_cal_response,
        )
    payload = settings_json(settings_payload)
    payload_digest = content_digest(payload)
    if st.session_state.get("_settings_autosave_digest") == payload_digest:
        return
    try:
        current = SETTINGS_FILE.read_text(encoding="utf-8") if SETTINGS_FILE.exists() else ""
        current_revision = file_revision(SETTINGS_FILE)
        expected_revision = str(st.session_state.get("_settings_file_revision", current_revision))
        if current != payload:
            written, next_revision = write_text_if_revision(
                SETTINGS_FILE,
                payload,
                expected_revision=expected_revision,
            )
            if not written:
                st.warning(
                    ui_message('ui.68a9677fa7df52')
                )
                return
            st.session_state["_settings_file_revision"] = next_revision
        else:
            st.session_state["_settings_file_revision"] = current_revision
        st.session_state["_settings_autosave_digest"] = payload_digest
    except OSError as exc:
        st.warning(ui_message('ui.322dd87fce9abc', p0=f'{exc}'))


def _response_asset_refs_for_autosave(
    raw_speaker_response: SpeakerResponse | None,
    raw_target_response: SpeakerResponse | None,
    mic_cal_response: SpeakerResponse | None,
) -> dict[str, dict[str, Any] | None]:
    current_state = st.session_state.get("_response_asset_refs")
    current_refs = dict(current_state) if isinstance(current_state, dict) else {}
    responses = {
        "speaker_response_raw": (raw_speaker_response, "speaker_input_raw"),
        "target_response_raw": (raw_target_response, "target_response_raw"),
        "mic_cal_response_raw": (mic_cal_response, "mic_calibration_raw"),
    }
    next_refs: dict[str, dict[str, Any] | None] = {}
    for key, (response, kind) in responses.items():
        if response is None:
            next_refs[key] = None
            continue
        current_ref = current_refs.get(key)
        digest = response_content_digest(response)
        if isinstance(current_ref, dict) and str(current_ref.get("content_sha256", "")) == digest:
            next_refs[key] = current_ref
            continue
        saved = save_response_asset(
            RESPONSE_ASSET_DB_FILE,
            response,
            kind=kind,
            current_ref=current_ref if isinstance(current_ref, dict) else None,
        )
        next_refs[key] = response_asset_ref_payload(saved)
    st.session_state["_response_asset_refs"] = next_refs
    return next_refs


