FIR_EQ_TASK_RESULT_PAGE = {
    "Gain": "Gain EQ",
    "Phase": "Phase EQ",
    "Auto Gain": "Auto Gain",
    "Auto Phase": "Auto Phase",
}


def _fir_eq_task_for_current_view() -> str:
    """Resolve the FIR preview stage before the editor widgets render.

    Streamlit writes the segmented-control widget value before this script
    reruns.  The persisted task can therefore still belong to the previous
    Gain/Phase view at the point where the Live Result stage is selected.
    """
    requested = str(st.session_state.get("_fir_eq_requested_task", ""))
    if requested in FIR_EQ_TASK_RESULT_PAGE:
        return requested
    task = str(st.session_state.get("fir_eq_task", "Gain"))
    view = str(
        st.session_state.get(
            "fir_eq_view_widget",
            st.session_state.get("fir_eq_view", "Gain"),
        )
    )
    if view not in {"Gain", "Phase"}:
        view = "Phase" if task in {"Phase", "Auto Phase"} else "Gain"
    if task not in {view, f"Auto {view}"}:
        task = view
    return task

SPEAKER_DB_SOURCE_ALIASES = {
    "User specs": "Speaker specs",
}


def _canonical_page_name(page: object) -> str:
    return str(page)


def _canonical_library_source(source: object) -> str:
    raw_source = str(source)
    return SPEAKER_DB_SOURCE_ALIASES.get(raw_source, raw_source)


def _navigate_to_page(page: str, **state_updates: Any) -> None:
    target_page = _canonical_page_name(page)
    if target_page == "Library" and _canonical_library_source(state_updates.get("speaker_db_source", "")) == "Speaker specs":
        target_page = "Speaker Specs"
    elif target_page == "Library" and state_updates.get("library_quick_measurement_type") == "Mic Calibration":
        target_page = "Mic Library"
    if target_page not in UI_PAGE_OPTIONS:
        return
    if "speaker_db_source" in state_updates:
        state_updates = {
            **state_updates,
            "speaker_db_source": _canonical_library_source(state_updates["speaker_db_source"]),
        }
    st.session_state["_pending_page_navigation"] = {
        "page": target_page,
        "state_updates": dict(state_updates),
    }


def _set_current_page(page: str, **state_updates: Any) -> None:
    target_page = _canonical_page_name(page)
    if target_page == "Library" and _canonical_library_source(state_updates.get("speaker_db_source", "")) == "Speaker specs":
        target_page = "Speaker Specs"
    elif target_page == "Library" and state_updates.get("library_quick_measurement_type") == "Mic Calibration":
        target_page = "Mic Library"
    if target_page not in UI_PAGE_OPTIONS:
        return
    if "speaker_db_source" in state_updates:
        state_updates = {
            **state_updates,
            "speaker_db_source": _canonical_library_source(state_updates["speaker_db_source"]),
        }
    st.session_state["active_page"] = target_page
    pending_updates: dict[str, Any] = {}
    try:
        st.session_state[safe_widget_key("__seg_val_", "active_page", "active_page_selector")] = target_page
    except st.errors.StreamlitAPIException:
        pending_updates.update(state_updates)
    for key, value in state_updates.items():
        try:
            st.session_state[key] = value
        except st.errors.StreamlitAPIException:
            pending_updates[key] = value
        if key == "speaker_db_source":
            try:
                st.session_state[safe_widget_key("__sel_val_", "speaker_db_source")] = value
                st.session_state["speaker_db_source_widget"] = value
            except st.errors.StreamlitAPIException:
                pending_updates[key] = value
    if pending_updates:
        st.session_state["_pending_page_navigation"] = {
            "page": target_page,
            "state_updates": pending_updates,
        }


def _apply_pending_page_navigation() -> None:
    pending = st.session_state.pop("_pending_page_navigation", None)
    if not isinstance(pending, dict):
        return
    page = str(pending.get("page", ""))
    state_updates = pending.get("state_updates", {})
    if not isinstance(state_updates, dict):
        state_updates = {}
    _set_current_page(page, **state_updates)
    target_page = _canonical_page_name(page)
    target_domain = next(
        (domain for domain, pages in _WORKSPACE_PAGES.items() if target_page in pages),
        "Speaker Package",
    )
    # This function runs before the header widgets are created, so all three
    # navigation keys can safely move together without a widget/state conflict.
    st.session_state["active_page_selector"] = target_page
    st.session_state["active_domain_selector"] = target_domain
    st.session_state[f"active_page_selector_{target_domain}"] = target_page


