def _compact_text(value: object, *, fallback: str = "未設定", max_len: int = 72) -> str:
    text = str(value or "").strip()
    if not text:
        return display_text(fallback)
    if len(text) <= max_len:
        return text
    return f"{text[: max_len - 1]}..."


