def _load_speaker_spec_to_state(record: SpeakerSpecRecord) -> None:
    numeric_keys = {
        "speaker_db_nominal_impedance_ohm",
        "speaker_db_fs_hz",
        "speaker_db_qts",
        "speaker_db_nominal_diameter_mm",
        "speaker_db_vas_l",
        "speaker_db_re_ohm",
        "speaker_db_le_mh",
        "speaker_db_sd_cm2",
        "speaker_db_xmax_mm",
        "speaker_db_spl_db",
        "speaker_db_pmax_w",
        "speaker_db_overall_diameter_mm",
        "speaker_db_baffle_cutout_mm",
        "speaker_db_mounting_depth_mm",
    }
    for key, value in {
        "speaker_db_brand": record.brand,
        "speaker_db_model": record.model,
        "speaker_db_driver_type": record.driver_type,
        "speaker_db_nominal_diameter_mm": record.nominal_diameter_mm,
        "speaker_db_nominal_impedance_ohm": record.nominal_impedance_ohm,
        "speaker_db_fs_hz": record.fs_hz,
        "speaker_db_qts": record.qts,
        "speaker_db_vas_l": record.vas_l,
        "speaker_db_re_ohm": record.re_ohm,
        "speaker_db_le_mh": record.le_mh,
        "speaker_db_sd_cm2": record.sd_cm2,
        "speaker_db_xmax_mm": record.xmax_mm,
        "speaker_db_spl_db": record.spl_db,
        "speaker_db_pmax_w": record.pmax_w,
        "speaker_db_overall_diameter_mm": record.overall_diameter_mm,
        "speaker_db_baffle_cutout_mm": record.baffle_cutout_mm,
        "speaker_db_mounting_depth_mm": record.mounting_depth_mm,
        "speaker_db_source_name": record.source_name,
        "speaker_db_source_url": record.source_url,
        "speaker_db_source_type": record.source_type,
        "speaker_db_redistributable": record.redistributable,
        "speaker_db_user_verified": record.user_verified,
        "speaker_db_note": record.note,
        "speaker_db_raw_text": record.raw_text,
    }.items():
        if key in numeric_keys:
            st.session_state[key] = "" if value is None else f"{float(value):g}"
        else:
            st.session_state[key] = value


def _project_metadata_defaults(
    record: SpeakerPackageRecord | None = None,
) -> dict[str, Any]:
    runtime_name = str(st.session_state.get("project_name", "") or "").strip()
    if runtime_name in {"", "Untitled Project"}:
        runtime_name = "Untitled Speaker Package"
    return {
        "name": record.name if record else runtime_name,
        "speaker_type": record.speaker_type if record else "",
        "side": record.side if record else "",
        "position": record.position if record else "",
        "tags": record.tags if record else "",
        "note": record.note if record else "",
    }


def _apply_config_to_state(config: DesignConfig) -> None:
    config = config.normalized()
    _set_design_condition_state(
        sample_rate=config.sample_rate,
        taps=config.taps,
        analysis_fft_size=config.analysis_fft_size,
    )
    st.session_state["window"] = config.window
    st.session_state["kaiser_beta"] = config.kaiser_beta
    st.session_state["chebyshev_attenuation_db"] = config.chebyshev_attenuation_db
    st.session_state["tukey_alpha"] = config.tukey_alpha
    st.session_state["dc_gain_normalize"] = config.dc_gain_normalize
    st.session_state["fir_auto_gain_enabled"] = config.fir_auto_gain_enabled
    for name, value in asdict(config.auto_gain_input_shaping).items():
        _set_setting_and_widget("auto_iir_shape_" + name, value,
                               "__chk_val_" if isinstance(value, bool) else "__num_val_")
    st.session_state.setdefault("project_name", "")
    st.session_state.setdefault("active_page", "Input")
    st.session_state["auto_phase_enabled"] = config.auto_eq.phase_enabled
    st.session_state["auto_gain_enabled"] = config.auto_eq.gain_enabled
    st.session_state["auto_f_min"] = config.auto_eq.f_min
    st.session_state["auto_f_max"] = config.auto_eq.f_max
    st.session_state["auto_smoothing_fraction"] = config.auto_eq.smoothing_fraction
    st.session_state["auto_edge_smooth_percent"] = config.auto_eq.edge_smooth_percent
    st.session_state["auto_gain_edge_smooth_oct"] = _nearest_auto_edge_option(config.auto_eq.gain_edge_smooth_oct)
    st.session_state["auto_phase_edge_smooth_oct"] = _nearest_auto_edge_option(config.auto_eq.phase_edge_smooth_oct)
    st.session_state["gain_tilt_smoothing_oct"] = _nearest_auto_edge_option(
        config.gain_tilt_smoothing_oct,
        GAIN_TILT_SMOOTH_OPTIONS,
    )
    st.session_state["phase_tilt_smoothing_oct"] = _nearest_auto_edge_option(config.phase_tilt_smoothing_oct)
    st.session_state["linear_fir_eq_mask_smoothing_oct"] = min(
        LINEAR_FIR_EQ_MASK_SMOOTHING_OPTIONS,
        key=lambda option: abs(float(option) - float(config.linear_fir_eq_mask_smoothing_oct)),
    )
    # Legacy state keys remain readable, but both Auto EQ modes are fixed at 100%.
    st.session_state["auto_phase_strength"] = 1.0
    # Legacy setting key retained for old Project compatibility. Auto Gain EQ
    # no longer exposes or applies Strength.
    st.session_state["auto_gain_strength"] = 1.0
    st.session_state["auto_max_boost"] = config.auto_eq.max_boost_db
    st.session_state["auto_max_cut"] = config.auto_eq.max_cut_db
    st.session_state.setdefault("speaker_url", "")
    st.session_state.setdefault("target_url", "")
    st.session_state.setdefault("driver_band_enabled", False)
    st.session_state.setdefault("driver_band_name", "")
    st.session_state.setdefault("driver_band_hpf_hz", 20.0)
    st.session_state.setdefault("driver_band_lpf_hz", 0.0)
    st.session_state.setdefault("apply_mic_cal", False)
    st.session_state.setdefault("speaker_polarity_invert", False)
    st.session_state.setdefault("speaker_phase_center_enabled", True)
    st.session_state.setdefault("speaker_phase_center_mode", DEFAULT_SPEAKER_PHASE_CENTER_MODE)
    st.session_state.setdefault("_speaker_phase_center_search_start_ms", None)
    st.session_state.setdefault("_speaker_phase_center_search_end_ms", None)
