def _auto_eq_sections_from_config(auto_eq: AutoEQConfig) -> tuple[list[AutoEQSection], list[AutoEQSection]]:
    if auto_eq.gain_sections or auto_eq.phase_sections:
        return list(auto_eq.gain_sections), list(auto_eq.phase_sections)

    legacy_sections = auto_eq.sections or [
        AutoEQSection(
            enabled=auto_eq.gain_enabled or auto_eq.phase_enabled,
            gain_enabled=auto_eq.gain_enabled,
            phase_enabled=auto_eq.phase_enabled,
            f_min=auto_eq.f_min,
            f_max=auto_eq.f_max,
            smoothing_fraction=auto_eq.smoothing_fraction,
            phase_strength=1.0,
            gain_strength=1.0,
            max_boost_db=auto_eq.max_boost_db,
            max_cut_db=auto_eq.max_cut_db,
            limit_mode=auto_eq.limit_mode,
            trend_smoothing_oct=0.0,
            post_limit_smoothing_fraction=0.0,
        )
    ]
    gain_sections: list[AutoEQSection] = []
    phase_sections: list[AutoEQSection] = []
    for section in legacy_sections:
        if section.gain_enabled:
            gain_sections.append(replace(section, gain_enabled=True, phase_enabled=False))
        if section.phase_enabled:
            phase_sections.append(replace(section, gain_enabled=False, phase_enabled=True))
    return gain_sections, phase_sections


def _normalize_loaded_auto_eq_overlaps(config: DesignConfig) -> tuple[DesignConfig, str]:
    """Load overlapping groups safely with every conflict participant OFF."""
    gain_sections, phase_sections = _auto_eq_sections_from_config(config.auto_eq)
    nyquist = float(config.sample_rate) / 2.0

    def normalize(sections: list[AutoEQSection]) -> tuple[list[AutoEQSection], bool]:
        normalized, conflict_indices = disable_overlapping_auto_eq_sections(sections, nyquist)
        return normalized, bool(conflict_indices)

    normalized_gain, gain_conflict = normalize(gain_sections)
    normalized_phase, phase_conflict = normalize(phase_sections)
    if not gain_conflict and not phase_conflict:
        return config, ""
    labels = [
        label
        for label, conflicted in (("Auto Gain EQ", gain_conflict), ("Auto Phase EQ", phase_conflict))
        if conflicted
    ]
    normalized_auto_eq = replace(
        config.auto_eq,
        sections=[],
        gain_sections=normalized_gain,
        phase_sections=normalized_phase,
    )
    warning = (
        f"{', '.join(labels)}に重複する有効範囲があったため、該当セクションをOFFで読み込みました。"
        "使用するセクションを確認してONにしてください。"
    )
    return replace(config, auto_eq=normalized_auto_eq), warning

def _ensure_initial_state() -> None:
    if (st.session_state.get("settings_initialized")
            and not any(key in st.session_state for key in SHAPING_UI_DEFAULTS)):
        # Initialize an already open pre-shaping session with current UI defaults.
        for key, default in SHAPING_UI_DEFAULTS.items():
            st.session_state[key] = default
    if "settings_initialized" not in st.session_state:
        if SETTINGS_FILE.exists():
            try:
                payload = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
                _apply_config_payload_to_state(payload)
                overlap_warning = st.session_state.pop("_auto_eq_load_overlap_warning", "")
                asset_warning = st.session_state.pop("_settings_asset_warning", "")
                st.session_state["_settings_notice"] = (
                    " / ".join(message for message in (overlap_warning, asset_warning) if message)
                    or f"前回の設定を復元しました: {SETTINGS_FILE}"
                )
            except (UnsupportedSettingsFileRevision, UnsupportedSettingsSchema) as exc:
                _apply_config_to_state(DEFAULT_CONFIG)
                if exc.reason == "too_old":
                    try:
                        quarantined = quarantine_unsupported_settings_file(
                            SETTINGS_FILE,
                            revision=exc.revision,
                        )
                        st.session_state["_settings_notice"] = (
                            f"古い設定ファイルは読み込まず、"
                            f"初期設定へクリアしました。退避先: {quarantined}"
                        )
                    except OSError as quarantine_exc:
                        st.session_state["_settings_notice"] = (
                            f"古い設定ファイルを読み込めませんでした。"
                            f"安全な退避にも失敗したため、元ファイルは変更していません: {quarantine_exc}"
                        )
                else:
                    st.session_state["_settings_notice"] = str(exc)
            except Exception as exc:
                _apply_config_to_state(DEFAULT_CONFIG)
                st.session_state["_settings_notice"] = f"前回の設定を復元できませんでした: {exc}"
        else:
            _apply_config_to_state(DEFAULT_CONFIG)
        st.session_state["_settings_file_revision"] = file_revision(SETTINGS_FILE)
        st.session_state["settings_initialized"] = True


def _state_default(key: str, value: Any) -> None:
    if key not in st.session_state:
        st.session_state[key] = value


def _session_state_heavy_entries(limit: int = 12) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for key, value in st.session_state.items():
        type_name = type(value).__name__
        size_text = ""
        score = 0
        if isinstance(value, pd.DataFrame):
            bytes_size = int(value.memory_usage(deep=True).sum())
            size_text = f"{bytes_size / 1024 / 1024:.2f} MB"
            score = bytes_size
        elif isinstance(value, np.ndarray):
            bytes_size = int(value.nbytes)
            size_text = f"{bytes_size / 1024 / 1024:.2f} MB"
            score = bytes_size
        elif isinstance(value, (list, tuple, dict)):
            try:
                length = len(value)
            except Exception:
                length = 0
            size_text = f"{length} item(s)"
            score = length
        if score:
            entries.append({"key": str(key), "type": type_name, "size": size_text, "_score": score})
    entries.sort(key=lambda item: int(item["_score"]), reverse=True)
    return [{key: value for key, value in item.items() if key != "_score"} for item in entries[:limit]]


def _cache_coordinator() -> CacheCoordinator:
    return CacheCoordinator(st.session_state)


def _invalidate_live_result_cache(event: CacheEvent = CacheEvent.DESIGN_CHANGED) -> None:
    _cache_coordinator().notify(event)


def _indexed_group_spec(prefix: str) -> tuple[str, dict[str, Any]] | tuple[None, None]:
    for list_key, spec in FILTER_REGISTRY_ADAPTERS.items():
        if spec["prefix"] == prefix:
            return list_key, spec
    return None, None


def _indexed_group_item_defaults(prefix: str) -> dict[str, Any]:
    _list_key, spec = _indexed_group_spec(prefix)
    if not spec:
        return {}
    return {item_field: default for item_field, (_indexed_field, default) in spec["fields"].items()}


def _indexed_group_count_key(prefix: str) -> str:
    _list_key, spec = _indexed_group_spec(prefix)
    return str(spec["count_key"]) if spec else f"{prefix}_count"


def _indexed_group_value(prefix: str, idx: int, item: dict[str, Any], spec: dict[str, Any], item_field: str) -> Any:
    return item.get(item_field)


def _format_eq_frequency_label(prefix: str, idx: int, item: dict[str, Any], spec: dict[str, Any] | None) -> str:
    if not spec:
        for field in ("fc", "f_start", "f_min"):
            if field in item:
                try:
                    return f"{float(item[field]):.0f} Hz"
                except Exception:
                    return str(item[field])
        return ""
    if "fc" in spec["fields"]:
        try:
            return f"{float(_indexed_group_value(prefix, idx, item, spec, 'fc')):.0f} Hz"
        except Exception:
            return ""
    start_field = "f_start" if "f_start" in spec["fields"] else "f_min" if "f_min" in spec["fields"] else ""
    end_field = "f_end" if "f_end" in spec["fields"] else "f_max" if "f_max" in spec["fields"] else ""
    if start_field:
        try:
            start = float(_indexed_group_value(prefix, idx, item, spec, start_field))
            if end_field:
                end = float(_indexed_group_value(prefix, idx, item, spec, end_field))
                if spec.get("item_type") == "auto_eq_section":
                    return auto_eq_range_label(start, end, nyquist_label="Nyq")
                end_text = "Nyq" if end == 0.0 else f"{end:.0f}"
                return f"{start:.0f}-{end_text} Hz"
            return f"{start:.0f} Hz"
        except Exception:
            return ""
    return ""


def _format_signed_value(value: Any, suffix: str) -> str:
    try:
        number = float(value)
    except Exception:
        return ""
    return f"{format_for_display(number, 1, signed=True)} {suffix}"


def _format_eq_detail_label(prefix: str, idx: int, item: dict[str, Any], spec: dict[str, Any] | None) -> str:
    if not spec:
        return ""
    details: list[str] = []
    if "mode" in spec["fields"]:
        mode = str(_indexed_group_value(prefix, idx, item, spec, "mode"))
        details.append(mode.title())
    if "polarity" in spec["fields"]:
        polarity = str(_indexed_group_value(prefix, idx, item, spec, "polarity"))
        details.append("Positive" if polarity == "positive" else "Negative")
    if "gain_db" in spec["fields"]:
        text = _format_signed_value(_indexed_group_value(prefix, idx, item, spec, "gain_db"), "dB")
        if text:
            details.append(text)
    if "phase_deg" in spec["fields"]:
        text = _format_signed_value(_indexed_group_value(prefix, idx, item, spec, "phase_deg"), "deg")
        if text:
            details.append(text)
    if "slope_db_per_oct" in spec["fields"]:
        text = _format_signed_value(_indexed_group_value(prefix, idx, item, spec, "slope_db_per_oct"), "dB/oct")
        if text:
            details.append(text)
    if "slope_deg_per_oct" in spec["fields"]:
        text = _format_signed_value(_indexed_group_value(prefix, idx, item, spec, "slope_deg_per_oct"), "deg/oct")
        if text:
            details.append(text)
    if spec.get("item_type") == "auto_eq_section":
        modes = []
        if bool(_indexed_group_value(prefix, idx, item, spec, "gain_enabled")):
            modes.append("Gain")
        if bool(_indexed_group_value(prefix, idx, item, spec, "phase_enabled")):
            modes.append("Phase")
        if modes:
            details.append("+".join(modes))
    return " | ".join(details)


def _indexed_group_label_from_item(prefix: str, item: dict[str, Any], idx: int) -> str:
    _list_key, spec = _indexed_group_spec(prefix)
    parts = [f"EQ{idx + 1}"]
    frequency_label = _format_eq_frequency_label(prefix, idx, item, spec)
    if frequency_label:
        parts.append(frequency_label)
    detail_label = _format_eq_detail_label(prefix, idx, item, spec)
    if detail_label:
        parts.append(detail_label)
    label = " | ".join(parts)
    enabled = bool(item.get("enabled", True))
    return label if enabled else f"{label} / OFF"


def _indexed_group_registry_items(prefix: str) -> tuple[str | None, dict[str, Any] | None, list[dict[str, Any]]]:
    list_key, spec = _indexed_group_spec(prefix)
    if not list_key or not spec:
        return None, None, []
    if list_key in REGISTRY_DIRECT_LIST_KEYS:
        ensure_list_state(list_key, item_type=spec["item_type"])
        return list_key, spec, list_items(list_key, include_disabled=True, sort_by_order=True)
    return list_key, spec, _refresh_filter_registry_items_from_state(list_key)


def _sort_indexed_group_by_numeric_field(prefix: str, field: str) -> None:
    list_key, spec, _items = _indexed_group_registry_items(prefix)
    if not list_key or not spec:
        return
    item_field = field
    if item_field not in spec["fields"]:
        for candidate, (indexed_field, _default) in spec["fields"].items():
            if indexed_field == field:
                item_field = candidate
                break
    _refresh_filter_registry_items_from_state(list_key)
    count_hint = int(st.session_state.get(spec["count_key"], len(_items)) or len(_items))
    before_ids = [str(item.get("id", "")) for item in list_items(list_key, include_disabled=True, sort_by_order=True)]
    sorted_items = sort_list_items(list_key, key_func=lambda item: float(item.get(item_field, 0.0) or 0.0))
    after_ids = [str(item.get("id", "")) for item in sorted(sorted_items, key=lambda item: int(item.get("order", 0) or 0))]
    if before_ids != after_ids:
        _clear_indexed_group_widget_keys(prefix, count_hint=count_hint)
        _invalidate_live_result_cache()


def _sort_indexed_group_by_type(prefix: str) -> None:
    list_key, _spec, items = _indexed_group_registry_items(prefix)
    if not list_key:
        return
    _refresh_filter_registry_items_from_state(list_key)
    count_hint = len(items)
    before_ids = [str(item.get("id", "")) for item in list_items(list_key, include_disabled=True, sort_by_order=True)]
    sorted_items = sort_list_items(list_key, key_func=lambda item: str(item.get("type", "")))
    after_ids = [str(item.get("id", "")) for item in sorted(sorted_items, key=lambda item: int(item.get("order", 0) or 0))]
    if before_ids != after_ids:
        _clear_indexed_group_widget_keys(prefix, count_hint=count_hint)
        _invalidate_live_result_cache()


def _reset_sort_select(settings_key: str, widget_key: str) -> None:
    st.session_state[settings_key] = "None"
    st.session_state[widget_key] = "None"


def _render_indexed_group_controls(
    prefix: str,
    label: str,
    *,
    auto_sort_field: str | None = None,
    selection_key: str | None = None,
    show_add: bool = True,
) -> int:
    list_key, spec, items = _indexed_group_registry_items(prefix)
    if not list_key or not spec:
        return int(st.session_state.get(_indexed_group_count_key(prefix), 0) or 0)
    count = len(items)
    control_cols = st.columns([0.18, 0.42, 0.27, 0.13], gap="small", vertical_alignment="bottom")
    with control_cols[0]:
        if show_add and localized_button(st, ui_message('ui.9fd728c66c9a25'), key=f"{prefix}_add", disabled=count >= list_policy(list_key).edit_limit, width="stretch"):
            added = add_list_item(
                list_key,
                item_type=spec["item_type"],
                values=_indexed_group_item_defaults(prefix),
            )
            if selection_key:
                _set_filter_editor_selection(selection_key, f"{prefix}:{added.get('id', '')}")
            st.session_state[f"{prefix}_expanded"] = True
            _clear_indexed_group_widget_keys(prefix, count_hint=count + 1)
            _invalidate_live_result_cache()
            st.rerun()
    with control_cols[2]:
        sort_settings_key = f"{prefix}_sort_mode"
        sort_widget_key = f"{prefix}_sort_mode_widget"
        sort_mode = selectbox_indexed(
            ui_message('ui.bec69036aa27e7'),
            ["None", "Frequency", "Type"],
            settings_key=sort_settings_key,
            default="None",
            key=sort_widget_key,
        format_func=localized_formatter(str))
    with control_cols[3]:
        st.caption(ui_message('ui.a5fee16d31821b', p0=f'{count}') if count == 1 else ui_message('ui.53528979ac6e7b', p0=f'{count}'))
    if count <= 0:
        with control_cols[1]:
            st.caption(ui_message('ui.c048f2e5dee62c', p0=f'{label}'))
    elif sort_mode != "None":
        if sort_mode == "Frequency":
            _sort_indexed_group_by_numeric_field(prefix, auto_sort_field or "fc")
        elif sort_mode == "Type":
            _sort_indexed_group_by_type(prefix)
        _reset_sort_select(sort_settings_key, sort_widget_key)
        st.rerun()
    return len(list_items(list_key, include_disabled=True, sort_by_order=True))


def _add_indexed_group_item(
    prefix: str,
    overrides: dict[str, Any] | None = None,
    *,
    selection_key: str | None = None,
) -> dict[str, Any] | None:
    list_key, spec, _items = _indexed_group_registry_items(prefix)
    if not list_key or not spec:
        return None
    if len(_items) >= list_policy(list_key).edit_limit:
        st.warning(ui_message('ui.1d5bd8130b6380', p0=f'{list_policy(list_key).edit_limit}'))
        return None
    values = _indexed_group_item_defaults(prefix)
    if overrides:
        values.update(overrides)
    added = add_list_item(list_key, item_type=spec["item_type"], values=values)
    if selection_key:
        _set_filter_editor_selection(selection_key, f"{prefix}:{added.get('id', '')}")
    _clear_indexed_group_widget_keys(prefix, count_hint=len(_items) + 1)
    _invalidate_live_result_cache()
    return added


def _frequency_sort_value(prefix: str, idx: int, item: dict[str, Any]) -> float:
    _list_key, spec = _indexed_group_spec(prefix)
    if not spec:
        return 0.0
    if "fc" in spec["fields"]:
        return float(_indexed_group_value(prefix, idx, item, spec, "fc") or 0.0)
    if "f_start" in spec["fields"]:
        return float(_indexed_group_value(prefix, idx, item, spec, "f_start") or 0.0)
    return 0.0


def _combined_eq_label(
    display_idx: int,
    filter_type: str,
    prefix: str,
    idx: int,
    item: dict[str, Any],
) -> str:
    _list_key, spec = _indexed_group_spec(prefix)
    frequency = _format_eq_frequency_label(prefix, idx, item, spec)
    details = _format_eq_detail_label(prefix, idx, item, spec)
    parts = [f"EQ{display_idx + 1}", filter_type]
    if frequency:
        parts.append(frequency)
    if details:
        parts.append(details)
    enabled = bool(item.get("enabled", True))
    label = " | ".join(parts)
    return label if enabled else f"{label} / OFF"


def _combined_row_key(row: tuple[str, str, int, dict[str, Any]]) -> str:
    _filter_type, prefix, idx, item = row
    item_id = str(item.get("id", ""))
    return f"{prefix}:{item_id or idx}"


def _sort_combined_one_frequency_rows(
    rows: list[tuple[str, str, int, dict[str, Any]]],
    sort_mode: str,
) -> list[tuple[str, str, int, dict[str, Any]]]:
    if sort_mode == "Frequency":
        return sorted(rows, key=lambda row: (_frequency_sort_value(row[1], row[2], row[3]), row[0], row[2]))
    if sort_mode == "Type":
        return sorted(rows, key=lambda row: (row[0], _frequency_sort_value(row[1], row[2], row[3]), row[2]))
    return rows


def _combined_one_frequency_rows(
    rows: list[tuple[str, str, int, dict[str, Any]]],
    sort_mode: str,
    *,
    cache_key: str | None = None,
    refresh: bool = False,
) -> list[tuple[str, str, int, dict[str, Any]]]:
    if cache_key is None:
        return rows if sort_mode == "None" else _sort_combined_one_frequency_rows(rows, sort_mode)

    order_key = f"{cache_key}_sort_order_keys"
    mode_key = f"{cache_key}_sort_order_mode"
    source_key = f"{cache_key}_sort_order_source_keys"
    current_keys = [_combined_row_key(row) for row in rows]
    cached_mode = st.session_state.get(mode_key)
    cached_source_keys = list(st.session_state.get(source_key, []))
    cached_order_keys = list(st.session_state.get(order_key, []))
    if sort_mode == "None":
        by_key = {_combined_row_key(row): row for row in rows}
        ordered = [by_key[key] for key in cached_order_keys if key in by_key]
        ordered.extend(row for row in rows if _combined_row_key(row) not in cached_order_keys)
        return ordered

    should_refresh = bool(refresh) or cached_mode != sort_mode or set(cached_source_keys) != set(current_keys)

    if should_refresh:
        ordered_rows = _sort_combined_one_frequency_rows(rows, sort_mode)
        ordered_keys = [_combined_row_key(row) for row in ordered_rows]
        st.session_state[order_key] = ordered_keys
        st.session_state[mode_key] = sort_mode
        st.session_state[source_key] = current_keys
        return ordered_rows

    by_key = {_combined_row_key(row): row for row in rows}
    ordered = [by_key[key] for key in cached_order_keys if key in by_key]
    ordered.extend(row for row in rows if _combined_row_key(row) not in cached_order_keys)
    return ordered


def _delete_eq_item_button(prefix: str, idx: int, key: str) -> None:
    list_key, _spec, items = _indexed_group_registry_items(prefix)
    if not list_key or idx < 0 or idx >= len(items):
        return
    if localized_button(st, ui_message('ui.e2d0a54968ead2'), key=key, help=ui_message('ui.25cc9122708c69')):
        old_count = len(items)
        delete_list_item(list_key, str(items[idx].get("id", "")))
        _clear_indexed_group_widget_keys(prefix, count_hint=old_count)
        _invalidate_live_result_cache()
        st.rerun()


def _eq_cell_text(text: str, *, muted: bool = False) -> None:
    class_name = "eq-cell-text eq-cell-muted" if muted else "eq-cell-text"
    st.markdown(f'<div class="{class_name}">{html.escape(text)}</div>', unsafe_allow_html=True)


def _format_plain_hz(value: Any) -> str:
    try:
        return f"{format_for_display(value, 0)} Hz"
    except Exception:
        return "0 Hz"


def _format_plain_q(value: Any) -> str:
    try:
        return f"Q {format_for_display(value, 1)}"
    except Exception:
        return "Q 1.0"


def _format_plain_signed(value: Any, unit: str) -> str:
    try:
        return f"{format_for_display(value, 1, signed=True)} {unit}"
    except Exception:
        return f"+0.0 {unit}"


def _summary_join(items: list[str], *, max_items: int = 2) -> str:
    if not items:
        return ""
    visible = items[:max_items]
    suffix = f" +{len(items) - max_items}" if len(items) > max_items else ""
    return ", ".join(visible) + suffix

def _card_state_key(card_id: str) -> str:
    return f"{CARD_STATE_PREFIX}{card_id}"


def _card_open_state_payload() -> dict[str, bool]:
    payload: dict[str, bool] = {}
    for key, value in st.session_state.items():
        key_text = str(key)
        if key_text.startswith(CARD_STATE_PREFIX) and not key_text.endswith("_toggle"):
            payload[key_text[len(CARD_STATE_PREFIX):]] = bool(value)
    return payload


def _apply_card_open_state_payload(payload: dict[str, Any]) -> None:
    for card_id, value in payload.items():
        if card_id == "live_analysis_gain_phase":
            # Start visible even for saved designs; retain this session's choice.
            st.session_state.setdefault(_card_state_key(card_id), True)
            continue
        if isinstance(card_id, str):
            st.session_state[_card_state_key(card_id)] = bool(value)


def _ui_card_open(
    card_id: str,
    title: str,
    *,
    summary: str = "",
    summary_prefix: str = "ON",
    empty_summary: str = "No active items",
    default_open: bool = True,
    description: str = "",
) -> bool:
    state_key = _card_state_key(card_id)
    if state_key not in st.session_state:
        st.session_state[state_key] = bool(default_open)
    opened = bool(st.session_state[state_key])
    header_cols = st.columns([0.09, 0.91], gap="small", vertical_alignment="center")
    with header_cols[0]:
        if localized_button(st, "▼" if opened else "▶", key=f"{CARD_TOGGLE_PREFIX}{card_id}", help=ui_message('ui.358f60870d7f41')):
            st.session_state[state_key] = not opened
            st.rerun()
    with header_cols[1]:
        prefix = f"{html.escape(display_text(summary_prefix))}: " if summary_prefix else ""
        summary_html = (
            f'<span class="eq-card-summary">{prefix}{html.escape(summary)}</span>'
            if summary
            else f'<span class="eq-card-summary muted">{html.escape(display_text(empty_summary))}</span>'
        )
        st.markdown(
            (
                '<div class="eq-card-title">'
                f'<span>{html.escape(title)}</span>'
                f'{summary_html}'
                '</div>'
            ),
            unsafe_allow_html=True,
        )
        if description:
            st.caption(description)
    return opened


def _enabled_registry_items(list_key: str) -> list[dict[str, Any]]:
    enabled_default = bool(_registry_field_default(list_key, "enabled", False))
    return [
        item
        for item in _items_for(list_key)
        if bool(_registry_current_item_value(list_key, item, "enabled", enabled_default))
    ]


def _gain_eq_on_summary(peq_list_key: str, shelf_list_key: str, lo_tilt_list_key: str | None = None) -> str:
    summaries: list[str] = []
    for item in _enabled_registry_items(peq_list_key):
        summaries.append(
            f"PEQ {_format_plain_hz(_registry_current_item_value(peq_list_key, item, 'fc', 1000.0))} "
            f"{_format_plain_signed(_registry_current_item_value(peq_list_key, item, 'gain_db', 0.0), 'dB')}"
        )
    for item in _enabled_registry_items(shelf_list_key):
        mode = str(_registry_current_item_value(shelf_list_key, item, "mode", "low"))
        filter_type = "Hi Shelf" if mode == "high" else "Lo Shelf"
        summaries.append(
            f"{filter_type} {_format_plain_hz(_registry_current_item_value(shelf_list_key, item, 'fc', 1000.0))} "
            f"{_format_plain_signed(_registry_current_item_value(shelf_list_key, item, 'gain_db', 0.0), 'dB')}"
        )
    if lo_tilt_list_key:
        for item in _enabled_registry_items(lo_tilt_list_key):
            summaries.append(
                "Lo Tilt "
                f"{_format_plain_hz(_registry_current_item_value(lo_tilt_list_key, item, 'f_start', 1.0))}-"
                f"{_format_plain_hz(_registry_current_item_value(lo_tilt_list_key, item, 'f_end', 1000.0))} "
                f"{_format_plain_signed(_registry_current_item_value(lo_tilt_list_key, item, 'slope_db_per_oct', 0.0), 'dB/oct')}"
            )
    return _summary_join(summaries)


def _phase_eq_on_summary(peq_list_key: str, shelf_list_key: str, allpass_list_key: str) -> str:
    summaries: list[str] = []
    for item in _enabled_registry_items(peq_list_key):
        summaries.append(
            f"PEQ {_format_plain_hz(_registry_current_item_value(peq_list_key, item, 'fc', 1000.0))} "
            f"{_format_plain_signed(_registry_current_item_value(peq_list_key, item, 'phase_deg', 0.0), 'deg')}"
        )
    for item in _enabled_registry_items(shelf_list_key):
        mode = str(_registry_current_item_value(shelf_list_key, item, "mode", "low"))
        filter_type = "Hi Shelf" if mode == "high" else "Lo Shelf"
        summaries.append(
            f"{filter_type} {_format_plain_hz(_registry_current_item_value(shelf_list_key, item, 'fc', 1000.0))} "
            f"{_format_plain_signed(_registry_current_item_value(shelf_list_key, item, 'phase_deg', 0.0), 'deg')}"
        )
    for item in _enabled_registry_items(allpass_list_key):
        polarity = str(_registry_current_item_value(allpass_list_key, item, "polarity", "positive"))
        polarity_text = "Min / 正" if polarity == "positive" else "Max / 逆"
        summaries.append(
            f"All Pass {_format_plain_hz(_registry_current_item_value(allpass_list_key, item, 'fc', 1000.0))} "
            f"{polarity_text}"
        )
    return _summary_join(summaries)


def _tilt_on_summary(list_key: str, *, unit: str) -> str:
    slope_key = "slope_db_per_oct" if unit == "dB/oct" else "slope_deg_per_oct"
    summaries: list[str] = []
    for item in _enabled_registry_items(list_key):
        slope = _registry_current_item_value(list_key, item, slope_key, 0.0)
        try:
            if abs(float(slope)) < 1e-9:
                continue
        except Exception:
            continue
        start = _registry_current_item_value(list_key, item, "f_start", 100.0)
        end = _registry_current_item_value(list_key, item, "f_end", 0.0)
        end_text = "Nyquist" if float(end or 0.0) == 0.0 else _format_plain_hz(end)
        summaries.append(
            f"{_format_plain_hz(start)}-{end_text} "
            f"{_format_plain_signed(slope, unit)}"
        )
    return _summary_join(summaries)


def _auto_eq_on_summary(*, mode: str) -> str:
    list_key = "auto_gain_section_items" if mode == "gain" else "auto_phase_section_items"
    summaries: list[str] = []
    for item in _enabled_registry_items(list_key):
        start = _registry_current_item_value(list_key, item, "f_min", 200.0)
        end = _registry_current_item_value(list_key, item, "f_max", 0.0)
        summaries.append(auto_eq_summary_range(float(start), float(end or 0.0)))
    return _summary_join(summaries)


