def _repair_generated_target_shift_visibility(ui_state: dict[str, Any]) -> dict[str, Any]:
    """Normalize a legacy lower-bound value; Auto never writes its estimate here."""

    mode = str(ui_state.get("target_gain_shift_mode", TARGET_GAIN_SHIFT_MODE_OPTIONS[0]))
    try:
        shift_db = float(ui_state.get("target_gain_shift_db", 0.0))
    except (TypeError, ValueError):
        shift_db = float("nan")
    generated_target = st.session_state.get("_restored_target_response_raw") is None
    stuck_at_lower_bound = (
        not np.isfinite(shift_db)
        or shift_db <= TARGET_GAIN_SHIFT_INPUT_MIN_DB + 1e-9
    )
    if mode != TARGET_GAIN_SHIFT_MODE_OPTIONS[0] or not generated_target or not stuck_at_lower_bound:
        return ui_state

    repaired = dict(ui_state)
    repaired["target_gain_shift_db"] = 0.0
    _set_setting_and_widget("target_gain_shift_db", 0.0, "__num_val_")
    return repaired


CONFIG_LOAD_TRANSIENT_STATE_DEFAULTS: dict[str, Any] = {
    # Layout-switch memory is useful while editing one Project, but must never
    # override a Project, snapshot, or preset that has just been loaded.
    "linear_fir_profile_memory": {},
}


def _reset_transient_ui_state_for_config_load() -> None:
    """Reset all non-persisted UI memories at one configuration-load boundary."""
    for state_key, default in CONFIG_LOAD_TRANSIENT_STATE_DEFAULTS.items():
        st.session_state[state_key] = dict(default) if isinstance(default, dict) else default
    st.session_state.pop("common_analysis_fft_size_draft", None)


def _set_design_condition_state(
    *,
    sample_rate: int | None = None,
    taps: int | None = None,
    analysis_fft_size: int | None = None,
) -> None:
    if sample_rate is not None:
        _set_setting_and_widget("sample_rate", int(sample_rate), "__sel_val_", "sample_rate_widget")
    if taps is not None:
        normalized_taps = _normalize_taps_value(int(taps))
        _set_setting_and_widget("taps", normalized_taps, "__num_val_", "taps_widget")
        st.session_state[safe_widget_key("__num_val_", "taps")] = normalized_taps
    if analysis_fft_size is not None:
        _set_setting_and_widget(
            "analysis_fft_size",
            int(analysis_fft_size),
            "__sel_val_",
            "analysis_fft_size_widget",
        )


def _coerce_sample_rate_state_value(value: Any) -> int:
    try:
        sample_rate = int(value)
    except (TypeError, ValueError):
        return int(DEFAULT_CONFIG.sample_rate)
    if sample_rate in {48_000, 96_000, 192_000}:
        return sample_rate
    return int(DEFAULT_CONFIG.sample_rate)


def _coerce_analysis_fft_state_value(value: Any, sample_rate: int) -> int:
    default = _recommended_analysis_fft_size(sample_rate)
    analysis_fft_size = _coerce_int_prefix(value, default)
    if analysis_fft_size in ANALYSIS_FFT_SIZE_OPTIONS:
        return analysis_fft_size
    return default


def _coerce_taps_state_value(value: Any) -> int:
    try:
        taps = int(value)
    except (TypeError, ValueError):
        taps = int(DEFAULT_CONFIG.taps)
    return _normalize_taps_value(taps)


def _sync_design_condition_widget_state() -> None:
    sample_rate = _coerce_sample_rate_state_value(
        st.session_state.get(
            "sample_rate_widget",
            st.session_state.get("sample_rate", DEFAULT_CONFIG.sample_rate),
        )
    )
    taps = _coerce_taps_state_value(
        st.session_state.get(
            "taps_widget",
            st.session_state.get("taps", DEFAULT_CONFIG.taps),
        )
    )
    analysis_fft_size = _coerce_analysis_fft_state_value(
        st.session_state.get(
            "analysis_fft_size_widget",
            st.session_state.get("analysis_fft_size", DEFAULT_CONFIG.analysis_fft_size),
        ),
        sample_rate,
    )
    _set_design_condition_state(
        sample_rate=sample_rate,
        taps=taps,
        analysis_fft_size=analysis_fft_size,
    )


def _reset_phase_center_defaults_for_input_file() -> None:
    _set_setting_and_widget("speaker_phase_center_enabled", True, "__chk_val_")
    _set_setting_and_widget("speaker_polarity_invert", False, "__chk_val_")
    _set_setting_and_widget(
        "speaker_phase_center_mode",
        DEFAULT_SPEAKER_PHASE_CENTER_MODE,
        "__rad_val_",
        "speaker_phase_center_mode_widget",
    )
    _set_setting_and_widget("speaker_phase_center_manual_offset_ms", 0.0, "__num_val_")
    st.session_state["_speaker_phase_center_detected_ms"] = 0.0
    st.session_state["_speaker_phase_center_search_start_ms"] = None
    st.session_state["_speaker_phase_center_search_end_ms"] = None


def _reset_phase_center_when_new_input_file(speaker_file: Any) -> None:
    if speaker_file is None:
        return
    file_bytes = speaker_file.getvalue()
    digest = hashlib.blake2b(file_bytes, digest_size=8).hexdigest()
    signature = f"{getattr(speaker_file, 'name', '')}:{len(file_bytes)}:{digest}"
    if st.session_state.get("_phase_center_input_file_signature") == signature:
        return
    st.session_state["_phase_center_input_file_signature"] = signature
    _reset_phase_center_defaults_for_input_file()


def _render_eq_card_header(
    title: str,
    prefix: str,
    idx: int,
    *,
    show_delete: bool = True,
) -> None:
    if not show_delete:
        _eq_cell_text(title)
        return
    header_cols = st.columns([0.78, 0.22])
    with header_cols[0]:
        _eq_cell_text(title)
    with header_cols[1]:
        _delete_eq_item_button(prefix, idx, f"{prefix}_{idx}_card_delete")


def _gain_eq_title(display_idx: int, filter_type: str, prefix: str, idx: int, *, enabled: bool = True) -> str:
    return eq_filter_card_title("Gain", display_idx, filter_type, enabled=enabled)


def _target_gain_eq_title(display_idx: int, filter_type: str, prefix: str, idx: int, *, enabled: bool = True) -> str:
    return eq_filter_card_title("Target Gain", display_idx, filter_type, enabled=enabled)


def _phase_eq_title(
    display_idx: int,
    filter_type: str,
    prefix: str,
    idx: int,
    item: dict[str, Any] | None = None,
    *,
    enabled: bool = True,
    polarity: str | None = None,
) -> str:
    detail = ""
    if prefix.endswith("phase_allpass"):
        selected_polarity = (
            polarity
            if polarity is not None
            else str(item.get("polarity", "positive"))
            if item is not None
            else _current_select_setting(f"{prefix}_{idx}_polarity", "positive")
        )
        detail = allpass_polarity_detail(str(selected_polarity))
    return eq_filter_card_title("Phase", display_idx, filter_type, detail=detail, enabled=enabled)


def _tilt_title(label: str, idx: int, prefix: str, unit: str, item: dict[str, Any] | None = None) -> str:
    list_key, spec = _indexed_group_spec(prefix)
    if item is not None:
        slope_key = "slope_db_per_oct" if unit == "dB/oct" else "slope_deg_per_oct"
        start = _registry_current_item_value(list_key, item, "f_start", 100.0) if list_key else item.get("f_start", 100.0)
        end = _registry_current_item_value(list_key, item, "f_end", 0.0) if list_key else item.get("f_end", 0.0)
        slope = _registry_current_item_value(list_key, item, slope_key, 0.0) if list_key else item.get(slope_key, 0.0)
    else:
        start_field = "f_start" if spec and "f_start" in spec.get("fields", {}) else "start"
        end_field = "f_end" if spec and "f_end" in spec.get("fields", {}) else "end"
        slope_field = (
            "slope_db_per_oct"
            if unit == "dB/oct" and spec and "slope_db_per_oct" in spec.get("fields", {})
            else "slope_deg_per_oct"
            if unit != "dB/oct" and spec and "slope_deg_per_oct" in spec.get("fields", {})
            else "slope"
        )
        start = _current_number_setting(f"{prefix}_{idx}_{start_field}", 100.0)
        end = _current_number_setting(f"{prefix}_{idx}_{end_field}", 0.0)
        slope = _current_number_setting(f"{prefix}_{idx}_{slope_field}", 0.0)
    end_text = "Nyquist" if float(end or 0.0) == 0.0 else _format_plain_hz(end)
    return f"{label}{idx + 1} | {_format_plain_hz(start)} - {end_text} | {_format_plain_signed(slope, unit)}"


def _filter_overview_value(item: dict[str, Any]) -> str:
    if "gain_db" in item:
        return f"{float(item.get('gain_db', 0.0)):+.1f} dB"
    if "phase_deg" in item:
        return f"{float(item.get('phase_deg', 0.0)):+.1f} deg"
    if "slope_db_per_oct" in item:
        return f"{float(item.get('slope_db_per_oct', 0.0)):+.1f} dB/oct"
    if "slope_deg_per_oct" in item:
        return f"{float(item.get('slope_deg_per_oct', 0.0)):+.1f} deg/oct"
    if "polarity" in item:
        return "Min / 正" if str(item.get("polarity", "positive")) == "positive" else "Max / 逆"
    return "-"


def _iir_overview_q(item: dict[str, Any]) -> str:
    kind = str(item.get("kind", "peq"))
    if kind not in {"peq", "high_shelf", "low_shelf", "allpass"}:
        return "-"
    if kind == "allpass":
        preset = str(item.get("allpass_preset", "manual"))
        order = parse_iir_order(item.get("filter_order", item.get("order", 2)) or 2)
        if preset != "manual" or order == 1:
            return "-"
    return f"{float(item.get('q', 0.7)):.1f}"


def _live_registry_item(list_key: str, item: dict[str, Any]) -> dict[str, Any]:
    """Return one derived snapshot with rendered widget values taking priority."""
    snapshot = dict(item)
    spec = FILTER_REGISTRY_ADAPTERS.get(list_key, {})
    for field, field_spec in spec.get("fields", {}).items():
        default = field_spec[1] if isinstance(field_spec, tuple) and len(field_spec) >= 2 else snapshot.get(field)
        snapshot[field] = _registry_current_item_value(list_key, item, field, default)
    snapshot["enabled"] = bool(_registry_current_item_value(list_key, item, "enabled", snapshot.get("enabled", True)))
    return snapshot


def _set_filter_editor_selection(selection_key: str, option_id: str) -> None:
    st.session_state[selection_key] = option_id


def _queue_result_detail_view_restore() -> None:
    """Preserve the right-pane selection across editor actions that rerun early."""

    value = _current_plain_widget_option("result_detail_view", RESULT_DETAIL_VIEWS, "Error")
    st.session_state["result_detail_view"] = value
    st.session_state["_pending_result_detail_view_restore"] = value


def _apply_filter_bulk_action(entries: list[tuple[str, str]], action: str) -> int:
    """Mutate only the displayed IDs, keeping registry identity and EQ rules."""
    if action not in {"All ON", "All OFF", "All Clear"}:
        raise ValueError(action)
    grouped: dict[str, set[str]] = {}
    for list_key, item_id in entries:
        if list_key and item_id:
            grouped.setdefault(list_key, set()).add(item_id)
    blocked = 0
    for list_key, ids in grouped.items():
        items = _items_for(list_key)
        for item in items:
            item_id = str(item.get("id", ""))
            if item_id not in ids:
                continue
            if action == "All Clear":
                delete_list_item(list_key, item_id)
            else:
                update_list_item(list_key, item_id, {"enabled": action == "All ON"})
                if action == "All ON":
                    _disable_overlapping_auto_eq_items_for_winner(list_key, item_id)
        remaining = list_items(list_key, include_disabled=True, sort_by_order=True)
        if action == "All ON":
            blocked += sum(str(item.get("id", "")) in ids and not item.get("enabled", True) for item in remaining)
        spec = FILTER_REGISTRY_ADAPTERS[list_key]
        st.session_state[spec["count_key"]] = len(remaining)
        _clear_registry_widget_keys(list_key)
        _clear_indexed_group_widget_keys(str(spec["prefix"]), count_hint=len(items) + 1)
    _invalidate_live_result_cache()
    _queue_result_detail_view_restore()
    return blocked


def _render_filter_bulk_controls(entries: list[tuple[str, str]], *, key: str) -> None:
    entries = [(list_key, item_id) for list_key, item_id in entries if list_key and item_id]
    with st.container(horizontal=True, gap="small"):
        for action in ("All ON", "All OFF", "All Clear"):
            if st.button(action, key=f"{key}_bulk_{action.replace(' ', '_')}", disabled=not entries,
                         help=ui_message('ui.dcf96e883d0a59')):
                blocked = _apply_filter_bulk_action(entries, action)
                st.session_state[f"{key}_bulk_notice"] = (
                    f"{action}：Auto EQの区間重複により{blocked}件はOFFです（一覧の後の区間を優先）。"
                    if blocked else f"{action}をこの一覧に適用しました。"
                )
                st.rerun()
    notice = st.session_state.pop(f"{key}_bulk_notice", None)
    if notice:
        st.caption(notice)


def _render_filter_overview_selector(
    rows: list[tuple[str, str, int, dict[str, Any]]],
    *,
    key: str,
    include_q: bool = False,
    identifiers: list[str] | None = None,
    show_table: bool = True,
) -> tuple[str, str, int, dict[str, Any]] | None:
    """Render one group-local filter table and resolve its selected editor row."""
    if show_table:
        _render_filter_bulk_controls([
            (_indexed_group_spec(prefix)[0], str(item.get("id", "")))
            for _, prefix, _, item in rows
        ], key=key)
    if not rows:
        if show_table:
            st.caption(ui_message('ui.40fdc03b48099d'))
        return None
    option_ids: list[str] = []
    lookup: dict[str, tuple[str, str, int, dict[str, Any]]] = {}
    records: list[dict[str, Any]] = []
    for row in rows:
        filter_type, prefix, idx, stored_item = row
        option_id = f"{prefix}:{stored_item.get('id', idx)}"
        option_ids.append(option_id)
        lookup[option_id] = row
        list_key, _spec = _indexed_group_spec(prefix)
        item = _live_registry_item(list_key, stored_item) if list_key else dict(stored_item)
        start = float(item.get("fc", item.get("f_start", 0.0)) or 0.0)
        end_value = item.get("f_end")
        frequency = _format_plain_hz(start)
        if end_value is not None:
            frequency += f" - {'Nyquist' if float(end_value or 0.0) == 0.0 else _format_plain_hz(end_value)}"
        record = {
            "#": (
                identifiers[len(records)]
                if identifiers is not None and len(records) < len(identifiers)
                else len(records) + 1
            ),
            "ON": bool(item.get("enabled", True)),
            "Type": filter_type,
            "Phase": _filter_phase_abbreviation(prefix, item),
            "Frequency": frequency,
            "Value": _filter_overview_value(item),
        }
        if include_q:
            record["Q"] = _iir_overview_q(item)
        records.append(record)
    selected = str(st.session_state.get(key, ""))
    if selected not in option_ids:
        selected = option_ids[0]
        st.session_state[key] = selected
    if show_table:
        selected = _single_row_table_selector(
            pd.DataFrame(records),
            option_ids,
            selected_state_key=key,
            table_key=f"{key}_table",
            height=min(245, 36 + 35 * len(records)),
        )
    _set_filter_editor_selection(key, selected)
    selected_row = lookup[selected]
    _filter_type, prefix, idx, item = selected_row
    list_key, _spec = _indexed_group_spec(prefix)
    item_id = str(item.get("id", ""))
    if show_table:
        with st.container(horizontal=True, gap="small"):
            if localized_button(st, ui_message('ui.02cdaabfca805d'), key=f"{key}_duplicate", disabled=not list_key or not item_id or len(st.session_state.get(list_key, [])) >= list_policy(list_key).edit_limit):
                duplicated = duplicate_list_item(list_key, item_id)
                if duplicated is not None:
                    duplicated_option = f"{prefix}:{duplicated.get('id', '')}"
                    _set_filter_editor_selection(key, duplicated_option)
                _clear_indexed_group_widget_keys(prefix, count_hint=len(rows) + 1)
                _invalidate_live_result_cache()
                _queue_result_detail_view_restore()
                st.rerun()
            if localized_button(st, ui_message('ui.e2d0a54968ead2'), key=f"{key}_delete", disabled=not list_key or not item_id):
                delete_list_item(list_key, item_id)
                remaining_options = [option for option in option_ids if option != selected]
                next_option = remaining_options[min(idx, len(remaining_options) - 1)] if remaining_options else ""
                _set_filter_editor_selection(key, next_option)
                _clear_indexed_group_widget_keys(prefix, count_hint=len(rows))
                _invalidate_live_result_cache()
                _queue_result_detail_view_restore()
                st.rerun()
    return selected_row


def _filter_phase_abbreviation(prefix: str, item: dict[str, Any]) -> str:
    """Describe the realization phase family without changing filter behavior."""
    if prefix in {"iir_filter", "target_iir_filter"}:
        return "Max." if str(item.get("kind", "")) == "allpass" else "Min."
    return "Lin."


def _single_row_table_selector(
    data: pd.DataFrame,
    option_ids: list[str],
    *,
    selected_state_key: str,
    table_key: str,
    height: int,
    default_id: str = "",
    column_config: dict[str, Any] | None = None,
) -> str:
    return shared_single_row_table_selector(data, option_ids, selected_state_key=selected_state_key,
        table_key=table_key, height=height, default_id=default_id, column_config=column_config)


FIR_EQ_ADD_TYPE_OPTIONS = (
    "Gain · PEQ",
    "Gain · High Shelf",
    "Gain · Low Shelf",
    "Gain · High Tilt",
    "Gain · Low Tilt",
    "Phase · PEQ",
    "Phase · High Shelf",
    "Phase · Low Shelf",
    "Phase · All Pass",
    "Phase · Tilt",
    "Auto Gain · Section",
    "Auto Phase · Section",
)


def _fir_eq_item_frequency(item: dict[str, Any]) -> str:
    if "fc" in item:
        return _format_plain_hz(float(item.get("fc", 0.0) or 0.0))
    start = float(item.get("f_min", item.get("f_start", 0.0)) or 0.0)
    end = float(item.get("f_max", item.get("f_end", 0.0)) or 0.0)
    return f"{_format_plain_hz(start)} – {'Nyquist' if end == 0.0 else _format_plain_hz(end)}"


def _fir_eq_item_detail(item: dict[str, Any]) -> str:
    if "q" in item:
        return f"Q {float(item.get('q', 0.0) or 0.0):g}"
    if "smoothing_fraction" in item:
        smoothing = float(item.get("smoothing_fraction", 0.0) or 0.0)
        return NO_SMOOTHING_LABEL if smoothing == 0.0 else f"1/{int(smoothing)} oct"
    if "cycles" in item:
        return f"{float(item.get('cycles', 0.0) or 0.0):g} cycles"
    return "-"


def _fir_eq_overview_data(
    nyquist: float,
    *,
    view: str = "Gain",
) -> tuple[pd.DataFrame, list[str], dict[str, dict[str, str]]]:
    del nyquist  # Values are already clipped by the registry collectors.
    records: list[dict[str, Any]] = []
    option_ids: list[str] = []
    metadata: dict[str, dict[str, str]] = {}
    visible_tasks = ("Gain", "Auto Gain") if view == "Gain" else ("Phase", "Auto Phase")
    stage_counts = {task: 0 for task in visible_tasks}

    groups = (
        ("Gain", "gain_peq", "PEQ", "PEQ / Shelf", "gain_eq_selected_filter"),
        ("Gain", "gain_shelf", "Shelf", "PEQ / Shelf", "gain_eq_selected_filter"),
        ("Gain", "gain_tilt", "High Tilt", "Tilt", "gain_tilt_selected_filter"),
        ("Gain", "gain_lo_tilt", "Low Tilt", "Tilt", "gain_tilt_selected_filter"),
        ("Phase", "phase_peq", "PEQ", "PEQ / Shelf / All-pass", "phase_eq_selected_filter"),
        ("Phase", "phase_shelf", "Shelf", "PEQ / Shelf / All-pass", "phase_eq_selected_filter"),
        ("Phase", "phase_allpass", "All Pass", "PEQ / Shelf / All-pass", "phase_eq_selected_filter"),
        ("Phase", "phase_tilt", "Tilt", "Tilt", "phase_tilt_selected_filter"),
        ("Auto Gain", "auto_gain_section", "Section", "", "auto_gain_section_selected_item"),
        ("Auto Phase", "auto_phase_section", "Section", "", "auto_phase_section_selected_item"),
    )
    for task, prefix, base_type, edit_group, selection_key in groups:
        if task not in visible_tasks:
            continue
        list_key, _spec, items = _indexed_group_registry_items(prefix)
        for index, stored_item in enumerate(items, start=1):
            item = _live_registry_item(list_key, stored_item) if list_key else dict(stored_item)
            item_id = str(stored_item.get("id", f"{prefix}_{index - 1}"))
            option_id = f"{prefix}:{item_id}"
            filter_type = base_type
            mode = str(item.get("mode", ""))
            if prefix in {"gain_shelf", "phase_shelf"}:
                filter_type = "High Shelf" if mode == "high" else "Low Shelf"
            option_ids.append(option_id)
            stage_counts[task] += 1
            metadata[option_id] = {
                "task": task,
                "edit_group": edit_group,
                "prefix": prefix,
                "list_key": str(list_key or ""),
                "item_id": item_id,
                "selection_key": selection_key,
                "selection_value": (
                    item_id if prefix.startswith("auto_") else f"{prefix}:{item_id}"
                ),
            }
            value = _filter_overview_value(item)
            records.append({
                "Stage": task,
                "#": str(index),
                "ON": "ON" if bool(item.get("enabled", True)) else "OFF",
                "Type": filter_type,
                "Phase": "Min." if task == "Auto Gain" and item.get("gain_phase_mode", "lin") == "min" else "Lin.",
                "Frequency": _fir_eq_item_frequency(item),
                "Value": value,
                "Q / Smoothing": _fir_eq_item_detail(item),
            })

    for task, count in stage_counts.items():
        if count:
            continue
        option_id = f"empty:{task}"
        option_ids.append(option_id)
        metadata[option_id] = {
            "task": task,
            "edit_group": "",
            "prefix": "",
            "list_key": "",
            "item_id": "",
            "selection_key": "",
            "selection_value": "",
        }
        records.append({
            "Stage": task,
            "#": "-",
            "ON": "-",
            "Type": "No filters",
            "Phase": "-",
            "Frequency": "-",
            "Value": "-",
            "Q / Smoothing": "-",
        })
    return pd.DataFrame(records), option_ids, metadata


def _add_fir_eq_item(add_type: str, nyquist: float) -> tuple[str, str]:
    mapping: dict[str, tuple[str, dict[str, Any], str, str]] = {
        "Gain · PEQ": ("gain_peq", {}, "Gain", "gain_eq_selected_filter"),
        "Gain · High Shelf": ("gain_shelf", {"mode": "high"}, "Gain", "gain_eq_selected_filter"),
        "Gain · Low Shelf": ("gain_shelf", {"mode": "low"}, "Gain", "gain_eq_selected_filter"),
        "Gain · High Tilt": (
            "gain_tilt", {"mode": "high", "f_start": 100.0, "f_end": min(20_000.0, nyquist)},
            "Gain", "gain_tilt_selected_filter",
        ),
        "Gain · Low Tilt": (
            "gain_lo_tilt", {"mode": "low", "f_start": 1.0, "f_end": min(1000.0, nyquist)},
            "Gain", "gain_tilt_selected_filter",
        ),
        "Phase · PEQ": ("phase_peq", {}, "Phase", "phase_eq_selected_filter"),
        "Phase · High Shelf": ("phase_shelf", {"mode": "high"}, "Phase", "phase_eq_selected_filter"),
        "Phase · Low Shelf": ("phase_shelf", {"mode": "low"}, "Phase", "phase_eq_selected_filter"),
        "Phase · All Pass": ("phase_allpass", {}, "Phase", "phase_eq_selected_filter"),
        "Phase · Tilt": (
            "phase_tilt", {"f_start": 100.0, "f_end": min(20_000.0, nyquist)},
            "Phase", "phase_tilt_selected_filter",
        ),
        "Auto Gain · Section": (
            "auto_gain_section", {"enabled": False}, "Auto Gain", "auto_gain_section_selected_item",
        ),
        "Auto Phase · Section": (
            "auto_phase_section", {"enabled": False}, "Auto Phase", "auto_phase_section_selected_item",
        ),
    }
    prefix, overrides, task, selection_key = mapping[add_type]
    added = _add_indexed_group_item(prefix, overrides)
    if added is None:
        return "", task
    item_id = str(added.get("id", ""))
    selection_value = item_id if prefix.startswith("auto_") else f"{prefix}:{item_id}"
    st.session_state[selection_key] = selection_value
    return f"{prefix}:{item_id}", task


def _duplicate_fir_eq_item(selected: dict[str, str]) -> None:
    list_key = str(selected.get("list_key", ""))
    prefix = str(selected.get("prefix", ""))
    item_id = str(selected.get("item_id", ""))
    if not list_key or not prefix or not item_id:
        return
    duplicated = duplicate_list_item(list_key, item_id)
    if duplicated is None:
        return
    duplicated_id = str(duplicated.get("id", ""))
    if prefix.startswith("auto_"):
        update_list_item(list_key, duplicated_id, {"enabled": False})
    option_id = f"{prefix}:{duplicated_id}"
    selection_key = str(selected.get("selection_key", ""))
    if selection_key:
        st.session_state[selection_key] = duplicated_id if prefix.startswith("auto_") else option_id
    st.session_state["fir_eq_overview_selected"] = option_id
    st.session_state["fir_eq_task"] = str(selected.get("task", "Gain"))
    _clear_indexed_group_widget_keys(prefix)
    _invalidate_live_result_cache()
    _queue_result_detail_view_restore()


def _delete_fir_eq_item(
    selected_id: str,
    selected: dict[str, str],
    option_ids: list[str],
    metadata: dict[str, dict[str, str]],
) -> None:
    list_key = str(selected.get("list_key", ""))
    prefix = str(selected.get("prefix", ""))
    item_id = str(selected.get("item_id", ""))
    task = str(selected.get("task", "Gain"))
    if not list_key or not prefix or not item_id or not delete_list_item(list_key, item_id):
        return
    same_task_options = [
        option_id
        for option_id in option_ids
        if option_id != selected_id and metadata[option_id]["task"] == task
    ]
    next_option = same_task_options[0] if same_task_options else f"empty:{task}"
    st.session_state["fir_eq_overview_selected"] = next_option
    selection_key = str(selected.get("selection_key", ""))
    if selection_key:
        if next_option.startswith("empty:"):
            st.session_state[selection_key] = ""
        else:
            next_meta = metadata[next_option]
            st.session_state[selection_key] = str(next_meta.get("selection_value", ""))
    st.session_state["fir_eq_task"] = task
    _clear_indexed_group_widget_keys(prefix)
    _invalidate_live_result_cache()
    _queue_result_detail_view_restore()


def _render_fir_eq_overview(nyquist: float, *, view: str) -> None:
    _function_section_heading(view.lower(), ui_message('ui.619df5678b58d4', p0=f'{view}'))
    st.caption(
        ui_message('ui.ec555a551d73e3', p0=f'{view}', p1=f'{view}')
    )
    st.caption(ui_message('ui.f08de2d9e6fe61'))

    visible_add_types = [
        option
        for option in FIR_EQ_ADD_TYPE_OPTIONS
        if option.startswith(f"{view} ·") or option.startswith(f"Auto {view} ·")
    ]

    with st.container(horizontal=True, vertical_alignment="bottom", gap="small"):
        add_type = selectbox_indexed(
            ui_message('ui.b84cad41b23175'),
            visible_add_types,
            settings_key="fir_eq_add_type",
            default=visible_add_types[0],
            key="fir_eq_add_type_widget",
        )
        if localized_button(st, ui_message('ui.9fd728c66c9a25'), key="fir_eq_add", type="primary"):
            option_id, task = _add_fir_eq_item(str(add_type), nyquist)
            if option_id:
                st.session_state["fir_eq_overview_selected"] = option_id
                st.session_state["fir_eq_task"] = task
                st.rerun()

    frame, option_ids, metadata = _fir_eq_overview_data(nyquist, view=view)
    _render_filter_bulk_controls([
        (item["list_key"], item["item_id"]) for item in metadata.values()
    ], key=f"fir_eq_{view}")
    requested_task = str(st.session_state.pop("_fir_eq_requested_task", ""))
    current_task = str(st.session_state.get("fir_eq_task", "Gain"))
    visible_tasks = (view, f"Auto {view}")
    preferred_task = requested_task if requested_task in visible_tasks else current_task
    if preferred_task not in visible_tasks:
        preferred_task = view
    preferred_id = next(
        (option_id for option_id in option_ids if metadata[option_id]["task"] == preferred_task),
        option_ids[0] if option_ids else "",
    )
    if requested_task:
        st.session_state["fir_eq_overview_selected"] = preferred_id
    previous_task = current_task
    selected_id = _single_row_table_selector(
        frame,
        option_ids,
        selected_state_key="fir_eq_overview_selected",
        table_key="fir_eq_overview",
        height=min(360, 42 + 35 * max(len(frame.index), 1)),
        default_id=preferred_id,
    )
    selected = metadata[selected_id]
    task = selected["task"]
    st.session_state["fir_eq_task"] = task
    if selected["edit_group"]:
        group_key = "gain_edit_group" if task == "Gain" else "phase_edit_group"
        _set_plain_setting_and_widget(group_key, selected["edit_group"])
    if selected["selection_key"] and selected["selection_value"]:
        st.session_state[selected["selection_key"]] = selected["selection_value"]
    selected_row = frame.iloc[option_ids.index(selected_id)]
    selected_label = str(selected_row["Type"])
    selected_frequency = str(selected_row["Frequency"])
    st.caption(
        ui_message('ui.1445c1eecdf52b', p0=f'{task}', p1=f'{selected_label}')
        + (ui_message('ui.04420b9dfe3f0a', p0=f'{selected_frequency}') if selected_frequency != "-" else "")
    )
    action_disabled = not bool(selected["item_id"])
    duplicate_disabled = action_disabled or len(st.session_state.get(selected["list_key"], [])) >= list_policy(selected["list_key"]).edit_limit
    with st.container(horizontal=True, gap="small"):
        if localized_button(st, ui_message('ui.02cdaabfca805d'), key="fir_eq_duplicate", disabled=duplicate_disabled):
            _duplicate_fir_eq_item(selected)
            st.rerun()
        if localized_button(st, ui_message('ui.e2d0a54968ead2'), key="fir_eq_delete", disabled=action_disabled):
            _delete_fir_eq_item(selected_id, selected, option_ids, metadata)
            st.rerun()
    if task != previous_task:
        st.rerun()


def _db_record_column_config(*, id_label: str = "ID") -> dict[str, Any]:
    return {
        "ID": None,
        "Created": st.column_config.TextColumn(
            "Created",
            width="medium",
            help="このレコードが最初にDBへ登録された日時です。",
        ),
        "Updated": st.column_config.TextColumn(
            "Updated",
            width="medium",
            help="このレコードが最後に更新された日時です。",
        ),
    }


def _db_record_identity_line(
    *,
    label: str,
    record_id: str,
    created_at: str,
    updated_at: str,
) -> str:
    parts = [f"Selected {label}"]
    if created_at:
        parts.append(f"Created: {created_at}")
    if updated_at:
        parts.append(f"Updated: {updated_at}")
    return " | ".join(parts)


def _input_measurement_selector_table(
    records: list[SpeakerMeasurementRecord],
) -> tuple[pd.DataFrame, list[str]]:
    table = measurement_table(records).fillna("").astype(str)
    columns = list(table.columns) if len(table.columns) else ["Type", "Name"]
    action_rows: list[dict[str, Any]] = []
    for name in ("Keep current", "None / clear"):
        row = {column: "" for column in columns}
        row["Type"] = "Selection"
        row["Name"] = name
        action_rows.append(row)
    action_table = pd.DataFrame(action_rows, columns=columns)
    if table.empty:
        table = action_table
    else:
        table = pd.concat([action_table, table], ignore_index=True)
    return table, [
        INPUT_MEASUREMENT_KEEP_OPTION,
        INPUT_MEASUREMENT_CLEAR_OPTION,
        *[record.id for record in records],
    ]


def _preset_editor_seed(prefix: str, selected: dict[str, Any] | None, values: dict[str, Any]) -> None:
    selected_id = str(selected.get("id", "")) if selected else ""
    seed_key = f"_{prefix}_editor_selected_id"
    selection_changed = st.session_state.get(seed_key) != selected_id
    st.session_state[seed_key] = selected_id
    for field, value in values.items():
        key = f"{prefix}_{field}"
        # Hidden widgets are removed by Streamlit; restore their saved/default values.
        if selection_changed or key not in st.session_state:
            st.session_state[key] = value


def _target_preset_catalog(*, full=False) -> list[dict[str, Any]]:
    return shared_target_preset_catalog(APP_ROOT, scope="phaseeq_channel", summaries=not full)


def _target_preset_source_label(definition: dict[str, Any]) -> str:
    source_name = str(definition.get("target_source_name", "")).strip()
    if source_name:
        return source_name
    target_url = str(definition.get("target_url", "")).strip()
    if target_url:
        return target_url
    if isinstance(definition.get("target_response_raw"), dict):
        return "Imported response"
    return "Generated flat Target"


def _apply_target_definition_to_state(definition: dict[str, Any]) -> None:
    from response_completion.settings import migrate_extension_choices
    definition = migrate_extension_choices(definition)
    if definition.get("_summary"):
        definition = materialize_target_preset(APP_ROOT, definition)
    _clear_selection_preview()
    st.session_state["_target_preset_editing_id"] = str(definition.get("id", ""))
    st.session_state["_target_preset_editing_name"] = str(definition.get("name", "未保存のTarget"))
    mode = str(definition.get("level_mode", TARGET_GAIN_SHIFT_MODE_OPTIONS[0]))
    if mode not in TARGET_GAIN_SHIFT_MODE_OPTIONS:
        mode = TARGET_GAIN_SHIFT_MODE_OPTIONS[0]
    _set_setting_and_widget(
        "target_gain_shift_mode", mode, "__rad_val_", "target_gain_shift_mode_widget",
    )
    _set_setting_and_widget(
        "target_gain_shift_db", float(definition.get("level_db", 0.0)), "__num_val_",
    )
    source_content_mode = str(
        definition.get("source_content_mode", TARGET_SOURCE_CONTENT_MODE_OPTIONS[0])
    )
    _set_plain_setting_and_widget(
        "target_source_content_mode",
        source_content_mode
        if source_content_mode in TARGET_SOURCE_CONTENT_MODE_OPTIONS
        else TARGET_SOURCE_CONTENT_MODE_OPTIONS[0],
    )
    _set_plain_setting_and_widget(
        "target_phase_enabled", bool(definition.get("phase_enabled", True)),
    )
    _set_plain_setting_and_widget("target_lf_extension_enabled", bool(definition.get("lf_extension_enabled", False)))
    _set_plain_setting_and_widget("target_hf_extension_enabled", bool(definition.get("hf_extension_enabled", False)))
    _set_setting_and_widget(
        "target_url", str(definition.get("target_url", "")), "__text_val_",
    )
    restored_target = speaker_response_from_payload(definition.get("target_response_raw"))
    if restored_target is None:
        st.session_state.pop("_restored_target_response_raw", None)
        st.session_state.pop("_restored_target_source_name", None)
        st.session_state.pop("_restored_target_url_input", None)
    else:
        st.session_state["_restored_target_response_raw"] = restored_target
        st.session_state["_restored_target_source_name"] = str(
            definition.get("target_source_name") or definition.get("name", "Target")
        )
        st.session_state["_restored_target_url_input"] = str(
            definition.get("target_url", "")
        ).strip()
    _apply_target_edit_payload_to_state(definition.get("target_edit", {}))
    st.session_state["_target_source_name"] = str(definition.get("target_source_name", "")) if restored_target is not None else ""
    _invalidate_live_result_cache()
    for field, default in (("name", "新しいTarget"), ("description", ""), ("category", "Reference")):
        st.session_state[f"target_editor_{field}"] = str(definition.get(field, default))
    st.session_state["_target_editor_baseline"] = _target_editor_record("") if definition.get("id") else None
    st.session_state["target_editor_saved_hash"] = _target_editor_signature()
    st.session_state["_target_editor_saved_definition"] = dict(definition)


def _render_preset_tier_transfer_actions(
    *,
    selected: dict[str, Any] | None,
    key_prefix: str,
    kind: str,
    bundled_path: Path,
    user_path: Path,
) -> None:
    source = str(selected.get("source", "")) if selected else ""
    shared_tiers = set(selected.get("sources", ())) if selected else set()
    tier_conflict = {"Built-in", "User"}.issubset(shared_tiers)
    with st.container(horizontal=True):
        promote = localized_button(st,
            ui_message('ui.2f7def4757bcc9'),
            key=f"{key_prefix}_promote",
            icon=":material/upgrade:",
            disabled=source != "User" or tier_conflict,
            help=ui_message('ui.996218bd16e730'),
        )
        demote = localized_button(st,
            ui_message('ui.58aa803001ae17'),
            key=f"{key_prefix}_demote",
            icon=":material/move_down:",
            disabled=source != "Built-in" or tier_conflict,
            help=ui_message('ui.dda17e28485fd7'),
        )
    if promote:
        assert selected is not None
        try:
            transfer_preset(
                str(selected["id"]),
                source_path=user_path,
                destination_path=bundled_path,
                kind=kind,
            )
            st.success(ui_message('ui.031c6856450c67', p0=f"{selected['name']}"))
            st.rerun()
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            st.error(ui_message('ui.89cbd091f271ee', p0=f'{exc}'))
    if demote:
        assert selected is not None
        try:
            transfer_preset(
                str(selected["id"]),
                source_path=bundled_path,
                destination_path=user_path,
                kind=kind,
            )
            st.success(ui_message('ui.1ec1a3b8972a6e', p0=f"{selected['name']}"))
            st.rerun()
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            st.error(ui_message('ui.2b16f15b25ec43', p0=f'{exc}'))


def _target_editor_unique_name(base: str) -> str:
    base = str(base).strip() or "新しいTarget"
    existing = {str(r.get("name", "")).strip().casefold() for r in _target_preset_catalog()}
    candidate = base
    number = 2
    while candidate.casefold() in existing:
        candidate = f"{base} ({number})"
        number += 1
    return candidate


def _target_editor_record(record_id: str) -> dict[str, Any]:
    from response_completion.settings import METHOD
    return {
        "response_extension_method": METHOD,
        "id": record_id,
        "name": str(st.session_state.get("target_editor_name", "")).strip(),
        "description": str(st.session_state.get("target_editor_description", "")).strip(),
        "category": str(st.session_state.get("target_editor_category", "Reference")),
        "compatible_scopes": ["phaseeq_channel", "composite_group"],
        "preset_schema_version": 2,
        "level_mode": _current_radio_setting(
            "target_gain_shift_mode", TARGET_GAIN_SHIFT_MODE_OPTIONS[0], "target_gain_shift_mode_widget"
        ),
        "level_db": _current_number_setting("target_gain_shift_db", 0.0),
        "source_content_mode": str(
            st.session_state.get(
                "target_source_content_mode", TARGET_SOURCE_CONTENT_MODE_OPTIONS[0]
            )
        ),
        "phase_enabled": bool(st.session_state.get("target_phase_enabled", True)),
        "lf_extension_enabled": bool(st.session_state.get("target_lf_extension_enabled", False)),
        "hf_extension_enabled": bool(st.session_state.get("target_hf_extension_enabled", False)),
        "target_url": _current_text_setting("target_url", ""),
        "target_source_name": str(
            st.session_state.get("_target_source_name", "")
            or st.session_state.get("_restored_target_source_name", "")
        ),
        "target_response_raw": speaker_response_payload(
            st.session_state.get("_restored_target_response_raw")
        ),
        "target_edit": _target_edit_payload_from_state(),
    }

def _target_editor_signature() -> str:
    return hashlib.sha256(json.dumps(_target_editor_record(""), sort_keys=True, ensure_ascii=False).encode()).hexdigest()


def _target_editor_dirty() -> bool:
    return _target_editor_signature() != st.session_state.get("target_editor_saved_hash", "")


def _target_editor_save(*, new: bool) -> bool:
    catalog = _target_preset_catalog()
    origin_id = str(st.session_state.get("_target_preset_editing_id", ""))
    origin = next((r for r in catalog if str(r["id"]) == origin_id), None)
    if not new and (origin is None or origin.get("source") != "User"):
        st.error(ui_message('ui.36338467f9e21a'))
        return False
    name = str(st.session_state.get("target_editor_name", "")).strip()
    if not name:
        st.error(ui_message('ui.e6b6ca5cace867'))
        return False
    record = _target_editor_record(new_preset_id(name) if new else origin_id)
    records = user_presets_from_catalog(_target_preset_catalog(full=True))
    if new:
        records.append(record)
    else:
        records = [record if str(r["id"]) == origin_id else r for r in records]
    try:
        write_user_presets(TARGET_PRESETS_USER_FILE, kind="target_response", presets=records)
    except (OSError, ValueError) as exc:
        st.error(ui_message('ui.7034516d195de7', p0=f'{exc}'))
        return False
    from utils.design_history import save as save_design_history, adopt_draft
    try:
        if new and not origin_id:
            adopt_draft(_history_path(), "target", _history_target_owner(), str(record["id"]))
        save_design_history(_history_path(), "target", str(record["id"]), record,
                            kind="manual", app_version=APP_VERSION)
    except (OSError, ValueError, sqlite3.Error) as exc:
        # Publishing the Target has already succeeded; retain that result and
        # make the auxiliary history failure inspectable without losing edits.
        st.session_state["_history_error"] = str(exc)
    st.session_state["_target_workspace_selection_pending"] = record["id"]
    st.session_state["_target_preset_editing_id"] = record["id"]
    st.session_state["_target_preset_editing_name"] = name
    st.session_state.pop("_target_editor_suggested_name", None)
    st.session_state["_target_editor_baseline"] = {**record, "id": ""}
    st.session_state["target_editor_saved_hash"] = _target_editor_signature()
    st.session_state["_target_editor_saved_definition"] = record
    st.session_state["_target_preset_save_notice"] = f"保存しました：{name}。Multiwayの登録済みTargetから選択できます。"
    return True


def _target_editor_request(definition, *, task="Target edit", rerun=True):
    if definition.get("_summary"):
        definition = materialize_target_preset(APP_ROOT, definition)
    request = {"definition": dict(definition), "task": task}
    if rerun:
        st.session_state["_target_editor_navigation_pending"] = True
    if bool(st.session_state.get("target_selection_lock", False)) and _target_editor_dirty():
        st.session_state["_target_editor_switch_request"] = request
    else:
        st.session_state.pop("_target_editor_switch_request", None)
        st.session_state["_target_editor_load_pending"] = request
    if rerun:
        st.rerun()


def _target_editor_value_changed(widget_key, setting_key, legacy_key=None):
    if widget_key != _target_editor_menu_key(setting_key + "_input"):
        return
    # Navigation can retire a widget before its queued callback arrives.
    # Missing UI state is not a new setting; retain the last committed value.
    try:
        value = st.session_state[widget_key]
    except KeyError:
        return
    if setting_key == "target_gain_shift_db" and value is None:
        value = 0.0
        st.session_state[widget_key] = value
    st.session_state[setting_key] = value
    if setting_key == "target_editor_name":
        st.session_state["_target_editor_name_user_edited"] = bool(str(value).strip())
        _target_editor_fill_empty_name()
    if legacy_key:
        st.session_state[legacy_key] = value


def _target_editor_text_input(label, setting_key, **kwargs):
    widget_key = _target_editor_menu_key(setting_key + "_input")
    st.session_state.setdefault(widget_key, st.session_state.get(setting_key, ""))
    return st.text_input(label, key=widget_key, on_change=_target_editor_value_changed,
                         args=(widget_key, setting_key), **kwargs)


def _target_editor_fill_empty_name():
    current = str(st.session_state.get("target_editor_name", "")).strip()
    # Restored drafts can contain the default name without the transient
    # suggestion marker. Recover that placeholder before rendering its widget.
    placeholder = (current == "新しいTarget"
                   and not st.session_state.get("_target_editor_name_user_edited"))
    if st.session_state.get("_target_preset_editing_id") or (current and not placeholder):
        return
    uploaded = st.session_state.get(_target_editor_menu_key("target_file"))
    source = (uploaded.name if uploaded is not None else
              st.session_state.get("_restored_target_source_name", ""))
    if not source:
        return
    suggestion = _target_editor_unique_name(Path(source).stem)
    st.session_state["target_editor_name"] = suggestion
    st.session_state["_target_editor_suggested_name"] = suggestion
    st.session_state[_target_editor_menu_key("target_editor_name_input")] = suggestion


def _target_editor_file_changed(widget_key):
    if widget_key != _target_editor_menu_key("target_file"):
        return
    uploaded = st.session_state.get(widget_key)
    suggested = st.session_state.get("_target_editor_suggested_name")
    current = st.session_state.get("target_editor_name", "")
    if (uploaded is not None and not st.session_state.get("_target_preset_editing_id")
            and not st.session_state.get("_target_editor_name_user_edited")
            and (not str(current).strip() or current == "新しいTarget"
                 or (suggested is not None and current == suggested))):
        # Queue before the header and save controls render, not after import.
        st.session_state["_target_editor_name_pending"] = (current, Path(uploaded.name).stem)


def _render_target_editor_header():
    if "target_editor_name" not in st.session_state and not st.session_state.get("_target_preset_editing_id"):
        source = str(st.session_state.get("_restored_target_source_name", ""))
        suggestion = _target_editor_unique_name(Path(source).stem if source else "新しいTarget")
        st.session_state["target_editor_name"] = suggestion
        st.session_state["_target_editor_suggested_name"] = suggestion
    pending = st.session_state.pop("_target_editor_load_pending", None)
    if pending is not None:
        # A loaded Target can select a different submenu. Ignore browser events
        # still arriving from the previous Target's navigation widgets.
        st.session_state["_target_editor_menu_revision"] = int(st.session_state.get("_target_editor_menu_revision", 0)) + 1
        definition = dict(pending["definition"])
        st.session_state.pop("_target_editor_name_user_edited", None)
        if not definition.get("id"):
            definition["name"] = _target_editor_unique_name(definition.get("name", "新しいTarget"))
            st.session_state["_target_editor_suggested_name"] = definition["name"]
        else:
            st.session_state.pop("_target_editor_suggested_name", None)
        st.session_state.pop("target_file", None)
        st.session_state.pop("_target_source_name", None)
        if "_settings_payload" in definition:
            _apply_target_settings_payload_to_state(definition["_settings_payload"])
            st.session_state["_target_preset_editing_id"] = ""
            st.session_state["_target_preset_editing_name"] = definition["name"]
        else:
            _apply_target_definition_to_state(definition)
        for field, default in (("name", "新しいTarget"), ("description", ""), ("category", "Reference")):
            st.session_state[f"target_editor_{field}"] = str(definition.get(field, default))
        st.session_state["_target_editor_baseline"] = _target_editor_record("") if definition.get("id") else None
        st.session_state["target_editor_saved_hash"] = _target_editor_signature()
        st.session_state["_target_editor_saved_definition"] = dict(definition)
        if pending.get("history_restore"):
            from utils.design_history import save as save_design_history
            st.session_state["target_editor_saved_hash"] = ""
            save_design_history(_history_path(), "target", _history_target_owner(),
                                _target_editor_record(str(st.session_state.get("_target_preset_editing_id", ""))),
                                kind="restore", restored_from=pending["history_restore"], app_version=APP_VERSION)
        # Render the restored widget values in this run. Rerunning before the
        # widgets mount lets the browser send their previous values back.
        st.session_state["target_task"] = pending["task"]
        st.session_state["target_task_widget"] = pending["task"]
    source_suggestion = st.session_state.pop("_target_editor_name_pending", None)
    if source_suggestion is not None:
        previous, base = source_suggestion
        if (not st.session_state.get("_target_preset_editing_id")
                and st.session_state.get("target_editor_name") == previous):
            suggestion = _target_editor_unique_name(base)
            st.session_state["target_editor_name"] = suggestion
            st.session_state["_target_editor_suggested_name"] = suggestion
            st.session_state[_target_editor_menu_key("target_editor_name_input")] = suggestion
    _target_editor_fill_empty_name()
    # Keep metadata alive while its optional editor is hidden by navigation.
    for field, default in (("name", st.session_state.get("_target_preset_editing_name", "新しいTarget")), ("description", ""), ("category", "Reference")):
        key = f"target_editor_{field}"
        st.session_state[key] = st.session_state.get(key, default)
    catalog = _target_preset_catalog()
    origin_id = str(st.session_state.get("_target_preset_editing_id", ""))
    origin = next((r for r in catalog if str(r["id"]) == origin_id), None)
    if origin and not st.session_state.get("_target_editor_saved_definition"):
        st.session_state["_target_editor_saved_definition"] = materialize_target_preset(APP_ROOT, origin) if origin.get("_summary") else dict(origin)
    editable = origin is not None and origin.get("source") == "User"
    kind = "自分のTarget" if editable else "標準Target・上書き不可" if origin else "新規Target"
    if "target_editor_saved_hash" not in st.session_state:
        initial = _target_editor_record("")
        # A pristine editor is not an unsaved import. Establish its baseline
        # before the first table click, while preserving restored drafts.
        if (not origin and initial["target_response_raw"] is None
                and not initial["target_url"] and not initial["target_source_name"]
                and initial["level_db"] == 0.0
                and not any(value for value in initial["target_edit"].values() if isinstance(value, list))):
            st.session_state["target_editor_saved_hash"] = _target_editor_signature()
    dirty = _target_editor_dirty()
    st.session_state["_target_editor_header_record"] = _target_editor_record("")
    with st.container(border=True):
        st.markdown(ui_message('ui.bc350433d2ba0a', p0=f"{st.session_state['target_editor_name']}"))
        st.caption(ui_message('ui.ae04d0e6f63d1e', p0=display_text(kind), p1=display_text('未保存の変更あり' if dirty else '保存済み' if origin else '未登録')))
        notice = st.session_state.pop("_target_preset_save_notice", "")
        if notice:
            st.success(display_notice(notice))
        _target_editor_text_input(ui_message('ui.24dd751352c0b6'), "target_editor_name",
                      help=ui_message('ui.21805d05103880'))
        with st.container(horizontal=True):
            if editable and st.button(display_text("更新"), key="target_preset_update", disabled=not dirty, type="primary"):
                if _target_editor_save(new=False):
                    st.rerun()
            if st.button(display_text("別のTargetとして新規登録" if editable else "コピーして新規登録" if origin else "新規登録"), key="target_preset_add", type="secondary" if editable else "primary"):
                if _target_editor_save(new=True):
                    st.rerun()
            if st.button(ui_message('ui.996db9dc29b00a'), disabled=not dirty or not st.session_state.get("_target_editor_saved_definition", {}).get("id"), key='i18n_840e9acc0032d236'):
                st.session_state["_target_editor_switch_request"] = {
                    "definition": st.session_state["_target_editor_saved_definition"],
                    "task": str(st.session_state.get("target_task", "Target edit")),
                }
                st.rerun()
        with st.expander(ui_message('ui.5b1c39989f3a23'), expanded=False):
            _target_editor_text_input(ui_message('ui.88331f1fe0455f'), "target_editor_description")
            _target_editor_text_input(ui_message('ui.5b6434ef309a57'), "target_editor_category")


def _render_target_switch_confirmation():
    request = st.session_state.get("_target_editor_switch_request")
    if not request:
        return
    origin_id = str(st.session_state.get("_target_preset_editing_id", ""))
    editable = any(str(r["id"]) == origin_id and r.get("source") == "User"
                   for r in _target_preset_catalog())
    current = str(st.session_state.get("target_editor_name", ""))
    destination = str(request["definition"].get("name", ""))
    st.info(ui_message("ui.8d415d4df3ab4f", destination=destination, current=current))
    st.warning(ui_message('ui.a06b7aca9d8407'))
    with st.container(horizontal=True):
        save_switch = st.button(ui_message('ui.e0f517d8cce5c4'), key='i18n_c9ba88d93d324300')
        discard_switch = st.button(ui_message('ui.cff9268ff500d4'), key='i18n_7dec1c0f3272c800')
        cancel = st.button(ui_message('ui.bca84ea5c65fee'), key="target_switch_cancel")
    if cancel:
        st.session_state["_target_workspace_selection_pending"] = origin_id
        st.session_state.pop("_target_editor_switch_request", None)
        st.rerun()
    if discard_switch or (save_switch and _target_editor_save(new=not editable)):
        st.session_state["_target_editor_load_pending"] = request
        st.session_state.pop("_target_editor_switch_request", None)
        st.rerun()


def _target_workspace_new_requested():
    # Commit the request before the table mounts so its old selection cannot
    # reselect the previous Target during this same button interaction.
    _target_editor_request(
        {"name": "新しいTarget", "level_mode": "手動シフト", "level_db": 0.0},
        rerun=False,
    )
    st.session_state["_target_workspace_selection_pending"] = ""


def _render_target_workspace_list(*, management=False):
    pending_scope = st.session_state.pop("_target_management_scope_pending", None)
    if pending_scope:
        st.session_state["target_workspace_scope"] = pending_scope
    catalog = _target_preset_catalog()
    origin_id = str(st.session_state.get("_target_preset_editing_id", ""))
    scope = required_segmented_control(display_text("一覧に表示するTarget"),
        ["すべて", "標準Target", "ユーザーTarget"], key="target_workspace_scope",
        format_func=localized_formatter(str))
    scope_changed = st.session_state.get("_target_workspace_previous_scope", scope) != scope
    st.session_state["_target_workspace_previous_scope"] = scope
    if scope != "すべて":
        catalog = [r for r in catalog if (r.get("source") == "User") == (scope == "ユーザーTarget")]
    origin_visible = any(str(r["id"]) == origin_id for r in catalog)
    pending = st.session_state.get("_target_editor_load_pending")
    switching = st.session_state.get("_target_editor_switch_request")
    selection_key = "target_workspace_selected_id"
    desired = st.session_state.pop("_target_workspace_selection_pending", None)
    if pending:
        desired = str(pending["definition"].get("id", ""))
    elif switching:
        desired = origin_id
    elif selection_key not in st.session_state or (scope_changed and not management):
        desired = origin_id
    if desired is not None and desired != st.session_state.get(selection_key):
        st.session_state[selection_key] = desired
        nonce = "target_workspace_table_selection_nonce"
        st.session_state[nonce] = int(st.session_state.get(nonce, 0)) + 1
    st.caption(display_text("ユーザーTargetは編集・更新できます。標準TargetはコピーしてユーザーTargetとして編集します。"))
    table = pd.DataFrame([{
        display_text("Target名"): r["name"],
        display_text("種類"): display_text("ユーザーTarget" if r.get("source") == "User" else "標準Target"),
        display_text("編集"): display_text("編集・上書き可能" if r.get("source") == "User" else "コピーして編集"),
        display_text("入力元"): r.get("target_source_name", "") or display_text("フラット／EQ"),
    } for r in catalog])
    selected_id = shared_single_row_table_selector(table, [str(r["id"]) for r in catalog],
        selected_state_key=selection_key, table_key="target_workspace_table", required=False,
        height=min(249, 36 + 35 * max(1, len(catalog)))) if catalog else ""
    if not catalog:
        st.session_state[selection_key] = ""
        st.caption(display_text("この種類のTargetはまだ登録されていません。"))
    if origin_id and not origin_visible:
        st.caption(display_text("編集中のTargetは一覧の表示対象外です。編集内容は保持しています。"))
    if management:
        return
    st.button(display_text("選択を解除して新規入力へ"), key="target_workspace_new",
              disabled=not bool(selected_id), on_click=_target_workspace_new_requested)
    if (not pending and not switching and selected_id != origin_id
            and (selected_id or (origin_visible and not scope_changed))):
        definition = next((r for r in catalog if str(r["id"]) == selected_id),
                          {"name": "新しいTarget", "level_mode": "手動シフト", "level_db": 0.0})
        _target_editor_request(definition, rerun=False)
    _render_target_switch_confirmation()
    _clear_selection_preview()


