def _format_auto_edge_smooth(value: float) -> str:
    value = float(value)
    if value <= 0:
        return NO_SMOOTHING_LABEL
    if value >= 1.0:
        return f"{value:g} oct"
    denominator = round(1.0 / value)
    return f"1/{denominator} oct"


def _nearest_auto_edge_option(value: float, options: list[float] | None = None) -> float:
    option_values = options or AUTO_EDGE_SMOOTH_OPTIONS
    return min(option_values, key=lambda option: abs(option - float(value)))


def _nearest_option(value: float, options: list[float]) -> float:
    return min(options, key=lambda option: abs(option - float(value)))


def _stored_auto_edge_smooth_value(
    key: str,
    default: float = 1.0 / 3.0,
    *,
    options: list[float] | None = None,
) -> float:
    try:
        value = float(st.session_state.get(key, default))
    except Exception:
        value = float(default)
    value = _nearest_auto_edge_option(value, options)
    st.session_state[key] = value
    return value


def _current_auto_edge_smooth_setting(
    key: str,
    default: float = 1.0 / 3.0,
    *,
    options: list[float] | None = None,
) -> float:
    """Return the latest smoothing value, including an active selectbox widget."""
    option_values = options or AUTO_EDGE_SMOOTH_OPTIONS
    widget_key = f"{key}_widget"
    source_value = st.session_state.get(widget_key, st.session_state.get(key, default))
    try:
        value = _nearest_auto_edge_option(float(source_value), option_values)
    except Exception:
        value = _nearest_auto_edge_option(float(default), option_values)
    st.session_state[key] = value
    return value


def _sync_plain_bool_widget(key: str, default: bool = False, *, widget_key: str | None = None) -> bool:
    """Seed a bool widget from its canonical setting without reverse overwrite.

    Streamlit may keep or remove widget-bound values independently while
    conditional result views rerun.  The canonical setting must therefore win
    on unrelated reruns; the widget callback is the only path that commits an
    intentional user toggle back to it.
    """
    widget_key = widget_key or f"{key}_widget"
    value = bool(st.session_state.get(key, default))
    st.session_state[key] = value
    if widget_key not in st.session_state:
        st.session_state[widget_key] = value
    return value


def _commit_plain_bool_widget(key: str, widget_key: str, default: bool) -> None:
    """Commit one explicit bool-widget interaction to its canonical setting."""
    st.session_state[key] = bool(
        st.session_state.get(widget_key, st.session_state.get(key, default))
    )


def _sync_plain_option_widget(
    key: str,
    options: list[Any] | tuple[Any, ...],
    default: Any,
    *,
    widget_key: str | None = None,
    normalize: Any | None = None,
) -> Any:
    widget_key = widget_key or f"{key}_widget"
    option_list = list(options)
    fallback = default if default in option_list else (option_list[0] if option_list else default)
    value = st.session_state.get(widget_key, st.session_state.get(key, fallback))
    if value is None:
        value = st.session_state.get(key, fallback)
    if normalize is not None:
        value = normalize(value)
    if value not in option_list:
        value = fallback
    st.session_state[key] = value
    # A cleared/stale selection must be repaired on the widget as well as the
    # canonical setting, otherwise the chart and its selected button disagree.
    if widget_key not in st.session_state or st.session_state[widget_key] != value:
        st.session_state[widget_key] = value
    return value


def _commit_plain_option_widget(
    key: str,
    widget_key: str,
    options: list[Any] | tuple[Any, ...],
    default: Any,
) -> None:
    """Commit one explicit single-choice interaction before the app reruns."""
    option_list = list(options)
    fallback = default if default in option_list else (option_list[0] if option_list else default)
    value = st.session_state.get(widget_key, st.session_state.get(key, fallback))
    st.session_state[key] = value if value in option_list else fallback


def _sync_live_result_controls_state() -> dict[str, Any]:
    graph_max_points = _sync_plain_option_widget(
        "graph_max_points",
        GRAPH_MAX_POINTS_OPTIONS,
        DEFAULT_GRAPH_MAX_POINTS,
        normalize=_normalize_graph_max_points,
    )
    gain_y_min = _sync_plain_option_widget(
        "gain_y_min_db",
        GAIN_Y_MIN_OPTIONS,
        DEFAULT_GAIN_Y_MIN_DB,
        normalize=_normalize_gain_y_min,
    )
    gain_y_max = _sync_plain_option_widget(
        "gain_y_max_db",
        GAIN_Y_MAX_OPTIONS,
        DEFAULT_GAIN_Y_MAX_DB,
        normalize=_normalize_gain_y_max,
    )
    return {
        "auto_update": _sync_plain_bool_widget("auto_update", True),
        "graph_mode": str(_sync_plain_option_widget("graph_mode", GRAPH_MODE_OPTIONS, DEFAULT_GRAPH_MODE)),
        "graph_max_points": int(graph_max_points),
        "gain_y_min_db": int(gain_y_min),
        "gain_y_max_db": int(gain_y_max),
    }


LIVE_RESULT_CONTEXT_KEYS = (
    "auto_update",
    "graph_mode",
    "graph_max_points",
    "gain_y_min_db",
    "gain_y_max_db",
    "phase_gain_mask",
    "result_detail_view",
    "wavelet_mode",
    "wavelet_preset",
    "wavelet_bandwidth",
    "wavelet_dynamic_range",
    "wavelet_window_preview",
)


def _preserve_live_result_context_for_measure(active_page: str) -> str:
    """Keep Measure independent from the correction-design Live Result.

    Streamlit removes widget bindings when a widget is not rendered. Measure
    replaces the normal right pane with the measurement dashboard, so retain
    both canonical settings and their widget mirrors across that temporary
    absence. The returned page is the design page whose preview stage should
    remain active internally while Measure is selected.
    """
    previous_page = str(st.session_state.get("_previous_active_page", ""))
    if active_page == "Measure":
        if previous_page != "Measure":
            snapshot: dict[str, Any] = {}
            for key in LIVE_RESULT_CONTEXT_KEYS:
                widget_key = f"{key}_widget"
                if widget_key in st.session_state:
                    snapshot[key] = st.session_state[widget_key]
                elif key in st.session_state:
                    snapshot[key] = st.session_state[key]
            st.session_state["_live_result_context_before_measure"] = snapshot
            if previous_page in UI_PAGE_OPTIONS and previous_page != "Measure":
                st.session_state["_last_design_live_result_page"] = previous_page
        design_page = str(st.session_state.get("_last_design_live_result_page", "Input"))
        if design_page not in UI_PAGE_OPTIONS or design_page == "Measure":
            design_page = "Input"
    else:
        if previous_page == "Measure":
            snapshot = st.session_state.pop("_live_result_context_before_measure", {})
            if isinstance(snapshot, dict):
                for key, value in snapshot.items():
                    st.session_state[key] = value
                    st.session_state[f"{key}_widget"] = value
        design_page = active_page
        st.session_state["_last_design_live_result_page"] = active_page
    st.session_state["_previous_active_page"] = active_page
    return design_page


def _checkbox_setting_widget(label: str, key: str, *, default: bool = False, help: str | None = None, disabled: bool = False) -> bool:
    if disabled:
        st.session_state[key] = False
    current = False if disabled else _sync_plain_bool_widget(key, default)
    widget_key = f"{key}_widget"
    # Callbacks have already committed the event. Recreate from the canonical
    # value so a remounted browser receives the same default as the saved state.
    st.session_state.pop(widget_key, None)
    st.checkbox(
        label,
        value=current,
        key=widget_key,
        help=help,
        disabled=disabled,
        on_change=_commit_plain_bool_widget,
        args=(key, widget_key, default),
    )
    return bool(st.session_state.get(key, current))


def _selectbox_setting_widget(
    label: str,
    options: list[Any] | tuple[Any, ...],
    key: str,
    *,
    default: Any,
    format_func: Any | None = None,
    help: str | None = None,
) -> Any:
    current = _sync_plain_option_widget(key, options, default)
    widget_key = f"{key}_widget"
    if st.session_state.get(widget_key) not in options:
        st.session_state[widget_key] = current
    value = choice_widget(
        label,
        options,
        key=widget_key,
        current=current, default=current,
        format_func=format_func if format_func is not None else str,
        help=help,
        on_change=_commit_plain_option_widget,
        args=(key, widget_key, tuple(options), default),
    )
    st.session_state[key] = value
    return value


def _segmented_setting_widget(
    label: str,
    options: list[Any] | tuple[Any, ...],
    key: str,
    *,
    default: Any,
    disabled: bool = False,
    option_labels: dict[str, str] | None = None,
) -> Any:
    current = _sync_plain_option_widget(key, options, default)
    widget_key = f"{key}_widget"
    if st.session_state.get(widget_key) not in options:
        st.session_state[widget_key] = current
    value = choice_widget(
        label,
        options,
        key=widget_key,
        current=current, default=current,
        kind="segmented_control", renderer=localized_segmented_control,
        **({"format_func": lambda value: user_ui_label(option_labels.get(value, value)),
            "translation_labels": [option_labels.get(value, value) for value in options]} if option_labels else {}),
        required=True,
        width="stretch",
        disabled=disabled,
        on_change=_commit_plain_option_widget,
        args=(key, widget_key, tuple(options), default),
    )
    if value is None:
        value = current
    st.session_state[key] = value
    return value


