def _sync_scalar_ui_state_for_save(ui_state: dict[str, Any] | None = None) -> dict[str, Any]:
    """Mirror current widget-derived scalar values to plain settings keys before saving.

    Stateful widgets keep the live value in generated widget keys. The settings
    payload also stores a UI section from plain session-state keys, so sync those
    plain keys immediately before serializing without touching rendered widget keys.
    """
    current = dict(ui_state or _read_scalar_ui_state())
    for key, value in current.items():
        st.session_state[key] = value
    return current


def _scalar_ui_state_signature(ui_state: dict[str, Any]) -> str:
    comparable = {
        key: value
        for key, value in ui_state.items()
        if key not in {"active_page"}
    }
    return json.dumps(comparable, ensure_ascii=False, sort_keys=True, default=str)


LIVE_RESULT_REFRESH_IGNORED_UI_KEYS = {
    "target_selection_lock",
    "display_fft_multiplier",
    "active_page",
    "auto_update",
    "graph_max_points",
    "graph_mode",
    "gain_y_min_db",
    "gain_y_max_db",
    "phase_gain_mask",
    "result_detail_view",
    "wavelet_mode",
    "wavelet_preset",
    "wavelet_bandwidth",
    "wavelet_dynamic_range",
    "wavelet_window_preview",
    "project_name",
    "fir_output_formats",
    "target_output_formats",
}


def _processing_changed_ui_keys(before: dict[str, Any], after: dict[str, Any]) -> set[str]:
    return {
        key
        for key in set(before) | set(after)
        if before.get(key) != after.get(key)
        and key not in LIVE_RESULT_REFRESH_IGNORED_UI_KEYS
    }


def _refresh_live_result_if_ui_changed(current: dict[str, Any]) -> None:
    previous = st.session_state.get("_last_scalar_ui_state_for_live_refresh")
    if isinstance(previous, dict) and _processing_changed_ui_keys(previous, current):
        _invalidate_live_result_cache()
        st.session_state["_pending_live_result_refresh"] = True
    st.session_state["_last_scalar_ui_state_for_live_refresh"] = dict(current)


def _purpose_tag_html(tag: str) -> str:
    return f'<span class="flow-purpose-tag">{html.escape(tag)}</span>' if tag else ""


def _flow_section(number: int, title: str, *, tag: str = "") -> None:
    st.markdown(
        (
            '<div class="flow-section-header">'
            f'<span class="flow-section-number">{html.escape(f"{number:02d}")}</span>'
            f'<span class="flow-section-title">{html.escape(title)}</span>'
            f'{_purpose_tag_html(tag)}'
            '</div>'
        ),
        unsafe_allow_html=True,
    )


def _function_section_heading(tone: str, title: str) -> None:
    """Render a Gain/Phase heading without relying on color alone."""
    normalized_tone = "phase" if str(tone).lower() == "phase" else "gain"
    st.markdown(
        f'<div class="rf-function-heading rf-tone-{normalized_tone}">{html.escape(title)}</div>',
        unsafe_allow_html=True,
    )


def _toggle_section_open(
    card_id: str,
    number: int,
    title: str,
    *,
    card_title: str | None = None,
    summary: str = "",
    default_open: bool = True,
) -> bool:
    _flow_section(number, title, tag=ui_message('ui.dce52f3e11196e'))
    return _ui_card_open(
        card_id,
        card_title or title,
        summary=summary,
        summary_prefix="",
        default_open=default_open,
    )


def _compact_navigation(
    label: str,
    sections: Any,
    *,
    settings_key: str,
    default: str,
    key: str,
) -> str:
    register_section_tree(sections, path=[settings_key])
    options = section_options(sections)
    labels = section_label_map(sections)
    current = str(st.session_state.get(settings_key, default))
    if current not in options:
        current = default if default in options else (options[0] if options else "")
        st.session_state[settings_key] = current

    if not options:
        return current
    widget_key = f"{key}_selector"
    if st.session_state.get(widget_key) not in options:
        st.session_state[widget_key] = current
    selected = localized_segmented_control(
        label,
        options,
        key=widget_key,
        format_func=lambda option: labels.get(option, option),
        translation_labels=[labels.get(option, option) for option in options],
        width="stretch",
    )
    st.session_state[settings_key] = selected
    return str(selected)


from ui.fir_navigation import DESIGN_PAGES

_WORKSPACE_PAGES = {
    "Speaker Package": ("Project", "Multiway Assignment", "Library", "Measurement Notes"),
    "PhaseEQ": DESIGN_PAGES,
    "Measure": ("Measure",),
    "Mic Calibration": ("Mic Library", "Mic Profiles"),
    "Speaker Specifications": ("Speaker Specs",),
    "Application": ("Common Settings", "Backup & Restore"),
}

_UTILITY_PAGES: tuple[str, ...] = ()

_DSP_FIR_EDITOR_PAGES = frozenset({"FIR EQ", "Linear FIR"})


def _dsp_fir_editor_available() -> bool:
    assignment = st.session_state.get("_active_context_assignment")
    return (bool(st.session_state.get("standalone_fir_enabled", True)) if assignment is None
            else int(getattr(assignment, "tap_count", 0)) > 0)


def _apply_workspace_navigation() -> None:
    st.session_state.pop('_numeric_edit_deadline', None)
    st.session_state.pop('_pending_page_navigation', None)
    domain = str(st.session_state.get("active_domain_selector", "Speaker Package"))
    pages = _WORKSPACE_PAGES.get(domain, _WORKSPACE_PAGES["Speaker Package"])
    page = pages[0]
    st.session_state["active_page_selector"] = page
    st.session_state[f"active_page_selector_{domain}"] = page
    _set_current_page(page)


def _apply_workspace_page_navigation(domain: str) -> None:
    st.session_state.pop('_numeric_edit_deadline', None)
    st.session_state.pop('_pending_page_navigation', None)
    key = f"active_page_selector_{domain}"
    page = str(st.session_state.get(key, _WORKSPACE_PAGES[domain][0]))
    st.session_state["active_page_selector"] = page
    _set_current_page(page)


def _render_app_header() -> str:
    _normalize_preview_stage_state()
    _state_default("active_page", "Input")
    _apply_pending_page_navigation()
    raw_active_page = st.session_state.get("active_page", "Input")
    canonical_page = _canonical_page_name(raw_active_page)
    if canonical_page != st.session_state.get("active_page"):
        _set_current_page(str(raw_active_page))

    from ui.fir_navigation import available_page, render_iir_only_pages
    permitted_page = available_page(st.session_state.get("active_page", "Input"), _dsp_fir_editor_available())
    if permitted_page != st.session_state.get("active_page"):
        _set_current_page(permitted_page)
        st.session_state["active_page_selector_PhaseEQ"] = permitted_page
        st.session_state["active_page_selector"] = permitted_page

    target_edit_mode = globals().get("_active_target_edit_session") is not None
    assignment_mode = bool(str(st.query_params.get("assignment", "")).strip())
    composite_connection_disabled = target_edit_mode or not assignment_mode
    if target_edit_mode:
        st.session_state["active_domain_selector"] = "PhaseEQ"
        st.session_state["active_page_selector_PhaseEQ"] = "Target"
        _set_current_page("Target")

    sections = APP_SECTIONS
    register_section_tree(sections, path=["active_page"])
    labels = section_label_map(sections)
    domains = _WORKSPACE_PAGES
    page_labels = {
        "Project": "Measurement List & Use",
        "Multiway Assignment": "Multiway Assignment",
        "Library": "Register Measurement",
        "Measurement Notes": "Measurement Notes",
        "Mic Library": "Calibration Library",
        "Mic Profiles": "Microphone Profiles",
        "Speaker Specs": "Speaker Specifications",
        "Input": "Response Processing",
        "Target": "Target",
        "IIR EQ": "IIR EQ",
        "FIR EQ": "FIR EQ",
        "Linear FIR": "Output Band Split",
        "Export": "Export",
        "Measure": "Measure",
        "Common Settings": "Preferences",
        "Backup & Restore": "Backup & Restore",
    }
    workflow_options = tuple(page for pages in domains.values() for page in pages)
    options = workflow_options
    current = str(st.session_state.get("active_page", "Input"))
    if current not in options:
        current = "Input" if "Input" in options else (options[0] if options else "")
        _set_current_page(current)
    utility_active = False
    current_domain = next(
        (domain for domain, pages in domains.items() if current in pages),
        "Speaker Package",
    )
    if current_domain not in domains:
        current_domain = "Speaker Package"
    title_col, selector_col = st.columns(
        [0.12, 0.88], gap="small", vertical_alignment="center"
    )
    with title_col:
        st.markdown(
            (
                f'<div class="rf-app-header-title">{html.escape(APP_NAME)}</div>'
                f'<div class="rf-app-header-meta">v{html.escape(APP_VERSION)} / By {html.escape(APP_AUTHOR)}</div>'
            ),
            unsafe_allow_html=True,
        )
    with selector_col:
        if st.session_state.get("active_domain_selector") not in domains:
            st.session_state["active_domain_selector"] = current_domain
        selected_domain = localized_segmented_control(
            ui_message('ui.87bb59ba2f92f2'),
            list(domains),
            format_func=lambda value: "Driver Profiles" if value == "Speaker Package" else value,
            translation_labels=["Driver Profiles", "PhaseEQ", "Measure", "Mic Calibration", "Speaker Specifications", "Application"],
            key="active_domain_selector",
            label_visibility="collapsed",
            width="stretch",
            on_change=_apply_workspace_navigation,
            disabled=target_edit_mode,
        ) or current_domain
        domain_pages = domains[selected_domain]
        if not utility_active and selected_domain != current_domain:
            current = domain_pages[0]
            _set_current_page(current)
        page_selector_key = f"active_page_selector_{selected_domain}"
        if st.session_state.get(page_selector_key) not in domain_pages:
            st.session_state[page_selector_key] = (
                current if current in domain_pages else domain_pages[0]
            )
        if utility_active:
            selected_page = current
        else:
            fir_editor_available = _dsp_fir_editor_available()
            if selected_domain == "PhaseEQ" and not fir_editor_available:
                selected_page = render_iir_only_pages(
                    domain_pages, page_labels, current, _navigate_to_page, disabled=target_edit_mode,
                )
            else:
                selected_page = localized_segmented_control(
                    ui_message('ui.f35683c1efcc60'),
                    domain_pages,
                    format_func=lambda value: page_labels.get(value, labels.get(value, value)),
                    translation_labels=[page_labels.get(value, labels.get(value, value)) for value in domain_pages],
                    key=page_selector_key,
                    label_visibility="collapsed",
                    width="stretch",
                    help=(
                        ui_message('ui.7fd28c291beb9f')
                        if selected_domain == "PhaseEQ" and not fir_editor_available else None
                    ),
                    on_change=_apply_workspace_page_navigation,
                    args=(selected_domain,),
                    disabled=target_edit_mode,
                ) or current
        if selected_page != st.session_state.get("active_page"):
            _set_current_page(str(selected_page))

    return str(selected_page or current or "Input")


def _render_runtime_instance_notice() -> None:
    action = st.session_state.pop("_runtime_instance_action", None)
    if isinstance(action, dict):
        status = str(action.get("status", ""))
        message = str(action.get("message", ""))
        if message:
            if status == "stopped":
                st.success(message)
            elif status == "requested":
                st.info(message)
            else:
                st.error(message)

    current = CURRENT_RUNTIME_INSTANCE
    if current is None:
        return
    try:
        others = list_other_runtime_instances(
            STORAGE_PATHS["runtime_instances"],
            current=current,
            app_name=APP_NAME,
            data_dir=STORAGE_PATHS["data"],
        )
    except OSError:
        return
    if not others:
        return

    with st.container(border=True):
        noun = "instance" if len(others) == 1 else "instances"
        verb = "uses" if len(others) == 1 else "use"
        st.warning(
            ui_message('ui.4a8b4b4708c789', p0=f'{len(others)}', p1=f'{noun}', p2=f'{verb}')
        )
        for instance in others:
            with st.container(horizontal=True, vertical_alignment="center", gap="small"):
                st.markdown(ui_message('ui.9d5eddf4c745ee', p0=f'{instance.port}'))
                st.caption(ui_message('ui.d155192d08532e'))
                if localized_button(
                    st,
                    ui_message('ui.b0aff7ae29fdd6', p0=f'{instance.port}'),
                    key=f"stop_runtime_instance_{instance.instance_id}",
                    help=(
                        ui_message('ui.42e281a72fa536', p0=f'{instance.port}')
                    ),
                    icon=":material/stop_circle:",
                ):
                    result = stop_runtime_instance(
                        instance,
                        app_name=APP_NAME,
                        data_dir=STORAGE_PATHS["data"],
                    )
                    st.session_state["_runtime_instance_action"] = {
                        "status": result.status,
                        "message": result.message,
                    }
                    st.rerun()


def _window_title(kicker: str, title: str, subtitle: str = "", *, tag: str = "") -> None:
    kicker, title, subtitle, tag = map(display_text, (kicker, title, subtitle, tag))
    subtitle_html = (
        f'<div class="rf-window-subtitle">{html.escape(subtitle)}</div>'
        if subtitle
        else ""
    )
    st.markdown(
        (
            f'<div class="rf-window-title" title="{html.escape(subtitle)}">'
            '<div class="rf-window-title-main">'
            f'<span class="section-kicker">{html.escape(kicker)}</span>'
            f'<div class="rf-window-title-text">{html.escape(title)}</div>'
            f"{subtitle_html}"
            '</div>'
            f'{_purpose_tag_html(tag)}'
            '</div>'
        ),
        unsafe_allow_html=True,
    )


def _clip_ui_frequencies(nyquist: float) -> None:
    frequency_suffixes = ("_fc", "_start", "_end", "_ref_freq")
    for key, value in list(st.session_state.items()):
        if key.endswith(frequency_suffixes) and isinstance(value, (int, float)):
            bounded = min(max(float(value), 0.0), nyquist)
            if bounded != value:
                st.session_state[key] = bounded


def _recommended_analysis_fft_size(sample_rate: int) -> int:
    return DEFAULT_ANALYSIS_FFT_SIZE_BY_SAMPLE_RATE.get(int(sample_rate), 16_384)


def _recommended_fir_taps(sample_rate: int) -> int:
    return DEFAULT_FIR_TAPS_BY_SAMPLE_RATE.get(int(sample_rate), DEFAULT_FIR_TAPS_BY_SAMPLE_RATE[48_000])


def _normalize_taps_value(value: int) -> int:
    return max(int(value), 1)


TAPS_INPUT_MESSAGE_KEY = "_taps_input_message"


def _normalize_taps_value_for_ui(value: int) -> int:
    raw_taps = int(value)
    normalized_taps = _normalize_taps_value(raw_taps)
    if raw_taps != normalized_taps:
        st.session_state[TAPS_INPUT_MESSAGE_KEY] = (
            "PhaseEQの出力FIRは1 tap以上です。"
            f"{raw_taps} tapsを{normalized_taps} tapsへ補正しました。"
        )
    return normalized_taps


def _effective_analysis_fft_size(selected_fft_size: int, taps: int) -> int:
    fft_size = max(int(selected_fft_size), int(taps))
    return next_fast_len(fft_size, real=True)


def _sync_taps_value() -> None:
    _set_design_condition_state(taps=_normalize_taps_value(st.session_state.get("taps", 1)))


def _sync_composite_iir_assignment(assignment: Any, *, apply: bool = True) -> bool:
    """Keep the Studio-owned IIR stage synchronized even for an existing tab."""
    received_iir = getattr(assignment, "iir_crossover", None)
    recipe = getattr(assignment, "band_split_recipe", None)
    if recipe is not None:
        from crossover_engine.recipe import validate, verify_iir_payload
        validate(recipe)
        if recipe["sample_rate_hz"] != assignment.sample_rate_hz or recipe["way"] != assignment.way:
            raise ValueError("Assignment band split recipe mismatch")
        if recipe.get("fir_enabled", True) != (assignment.tap_count > 0):
            raise ValueError("Assignment band split FIR state mismatch")
        verify_iir_payload(recipe, received_iir)
    if isinstance(received_iir, dict):
        coefficient_fs = int(received_iir.get("coefficient_sample_rate_hz", 0))
        sos = np.asarray(received_iir.get("sos", []), dtype=float)
        if coefficient_fs != int(getattr(assignment, "sample_rate_hz", 0)):
            raise ValueError("Composite IIR SOS sample rate does not match Assignment")
        if sos.size and (sos.ndim != 2 or sos.shape[1] != 6 or not np.isfinite(sos).all()):
            raise ValueError("Composite IIR SOS is invalid")
        for section in sos:
            if np.any(np.abs(np.roots(section[3:])) >= 1.0):
                raise ValueError("Composite IIR SOS is unstable")
        hash_fields = (
            "enabled", "family", "order", "highpass_hz", "lowpass_hz",
            "common_highpass_hz", "common_lowpass_hz", "overlap_oct", "lr2_polarity",
            "highpass_order", "lowpass_order",
        )
        hash_payload = {
            **{key: received_iir[key] for key in hash_fields if key in received_iir},
            "coefficient_sample_rate_hz": coefficient_fs,
        }
        actual_hash = hashlib.sha256(
            json.dumps(hash_payload, sort_keys=True, separators=(",", ":")).encode()
        ).hexdigest()
        if str(received_iir.get("definition_hash", "")) != actual_hash:
            raise ValueError("Composite IIR definition hash does not match SOS contract")
        if not apply:
            return False
        changed = st.session_state.get("_composite_iir_crossover") != received_iir
        st.session_state["_composite_iir_crossover"] = dict(received_iir)
    else:
        if not apply:
            return False
        changed = "_composite_iir_crossover" in st.session_state
        st.session_state.pop("_composite_iir_crossover", None)
    return changed


def _apply_composite_linear_fir_assignment(assignment: Any) -> None:
    """Keep the PhaseEQ preview synchronized with the Studio-owned band split."""
    assignment_id = str(getattr(assignment, "assignment_id", "")).strip()
    if not assignment_id:
        return
    iir_changed = _sync_composite_iir_assignment(assignment)
    st.session_state["band_split_recipe"] = getattr(assignment, "band_split_recipe", None)
    filters = [
        dict(item) for item in getattr(assignment, "linear_fir_filters", ())
        if isinstance(item, dict)
    ]
    if assignment.band_split_recipe is not None:
        from crossover_engine.recipe import adjacent_filter_parameters
        filters = adjacent_filter_parameters(assignment.band_split_recipe)
    assignment_is_current = (
        st.session_state.get("_composite_linear_fir_assignment_id") == assignment_id
        and _linear_fir_items_semantic(_items_for("linear_fir_items"))
        == _linear_fir_items_semantic(filters)
    )
    if assignment_is_current:
        if iir_changed:
            _invalidate_live_result_cache()
        return
    modes = {str(item.get("mode", "")) for item in filters}
    profile = "Mid" if modes == {"hp", "lp"} else "Hi" if modes == {"hp"} else "Lo" if modes == {"lp"} else "Pass"
    for item in filters:
        mode = "hp" if str(item.get("mode", "")) == "hp" else "lp"
        st.session_state[f"linear_fir_{mode}_response"] = _normalize_output_band_split_method(
            item.get("response", "kaiser")
        )
        st.session_state[f"linear_fir_{mode}_fc"] = float(item["fc"])
        st.session_state[f"linear_fir_{mode}_cycles"] = float(item["cycles"])
        st.session_state[f"linear_fir_{mode}_beta"] = float(item["beta"])
    _set_registry_items("linear_fir_items", filters)
    st.session_state["_linear_fir_domain_profile"] = profile
    st.session_state["linear_fir_active_profile"] = profile
    _set_setting_and_widget("linear_fir_profile", profile, "__sel_val_")
    _clear_linear_fir_parameter_widget_state()
    st.session_state["_composite_linear_fir_assignment_id"] = assignment_id
    _invalidate_live_result_cache()


def _apply_composite_target_assignment(assignment: Any) -> None:
    """Apply a Composite Group Target to PhaseEQ's normal Target state."""
    definition = getattr(assignment, "target_definition", None)
    if not isinstance(definition, dict):
        return
    revision = str(definition.get("revision", "")).strip()
    assignment_id = str(getattr(assignment, "assignment_id", "")).strip()
    applied_key = f"{assignment_id}:{revision}"
    if not assignment_id or not revision:
        return
    if st.session_state.get("_composite_target_assignment_revision") == applied_key:
        return
    application = str(getattr(assignment, "target_application", "legacy_apply"))
    if application == "display_only":
        st.session_state["_composite_channel_target_reference"] = dict(definition)
        st.session_state["_composite_target_assignment_revision"] = applied_key
        st.session_state["_settings_notice"] = (
            f"旧形式の表示用Targetを読み込みました（DSP非適用）: "
            f"{definition.get('name', 'Selected Target')} / revision {revision[:12]}"
        )
        return
    _apply_target_settings_payload_to_state({
        "settings_file_revision": CURRENT_SETTINGS_FILE_REVISION,
        "target": {
            "target_url": str(definition.get("target_url", "")),
            "target_source_name": str(
                definition.get("target_source_name")
                or definition.get("name", "Group Target")
            ),
            "target_response_raw": definition.get("target_response_raw"),
            "target_gain_shift_mode": str(
                definition.get("level_mode", TARGET_GAIN_SHIFT_MODE_OPTIONS[0])
            ),
            "target_gain_shift_db": (
                float(definition.get("level_db", 0.0))
                + float(definition.get("application_gain_db", 0.0))
            ),
            "target_source_content_mode": str(
                definition.get("source_content_mode", TARGET_SOURCE_CONTENT_MODE_OPTIONS[0])
            ),
            "target_phase_enabled": bool(definition.get("phase_enabled", True)),
            "target_lf_extension_enabled": bool(definition.get("lf_extension_enabled", False)),
            "target_hf_extension_enabled": bool(definition.get("hf_extension_enabled", False)),
            "target_response_edit": dict(definition.get("target_edit", {})),
        },
    })
    if st.session_state.get("speaker_gain_shift_mode", SPEAKER_GAIN_SHIFT_MODE_OPTIONS[0]) == SPEAKER_GAIN_SHIFT_MODE_OPTIONS[0]:
        _set_setting_and_widget("speaker_gain_shift_mode", TARGET_LEVEL_MODE, "__rad_val_", "speaker_gain_shift_mode_widget")
    st.session_state["_composite_group_target_reference"] = dict(definition)
    st.session_state["_composite_target_assignment_revision"] = applied_key
    st.session_state["_settings_notice"] = (
        f"Composite Group TargetをPhaseEQ Targetへ適用しました: "
        f"{definition.get('name', 'Selected Target')} / revision {revision[:12]}"
    )


def _enforce_standalone_target_scope() -> None:
    """Do not restore Channel crossover targets in a standalone editor."""
    if st.session_state.get("_active_context_assignment") is not None:
        return
    recipe = st.session_state.get("band_split_recipe")
    inherited = recipe is not None or st.session_state.get("_composite_linear_fir_assignment_id")
    items = _items_for("linear_fir_items")
    if inherited:
        st.session_state["_detached_channel_band_split"] = deepcopy({
            "recipe": recipe, "filters": items,
            "iir": st.session_state.get("_composite_iir_crossover"),
        })
        st.session_state["band_split_recipe"] = None
        st.session_state.pop("_composite_linear_fir_assignment_id", None)
        st.session_state.pop("_composite_iir_crossover", None)
        _sync_linear_fir_registry([], profile="None")
        _clear_linear_fir_parameter_widget_state()
    else:
        # Standalone owns these target choices, including when FIR is OFF.
        return
    for side in ("hp", "lp"):
        st.session_state[f"linear_fir_{side}_acoustic_target"] = False
    # Layout recall must not resurrect a Channel's acoustic target flags.
    memory = deepcopy(st.session_state.get("linear_fir_profile_memory", {}))
    for profile in memory.values():
        for item in profile.values():
            item["acoustic_target"] = False
    st.session_state["linear_fir_profile_memory"] = memory


