def _advisor_japanese_title(card: DiagnosisCard) -> str:
    return ADVISOR_CATEGORY_LABELS.get(card.category, "確認ポイント")


def _advisor_japanese_summary(card: DiagnosisCard) -> str:
    text_by_category = {
        "direct_peak": "直接音主体のピークです。まず軽いCut候補にできます。",
        "reflection_dip": "反射やキャンセル由来の可能性があります。Boostは避けます。",
        "broad_tonal_dip": "音色として聞こえやすい広めの落ち込みです。Target側を少し緩める候補です。",
        "narrow_ringing": "共振や鳴きとして耳につく可能性があります。強い補正は避けます。",
        "phase_instability": "位相または時間軸が不安定です。Phase補正は控えめにします。",
        "excess_time_energy": "時間方向に残るエネルギーが多い帯域です。必要なら軽く下げます。",
        "delayed_energy": "遅れ成分が目立つ帯域です。Boostや強いPhase補正は慎重にします。",
        "fir_limit": "現在のtap数では低域側の補正が難しい可能性があります。",
        "stable_region": "差が小さく安定しています。基準帯域として大きく触らず使えます。",
    }
    return text_by_category.get(card.category, card.summary)


def _advisor_metric_summary(card: DiagnosisCard) -> str:
    metric_labels = {
        "peak_error_db": "ピーク差",
        "dip_error_db": "落ち込み",
        "max_error_db": "最大差",
        "phase_error_deg": "位相差",
        "group_delay_dev_ms": "GD差",
        "delay_ms": "遅れ",
        "spread_ms": "広がり",
        "excess_energy_db": "時間残り",
        "cycles_at_hpf": "HPF周期数",
        "duration_ms": "FIR長",
    }
    parts: list[str] = []
    for key, label in metric_labels.items():
        if key not in card.metrics:
            continue
        value = card.metrics[key]
        suffix = ""
        if key.endswith("_db"):
            suffix = " dB"
        elif key.endswith("_deg"):
            suffix = " 度"
        elif key.endswith("_ms"):
            suffix = " ms"
        parts.append(f"{label}: {value}{suffix}")
    return " / ".join(parts)


def _render_response_advisor(cards: list[DiagnosisCard]) -> None:
    if not cards:
        st.info(ui_message('ui.fb48edcf39e607'))
        return
    severity_order = ["danger", "warning", "info", "good"]
    summary_cols = st.columns(4)
    for idx, severity in enumerate(severity_order):
        count = sum(1 for card in cards if card.severity == severity)
        summary_cols[idx].metric(ADVISOR_SEVERITY_LABELS[severity], str(count))
    rows = [
        {
            "判定": ADVISOR_SEVERITY_LABELS.get(card.severity, "参考"),
            "内容": _advisor_japanese_title(card),
            "中心Hz": round_for_display(card.f_center_hz, 1),
            "範囲Hz": f"{card.f_start_hz:.0f}-{card.f_end_hz:.0f}",
            "対応": ADVISOR_ACTION_LABELS.get(card.action, "確認"),
        }
        for card in cards
    ]
    st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
    for card in cards:
        with st.container(border=True):
            st.markdown(ui_message('ui.dd92e1b4b77753', p0=f"{ADVISOR_SEVERITY_LABELS.get(card.severity, '参考')}", p1=f'{_advisor_japanese_title(card)}'))
            st.caption(ui_message('ui.55a1b0c6ef87d5', p0=f'{card.f_center_hz:.0f}', p1=f'{card.f_start_hz:.0f}', p2=f'{card.f_end_hz:.0f}'))
            st.write(_advisor_japanese_summary(card))
            st.info(ADVISOR_ACTION_LABELS.get(card.action, "測定とTargetを確認してください。"))
            metric_text = _advisor_metric_summary(card)
            if metric_text:
                st.caption(metric_text)


def _display_analysis_cache() -> display_analysis.AnalysisCache:
    cache = st.session_state.get("_display_analysis_cache")
    if not isinstance(cache, display_analysis.AnalysisCache):
        cache = display_analysis.AnalysisCache()
        st.session_state["_display_analysis_cache"] = cache
    return cache


def _time_analysis_fft_size(sample_rate: int, taps: int) -> int:
    n = display_analysis.fft_length(sample_rate, st.session_state.get("display_fft_multiplier", 1))
    if taps > n:
        raise ValueError("FIR長が表示解析長を超えています。2倍・4倍を確認してください。4倍でも超える場合は時間応答を表示できません。出力係数は変更しません。")
    return n


def _display_response_bundles(result, speaker, target, sample_rate, iir_filters=None,
                              *, config=None, stage=None, fir_enabled=True):
    """Application adapter: inputs are already at the selected page's stage."""
    cache = _display_analysis_cache()
    n = _time_analysis_fft_size(sample_rate, len(result.fir))
    sources = {}
    for name, response in (("Speaker/Input", speaker), ("Target Response", target)):
        if response is None or response.phase_deg is None:
            continue
        try:
            sources[name] = display_analysis.measurement(
                cache, name, sample_rate, n, response.frequency, response.gain_db,
                response.phase_deg, speaker=name == "Speaker/Input")
        except ValueError as exc:
            # Only this invalid time series is omitted; Gain remains available.
            st.warning(ui_message('ui.07e3a63ea0ed5b', p0=f'{name}', p1=f'{exc}'))
            continue
    if stage in {"Speaker/Input", "Target Response"}:
        return sources
    if iir_filters is None:
        correction = display_analysis.fir_response(
            cache, result.fir if fir_enabled else np.ones(1), sample_rate, n)
        if config is not None and stage == "Linear FIR":
            # These crossover stages are outside result.fir. Match the design
            # adapter's branch order, including Recipe ownership and LR2 sign.
            recipe = config.band_split_recipe
            if recipe is not None:
                from crossover_engine.alignment import output_response
                def evaluate_recipe():
                    h = output_response(recipe, correction.frequency)
                    return display_analysis.bundle("recipe_iir", sample_rate, n, h,
                                                    (display_analysis.digest(recipe),))
                extra = cache.get(display_analysis.digest("recipe_iir", recipe, sample_rate, n), evaluate_recipe)
                correction = display_analysis.multiply(cache, correction, extra)
            else:
                filters = band_split_iir_filters(config)
                if filters:
                    correction = display_analysis.multiply(cache, correction,
                        display_analysis.sos_response(cache, cascade_iir_sos(filters, sample_rate), sample_rate, n))
                payload = st.session_state.get("_composite_iir_crossover")
                if isinstance(payload, dict) and payload.get("enabled"):
                    if int(payload.get("coefficient_sample_rate_hz", 0)) != sample_rate:
                        raise ValueError("Composite IIR SOSのサンプルレートが一致しません。")
                    sos = np.asarray(payload.get("sos", []), float)
                    if sos.size:
                        extra = display_analysis.sos_response(cache, sos, sample_rate, n)
                        polarity = int(payload.get("lr2_polarity", 1))
                        extra = cache.get(display_analysis.digest("external_iir", extra.key, polarity),
                            lambda: display_analysis.bundle("external_iir", sample_rate, n,
                                extra.response * polarity, extra.stages))
                        correction = display_analysis.multiply(cache, correction, extra)
        if stage == "Export FIR" and config is not None:
            sources["FIR Output"] = correction
            extra = display_analysis.sos_response(cache, export_iir_sos(
                config, st.session_state.get("_composite_iir_crossover")), sample_rate, n)
            sources["IIR Output"] = extra
            correction = display_analysis.multiply(cache, correction, extra)
            sources["FIR + IIR Output"] = correction
        else:
            sources["Correction Filter Realized"] = correction
        after = "Speaker + Realized"
    else:
        correction = display_analysis.sos_response(
            cache, cascade_iir_sos(iir_filters, sample_rate), sample_rate, n)
        sources["IIR Filter"] = correction
        after = "IIR Result"
    if "Speaker/Input" in sources:
        sources[after] = display_analysis.multiply(cache, sources["Speaker/Input"], correction)
    if "Target Response" in sources:
        sources["Target Response"] = sources.pop("Target Response")
    return sources


def _display_time_series(sources, taps, requested):
    cache = _display_analysis_cache()
    indices = np.arange(taps) - taps//2
    impulses, steps, delays = {"tap": indices}, {"tap": indices}, {}
    for name, response in sources.items():
        if requested == "Group Delay":
            delays["frequency"] = response.frequency
            delays[name] = display_analysis.derive(cache, response, "gd")
            if name == "Correction Filter Realized":
                # Existing PhaseEQ coefficient GD includes its causal tap center.
                delays[name] = delays[name] + (taps-1)/2/response.fs*1000
        else:
            view = "step" if requested == "Step" else "impulse"
            values = display_analysis.derive(cache, response, view)
            selected = values[response.n//2 + indices]
            (steps if view == "step" else impulses)[name] = selected
    return impulses, steps, delays


def _group_delay_from_phase_ms(frequency: np.ndarray, phase_deg: np.ndarray) -> np.ndarray:
    frequency = np.asarray(frequency, dtype=float)
    phase_deg = np.asarray(phase_deg, dtype=float)
    if frequency.size < 2:
        return np.zeros_like(frequency)
    gradient_deg_per_hz = np.gradient(phase_deg, frequency, edge_order=1)
    return np.nan_to_num(-gradient_deg_per_hz / 360.0 * 1000.0)


def _load_measurement_inputs(
    speaker_file: Any,
    speaker_url: str,
    mic_cal_file: Any,
    apply_mic_cal: bool,
    sample_rate: int,
) -> tuple[SpeakerResponse | None, SpeakerResponse | None, list[str], str, str, np.ndarray | None, int | None, str]:
    messages: list[str] = []
    mic_cal_response = None
    mic_cal_source_name = ""
    if mic_cal_file is not None:
        try:
            mic_cal_response = load_uploaded_speaker_response(mic_cal_file).speaker_response
            mic_cal_source_name = mic_cal_file.name
            messages.append(f"Mic Calibration: {mic_cal_file.name} / {len(mic_cal_response.frequency)} rows")
        except Exception as exc:
            messages.append(f"Mic Calibration import skipped: {exc}")

    speaker_response = None
    speaker_impulse = None
    speaker_impulse_sample_rate = None
    speaker_source_type = "reconstructed_from_response"
    source_note = ""
    if speaker_file is not None or speaker_url.strip():
        try:
            if speaker_file is not None:
                try:
                    loaded = load_uploaded_speaker_response(speaker_file)
                    speaker_response = loaded.speaker_response
                    speaker_impulse = loaded.impulse
                    speaker_impulse_sample_rate = loaded.impulse_sample_rate
                    speaker_source_type = loaded.source_type
                    source_note = loaded.source_name
                except ValueError:
                    text = decode_uploaded_text(speaker_file)
                    detected_url = extract_first_url(text)
                    if detected_url is None:
                        raise
                    speaker_response = load_speaker_response_url(detected_url)
                    source_note = detected_url
            else:
                speaker_response = load_speaker_response_url(speaker_url.strip())
                source_note = speaker_url.strip()

            # Keep the imported response raw. Calibration belongs to P0 and is
            # recomputed from this immutable input when its settings change.
            messages.append(f"Speaker/Input: {source_note} / {len(speaker_response.frequency)} rows")
        except Exception as exc:
            messages.append(
                "Speaker/Input import skipped: 数値データを読み込めませんでした。"
                "FRD/TXT/CSV本体、mono WAV impulse、またはデータURLを指定してください。"
                f" 詳細: {exc}"
            )
    return (
        speaker_response,
        mic_cal_response,
        messages,
        source_note,
        mic_cal_source_name,
        speaker_impulse,
        speaker_impulse_sample_rate,
        speaker_source_type,
    )


def _load_near_field_input(file_obj: Any, label: str) -> tuple[SpeakerResponse | None, list[str]]:
    if file_obj is None:
        return None, []
    try:
        loaded = load_uploaded_speaker_response(file_obj)
        return loaded.speaker_response, [f"{label}: {loaded.source_name} / {len(loaded.speaker_response.frequency)} rows"]
    except Exception as exc:
        return None, [f"{label} import skipped: {exc}"]


def _load_response_from_file_or_url(file_obj: Any, url: str) -> tuple[SpeakerResponse | None, str]:
    if file_obj is None and not url.strip():
        return None, ""
    if file_obj is not None:
        if str(getattr(file_obj, "name", "")).lower().endswith(".wav"):
            loaded = load_uploaded_target_response(file_obj)
            return loaded.speaker_response, loaded.source_name
        text = decode_uploaded_text(file_obj)
        try:
            loaded = load_uploaded_target_response(file_obj)
            return loaded.speaker_response, loaded.source_name
        except ValueError:
            detected_url = extract_first_url(text)
            if detected_url is None:
                raise
            return load_speaker_response_url(detected_url), detected_url
    source_name = url.strip()
    return load_speaker_response_url(source_name), source_name


def _target_gain_shift_db(
    target: SpeakerResponse | None,
    speaker: SpeakerResponse | None,
    mode: str,
    manual_shift_db: float,
) -> float:
    return _target_gain_shift_estimate(target, speaker, mode, manual_shift_db).shift_db


def _target_gain_shift_estimate(
    target: SpeakerResponse | None,
    speaker: SpeakerResponse | None,
    mode: str,
    manual_shift_db: float,
) -> TargetGainShiftEstimate:
    if target is None:
        return TargetGainShiftEstimate(0.0, 0.0, -15.0, 0)
    if mode == "手動シフト":
        return TargetGainShiftEstimate(float(manual_shift_db), 0.0, -15.0, 0)
    if speaker is None:
        return TargetGainShiftEstimate(float(manual_shift_db), 0.0, -15.0, 0)
    return estimate_target_auto_gain_shift(target, speaker, manual_shift_db=manual_shift_db)


def _speaker_gain_shift_estimate(
    speaker: SpeakerResponse | None,
    target: SpeakerResponse | None,
    mode: str,
    manual_shift_db: float,
    source_impulse: np.ndarray | None = None,
    source_sample_rate: int | None = None,
) -> SpeakerGainShiftEstimate:
    if speaker is None:
        return SpeakerGainShiftEstimate(0.0, 0.0, 0.0, -15.0, 0, False)
    if mode == "手動シフト":
        return SpeakerGainShiftEstimate(float(manual_shift_db), 0.0, 0.0, -15.0, 0, False)
    return estimate_speaker_auto_gain_shift(
        speaker,
        manual_shift_db=manual_shift_db,
        source_impulse=source_impulse,
        source_sample_rate=source_sample_rate,
    )


def _shift_speaker_response_gain(speaker: SpeakerResponse | None, shift_db: float) -> SpeakerResponse | None:
    if speaker is None:
        return None
    shifted_gain = (np.asarray(speaker.gain_db, dtype=float) + float(shift_db)).tolist()
    return SpeakerResponse(
        frequency=speaker.frequency,
        gain_db=shifted_gain,
        phase_deg=speaker.phase_deg,
    )


def _shift_target_response_gain(target: SpeakerResponse | None, shift_db: float) -> SpeakerResponse | None:
    if target is None:
        return None
    shifted_gain = (np.asarray(target.gain_db, dtype=float) + float(shift_db)).tolist()
    return SpeakerResponse(
        frequency=target.frequency,
        gain_db=shifted_gain,
        phase_deg=target.phase_deg,
    )


def _has_enabled_filters(filters: list[Any]) -> bool:
    return any(bool(getattr(item, "enabled", False)) for item in filters)


def _has_target_source_or_edit_configured() -> bool:
    if _current_text_setting("target_url", "").strip():
        return True
    if st.session_state.get("_restored_target_response_raw") is not None:
        return True
    target_edit = _target_edit_payload_from_state()
    edit_groups = (
        "gain_peq",
        "gain_shelf",
        "gain_linear",
        "gain_tilt",
        "phase_peq",
        "phase_shelf",
        "phase_tilt",
        "phase_allpass",
    )
    return any(
        bool(item.get("enabled", True))
        for group in edit_groups
        for item in target_edit.get(group, [])
        if isinstance(item, dict)
    )


def _target_edit_axis(
    base_target: SpeakerResponse | None,
    sample_rate: int,
    analysis_fft_size: int,
) -> np.ndarray:
    nyquist = float(sample_rate) / 2.0
    if base_target is not None:
        frequency = np.asarray(base_target.frequency, dtype=float)
        frequency = frequency[np.isfinite(frequency)]
        frequency = np.clip(frequency, 0.0, nyquist)
        frequency = np.unique(frequency)
        if frequency.size:
            return frequency
    return frequency_axis(sample_rate, analysis_fft_size)


def _flat_target_response_for_edit(
    sample_rate: int,
    analysis_fft_size: int,
) -> SpeakerResponse:
    frequency = frequency_axis(sample_rate, analysis_fft_size)
    return SpeakerResponse(
        frequency=frequency.tolist(),
        gain_db=np.zeros_like(frequency, dtype=float).tolist(),
        phase_deg=None,
    )


def _apply_target_response_edits(
    base_target: SpeakerResponse | None,
    *,
    sample_rate: int,
    analysis_fft_size: int,
    target_gain_peq_filters: list[GainPEQ],
    target_gain_shelf_filters: list[GainShelf],
    target_gain_linear_filters: list[GainLinearFilter],
    target_gain_tilt_filters: list[GainTilt],
    target_gain_tilt_smoothing_oct: float,
    target_phase_peq_filters: list[PhasePEQ],
    target_phase_shelf_filters: list[PhaseShelf],
    target_phase_tilt_filters: list[PhaseTilt],
    target_phase_tilt_smoothing_oct: float,
    target_phase_allpass_filters: list[PhaseAllPass],
    target_iir_filters: list[IIRFilter],
    source_gain_only: bool = False,
) -> SpeakerResponse | None:
    payload = {
        "gain_peq": [asdict(item) for item in target_gain_peq_filters],
        "gain_shelf": [asdict(item) for item in target_gain_shelf_filters],
        "gain_linear": [asdict(item) for item in target_gain_linear_filters],
        "gain_tilt": [asdict(item) for item in target_gain_tilt_filters],
        "gain_tilt_smoothing_oct": float(target_gain_tilt_smoothing_oct),
        "phase_peq": [asdict(item) for item in target_phase_peq_filters],
        "phase_shelf": [asdict(item) for item in target_phase_shelf_filters],
        "phase_tilt": [asdict(item) for item in target_phase_tilt_filters],
        "phase_tilt_smoothing_oct": float(target_phase_tilt_smoothing_oct),
        "phase_allpass": [asdict(item) for item in target_phase_allpass_filters],
        "iir_filters": [asdict(item) for item in target_iir_filters],
    }
    return apply_target_edit_to_response(
        base_target,
        sample_rate_hz=int(sample_rate),
        analysis_fft_size=int(analysis_fft_size),
        payload=payload,
        source_gain_only=bool(source_gain_only),
    )
def _preview_response_values(
    response: SpeakerResponse,
    frequency: np.ndarray,
) -> tuple[np.ndarray, np.ndarray | None]:
    gain, phase, has_phase = _response_on_axis(response, frequency)
    source_frequency = np.asarray(response.frequency, dtype=float)
    valid_source = source_frequency[np.isfinite(source_frequency) & (source_frequency > 0.0)]
    if valid_source.size:
        covered = (frequency >= float(np.min(valid_source))) & (frequency <= float(np.max(valid_source)))
        gain = np.where(covered, gain, np.nan)
        phase = np.where(covered, phase, np.nan)
    return gain, phase if has_phase else None


def _preview_frequency_axis(config: DesignConfig, responses: list[SpeakerResponse] | None = None) -> np.ndarray:
    frequency = frequency_axis(int(config.sample_rate), int(config.analysis_fft_size))
    if responses:
        response_max = max(
            (_response_max_frequency(response) or 0.0 for response in responses),
            default=0.0,
        )
        if response_max > 0.0:
            frequency = frequency[frequency <= min(response_max, float(config.sample_rate) / 2.0)]
    return frequency if frequency.size else frequency_axis(int(config.sample_rate), int(config.analysis_fft_size))


SELECTION_PREVIEW_GAIN_RANGE_OPTIONS = [
    "Auto (40 dB)",
    "20 dB",
    "40 dB",
    "60 dB",
    "80 dB",
    "120 dB",
]


def _selection_preview_gain_span_control() -> float:
    state_key = "_selection_preview_gain_range"
    widget_key = "selection_preview_gain_range_widget"
    selected = str(st.session_state.get(state_key, SELECTION_PREVIEW_GAIN_RANGE_OPTIONS[0]))
    if selected not in SELECTION_PREVIEW_GAIN_RANGE_OPTIONS:
        selected = SELECTION_PREVIEW_GAIN_RANGE_OPTIONS[0]
    if widget_key not in st.session_state:
        st.session_state[widget_key] = selected
    selected = str(
        localized_segmented_control(
            ui_message('ui.84694d41ccb525'),
            SELECTION_PREVIEW_GAIN_RANGE_OPTIONS,
            key=widget_key,
            width="stretch",
            help=ui_message('ui.edce29efbf1ab1'),
        )
        or selected
    )
    st.session_state[state_key] = selected
    if selected == SELECTION_PREVIEW_GAIN_RANGE_OPTIONS[0]:
        return 40.0
    return float(selected.split()[0])


def _selection_preview_gain_domain(
    gain_series: dict[str, np.ndarray],
    *,
    span_db: float = 40.0,
) -> list[float] | None:
    values = [
        np.asarray(series, dtype=float).ravel()
        for name, series in gain_series.items()
        if name != "frequency"
    ]
    if not values:
        return None
    finite = np.concatenate(values)
    finite = finite[np.isfinite(finite)]
    if finite.size == 0:
        return None

    # Keep the acoustic peak visible with a small upper margin while retaining
    # the selected comparison width across every Selection preview.
    peak = float(np.max(finite))
    upper = float(np.ceil((peak + 3.0) / 5.0) * 5.0)
    return [upper - float(span_db), upper]


def _render_preview_gain_phase(
    responses: list[tuple[str, SpeakerResponse]],
    config: DesignConfig,
    *,
    boundary_markers: list[dict[str, Any]] | None = None,
) -> None:
    if not responses:
        st.info(ui_message('ui.3888f2ef212f49'))
        return
    frequency = _preview_frequency_axis(config, [response for _, response in responses])
    gain_series: dict[str, np.ndarray] = {"frequency": frequency}
    phase_series: dict[str, np.ndarray] = {"frequency": frequency}
    for label, response in responses:
        gain, phase = _preview_response_values(response, frequency)
        gain_series[label] = gain
        if phase is not None:
            phase_series[label] = phase
    gain_span_db = _selection_preview_gain_span_control()
    st.markdown(ui_message('ui.0540656d429ced'))
    _series_chart(
        gain_series,
        y_domain=_selection_preview_gain_domain(gain_series, span_db=gain_span_db),
        boundary_markers=boundary_markers,
    )
    if len(phase_series) > 1:
        st.markdown(ui_message('ui.4e7301dde15566'))
        _series_chart(
            phase_series,
            y_domain=[-180.0, 180.0],
            break_wrapped_phase=True,
            boundary_markers=boundary_markers,
        )
    else:
        st.caption(ui_message('ui.c5e5b9bcbe1e8f'))


def _render_measurement_selection_preview(record: SpeakerMeasurementRecord, config: DesignConfig) -> None:
    if record.source_type == "impedance":
        payload = record.response_payload or {}
        frequency = np.asarray(payload.get("frequency", []), dtype=float)
        impedance = np.asarray(payload.get("impedance_ohm", []), dtype=float)
        if frequency.size == 0 or impedance.size != frequency.size:
            st.info(ui_message('ui.44afbeffab4fa5'))
            return
        st.markdown(ui_message('ui.2161402a974a88'))
        _series_chart({"frequency": frequency, "Impedance Ω": impedance})
        phase = np.asarray(payload.get("phase_deg", []), dtype=float)
        if phase.size == frequency.size:
            st.markdown(ui_message('ui.4e7301dde15566'))
            _series_chart(
                {"frequency": frequency, "Impedance phase": phase},
                y_domain=[-180.0, 180.0],
                break_wrapped_phase=True,
            )
        else:
            st.caption(ui_message('ui.53abe7e2010669'))
        return

    responses: list[tuple[str, SpeakerResponse]] = []
    if record.source_type == "speaker_input_raw":
        speaker = speaker_input_from_measurement_payload(record.response_payload)
        if speaker is not None:
            responses.append(("Speaker/Input", speaker))
        woofer = near_field_woofer_from_measurement_payload(record.response_payload)
        if woofer is not None:
            responses.append(("Near-field woofer", woofer))
        port = near_field_port_from_measurement_payload(record.response_payload)
        if port is not None:
            responses.append(("Near-field port", port))
    else:
        response = speaker_response_from_payload(record.response_payload)
        if response is not None:
            label = "Mic Calibration" if record.source_type == "mic_calibration_raw" else record.name
            responses.append((label, response))
    _render_preview_gain_phase(responses, config)


def _render_selection_preview(request: dict[str, Any], config: DesignConfig) -> None:
    header_col, action_col = st.columns([0.72, 0.28], gap="medium", vertical_alignment="center")
    with header_col:
        _window_title(ui_message('ui.59e1f415bf9d77'), ui_message('ui.f89ebf24860062'), ui_message('ui.999f6d057a021f'))
    with action_col:
        if localized_button(
            st,
            ui_message('ui.67f859b0612736'),
            key="selection_preview_back_to_live",
            icon=":material/arrow_back:",
            help=ui_message('ui.1f438731bd83b5'),
        ):
            _clear_selection_preview(suppress_current=True)
            st.rerun()
    st.info(ui_message('ui.caad28bb0a9a4c'), icon=":material/visibility:")
    st.markdown(ui_message('ui.061bd94945ee5b', p0=f"{str(request.get('name', 'Selected item'))}"))
    subtitle = str(request.get("subtitle", "")).strip()
    if subtitle:
        st.caption(subtitle)

    kind = str(request.get("kind", ""))
    record_id = str(request.get("record_id", ""))
    if kind == "target_preset":
        definition = get_shared_target_preset(APP_ROOT, record_id)
        if definition is None:
            st.warning(ui_message('ui.075d7c9cad9bbc'))
            return
        raw = speaker_response_from_payload(definition.get("target_response_raw"))
        if raw is None and str(definition.get("target_url", "")).strip():
            st.info(ui_message('ui.eac1238ee162d7'))
            return
        preview = process_target(
            raw,
            TargetProcessingSettings(
                sample_rate=int(config.sample_rate), analysis_fft_size=int(config.analysis_fft_size),
                gain_shift_mode=str(definition.get("level_mode", "Off")),
                manual_gain_shift_db=float(definition.get("level_db", 0.0)),
                source_gain_only=definition.get("source_content_mode") == "Gain only",
                phase_enabled=bool(definition.get("phase_enabled", True)), zero_missing_phase=True,
                lf_extension_enabled=bool(definition.get("lf_extension_enabled", False)),
                hf_extension_enabled=bool(definition.get("hf_extension_enabled", False)),
            ),
            speaker_reference=config.speaker_response,
            response_editor=lambda base: apply_target_edit_to_response(
                base, sample_rate_hz=int(config.sample_rate),
                analysis_fft_size=int(config.analysis_fft_size), payload=definition.get("target_edit", {}),
            ),
        )
        st.caption(ui_message('ui.351c4d4d5cf182'))
        _render_preview_gain_phase([("Target Response", preview.effective_response)], config)
        return
    if kind == "measurement":
        record = get_measurement(SPEAKER_MEASUREMENTS_DB_FILE, record_id)
        if record is None:
            st.warning(ui_message('ui.37a05b5fa90ec3'))
        else:
            _render_measurement_selection_preview(record, config)
        return
    if kind == "current_input":
        if config.speaker_response is None:
            st.info(ui_message('ui.53add1ca08c952'))
        else:
            _render_preview_gain_phase([("Speaker/Input", config.speaker_response)], config)
        return
    if kind == "current_mic":
        mic = st.session_state.get("_restored_mic_cal_response_raw")
        if not isinstance(mic, SpeakerResponse):
            st.info(ui_message('ui.cae8e20fae4508'))
        else:
            _render_preview_gain_phase([("Mic Calibration", mic)], config)
        return
    if kind == "empty":
        st.info(ui_message('ui.452ca95e325c95'))
        return
    st.warning(ui_message('ui.bf7ad58ddecaeb'))


def _apply_mic_calibration(speaker: SpeakerResponse, mic_cal: SpeakerResponse) -> SpeakerResponse:
    from phase_fir_designer.input_pipeline import apply_mic_calibration
    return apply_mic_calibration(speaker, mic_cal)


def _minimum_phase_from_gain_db(frequency: np.ndarray, gain_db: np.ndarray) -> np.ndarray:
    frequency = np.asarray(frequency, dtype=float)
    gain_db = np.asarray(gain_db, dtype=float)
    valid = np.isfinite(frequency) & np.isfinite(gain_db) & (frequency >= 0)
    if np.count_nonzero(valid) < 2:
        return np.zeros_like(frequency, dtype=float)

    valid_freq = frequency[valid]
    valid_gain = gain_db[valid]
    order = np.argsort(valid_freq)
    valid_freq = valid_freq[order]
    valid_gain = valid_gain[order]
    positive = valid_freq > 0
    if not np.any(positive):
        return np.zeros_like(frequency, dtype=float)

    f_min = float(np.min(valid_freq[positive]))
    f_max = float(np.max(valid_freq))
    n_fft = 1 << 15
    uniform_freq = np.linspace(0.0, f_max, n_fft // 2 + 1)
    interp_freq = np.maximum(uniform_freq, f_min)
    uniform_gain = np.interp(
        interp_freq,
        valid_freq,
        valid_gain,
        left=valid_gain[0],
        right=valid_gain[-1],
    )
    log_mag = np.log(np.maximum(10.0 ** (uniform_gain / 20.0), 1e-9))
    full_log_mag = np.concatenate([log_mag, log_mag[-2:0:-1]])
    cepstrum = np.fft.ifft(full_log_mag).real
    min_cepstrum = np.zeros_like(cepstrum)
    min_cepstrum[0] = cepstrum[0]
    min_cepstrum[1 : n_fft // 2] = 2.0 * cepstrum[1 : n_fft // 2]
    min_cepstrum[n_fft // 2] = cepstrum[n_fft // 2]
    min_phase_spectrum = np.fft.fft(min_cepstrum)
    uniform_phase = np.rad2deg(np.unwrap(np.imag(min_phase_spectrum[: n_fft // 2 + 1])))
    return np.interp(
        np.clip(frequency, 0.0, f_max),
        uniform_freq,
        uniform_phase,
        left=uniform_phase[0],
        right=uniform_phase[-1],
    )


def _apply_speaker_phase_mode(
    speaker: SpeakerResponse | None,
    phase_mode: str,
) -> SpeakerResponse | None:
    if speaker is None:
        return None
    if phase_mode == "位相を使わない":
        return SpeakerResponse(
            frequency=speaker.frequency,
            gain_db=speaker.gain_db,
            phase_deg=None,
        )
    if phase_mode == "Gainのみから最小位相を生成":
        frequency = np.asarray(speaker.frequency, dtype=float)
        gain = np.asarray(speaker.gain_db, dtype=float)
        minimum_phase = _minimum_phase_from_gain_db(frequency, gain)
        return SpeakerResponse(
            frequency=speaker.frequency,
            gain_db=speaker.gain_db,
            phase_deg=minimum_phase.tolist(),
        )
    return speaker


def _invert_speaker_polarity(speaker: SpeakerResponse | None) -> SpeakerResponse | None:
    if speaker is None:
        return None
    if speaker.phase_deg is None:
        phase = np.full(len(speaker.frequency), 180.0, dtype=float)
    else:
        phase = np.asarray(speaker.phase_deg, dtype=float) + 180.0
    return SpeakerResponse(
        frequency=speaker.frequency,
        gain_db=speaker.gain_db,
        phase_deg=phase.tolist(),
    )


def _unwrap_speaker_phase_response(speaker: SpeakerResponse | None) -> SpeakerResponse | None:
    if speaker is None or speaker.phase_deg is None:
        return speaker
    phase = np.rad2deg(np.unwrap(np.deg2rad(np.asarray(speaker.phase_deg, dtype=float))))
    return SpeakerResponse(
        frequency=speaker.frequency,
        gain_db=speaker.gain_db,
        phase_deg=phase.tolist(),
    )


def _smooth_speaker_response(
    speaker: SpeakerResponse | None,
    smoothing_fraction: float,
    smoothing_mode: str,
) -> SpeakerResponse | None:
    mode = "complex_gain" if smoothing_mode == "Complex Gain" else "gain_phase"
    return smooth_speaker_response(speaker, smoothing_fraction, mode=mode)


def _render_auto_eq_sections_legacy(nyquist: float, *, mode: str) -> list[AutoEQSection]:
    is_gain_page = mode == "gain"
    page_label = "Auto Gain EQ" if is_gain_page else "Auto Phase EQ"
    prefix = "auto_gain_section" if is_gain_page else "auto_phase_section"
    count = _render_indexed_group_controls(prefix, page_label, auto_sort_field="start")
    list_key, _spec, items = _indexed_group_registry_items(prefix)
    if not list_key:
        return _collect_auto_gain_sections_state(nyquist) if is_gain_page else _collect_auto_phase_sections_state(nyquist)
    overview_records: list[dict[str, Any]] = []
    selection_options: list[str] = []
    selection_labels: list[str] = []
    for idx, stored_item in enumerate(items):
        item = _live_registry_item(list_key, stored_item)
        option_id = str(stored_item.get("id", f"{prefix}_{idx}"))
        selection_options.append(option_id)
        enabled = bool(item.get("enabled", True))
        start = float(item.get("f_min", 0.0) or 0.0)
        end = float(item.get("f_max", 0.0) or 0.0)
        smoothing = float(item.get("smoothing_fraction", 0.0) or 0.0)
        end_label = "Nyquist" if end == 0.0 else _format_plain_hz(end)
        selection_labels.append(f"#{idx + 1} {'ON' if enabled else 'OFF'} {_format_plain_hz(start)} - {end_label}")
        record = {
            "#": idx + 1,
            "ON": enabled,
            "Range": f"{_format_plain_hz(start)} - {end_label}",
            "Smoothing": NO_SMOOTHING_LABEL if smoothing == 0.0 else f"1/{int(smoothing)} oct",
        }
        overview_records.append(record)
    if overview_records:
        st.dataframe(
            pd.DataFrame(overview_records),
            hide_index=True,
            width="stretch",
            height=min(210, 36 + 35 * len(overview_records)),
        )
        selected_id = selectbox_indexed(
            ui_message('ui.f64923530eb730'),
            selection_options,
            settings_key=f"{prefix}_selected_item",
            labels=selection_labels,
            default=selection_options[0],
            key=f"{prefix}_selected_item_widget",
        )
        selected_indices = [
            idx for idx, item in enumerate(items)
            if str(item.get("id", f"{prefix}_{idx}")) == str(selected_id)
        ]
    else:
        selected_indices = []
    previous_end = 0.0
    for idx in selected_indices:
        if idx >= len(items):
            continue
        item = items[idx]
        header_slot = st.empty()
        range_cols = st.columns([0.16, 0.28, 0.28, 0.28])
        with range_cols[0]:
            enabled = _registry_checkbox(ui_message('ui.e8a01133b1351e'), list_key=list_key, item=item, field="enabled", default=True)
        with range_cols[1]:
            start = _registry_number_input(
                "Auto EQ start",
                list_key=list_key,
                item=item,
                field="f_min",
                min_value=0.0,
                max_value=nyquist,
                default=200.0 if idx == 0 else previous_end,
                step=1.0,
                format="%.0f",
            )
        with range_cols[2]:
            end = _registry_number_input(
                "Auto EQ end",
                list_key=list_key,
                item=item,
                field="f_max",
                min_value=0.0,
                max_value=nyquist,
                default=10_000.0 if idx == 0 else 0.0,
                step=1.0,
                format="%.0f",
                help="0 Hzを指定するとNyquistまでとして扱います。",
            )
        with range_cols[3]:
            smoothing = _registry_selectbox(
                "Smoothing",
                SMOOTHING_FRACTION_OPTIONS,
                list_key=list_key,
                item=item,
                field="smoothing_fraction",
                default=3.0,
                format_func=lambda value: NO_SMOOTHING_LABEL if value == 0.0 else f"1/{int(value)} oct",
            )
        with header_slot.container():
            _render_eq_card_header(
                auto_eq_card_title(
                    page_label,
                    idx,
                    f_min=float(start),
                    f_max=float(end),
                    enabled=bool(enabled),
                ),
                prefix,
                idx,
                show_delete=show_overview,
            )
        effective_end = nyquist if float(end) == 0.0 else min(max(float(end), float(start)), nyquist)
        if effective_end <= start and start < nyquist:
            effective_end = min(nyquist, float(start) + 1.0)
            if end != 0.0:
                st.caption(ui_message('ui.020e7211e2c483', p0=f'{effective_end:.0f}'))
        section_end = 0.0 if float(end) == 0.0 else float(effective_end)

        section_enabled = bool(enabled and effective_end > start)
        if enabled and not section_enabled:
            st.caption(ui_message('ui.e6783cc8e97bee'))
        range_end_label = "Nyquist" if float(end) == 0.0 else f"{effective_end:.0f} Hz"
        state_label = "Active" if section_enabled else "Inactive"
        mode_label = "Gain" if is_gain_page else "Phase"
        st.caption(ui_message('ui.375c8f9fe8f5fb', p0=f'{state_label}', p1=f'{mode_label}', p2=f'{start:.0f}', p3=f'{range_end_label}'))
        if section_enabled:
            previous_end = effective_end
        if not is_gain_page:
            st.caption(ui_message('ui.c6ad924182783b'))
    return _collect_auto_gain_sections_state(nyquist) if is_gain_page else _collect_auto_phase_sections_state(nyquist)


def _sync_auto_eq_end_mode(list_key: str, item_id: str, state_key: str, nyquist: float) -> None:
    mode = str(st.session_state.get(state_key, "Nyquist"))
    items = list_items(list_key, include_disabled=True, sort_by_order=True)
    item = next((candidate for candidate in items if str(candidate.get("id", "")) == item_id), None)
    if item is None:
        return
    widget_key = _registry_widget_key("num", list_key, item_id, "f_max")
    if mode == "Nyquist":
        update_list_item(list_key, item_id, {"f_max": 0.0})
        st.session_state[widget_key] = 0.0
    elif float(item.get("f_max", 0.0) or 0.0) == 0.0:
        end = float(nyquist)
        update_list_item(list_key, item_id, {"f_max": end})
        st.session_state[widget_key] = end
    _disable_overlapping_auto_eq_items_for_winner(list_key, item_id)
    _invalidate_live_result_cache()


def _render_auto_eq_sections(
    nyquist: float,
    *,
    mode: str,
    show_add: bool = True,
    show_overview: bool = True,
) -> list[AutoEQSection]:
    """Render the compact row-selection Auto EQ editor shared by Gain and Phase."""
    is_gain_page = mode == "gain"
    page_label = "Auto Gain EQ" if is_gain_page else "Auto Phase EQ"
    prefix = "auto_gain_section" if is_gain_page else "auto_phase_section"
    list_key, spec, items = _indexed_group_registry_items(prefix)
    if not list_key or not spec:
        return _collect_auto_gain_sections_state(nyquist) if is_gain_page else _collect_auto_phase_sections_state(nyquist)

    if show_overview:
        _render_filter_bulk_controls([(list_key, str(item.get("id", ""))) for item in items], key=prefix)

    selected_state_key = f"{prefix}_selected_item"
    pending_index_key = f"{prefix}_pending_selected_index"
    selection_nonce_key = f"{prefix}_selection_nonce"
    selection_nonce = int(st.session_state.get(selection_nonce_key, 0) or 0)
    selected_id = str(st.session_state.get(selected_state_key, ""))
    item_ids = [str(item.get("id", f"{prefix}_{idx}")) for idx, item in enumerate(items)]
    pending_index = st.session_state.pop(pending_index_key, None)
    if pending_index is not None and item_ids:
        selected_id = item_ids[min(max(int(pending_index), 0), len(item_ids) - 1)]
        st.session_state[selected_state_key] = selected_id
    if selected_id not in item_ids:
        selected_id = item_ids[0] if item_ids else ""
        st.session_state[selected_state_key] = selected_id

    records: list[dict[str, Any]] = []
    for idx, stored_item in enumerate(items):
        item = _live_registry_item(list_key, stored_item)
        start = float(item.get("f_min", 0.0) or 0.0)
        end = float(item.get("f_max", 0.0) or 0.0)
        smoothing = float(item.get("smoothing_fraction", 0.0) or 0.0)
        record = {
            "#": idx + 1,
            "ON": bool(item.get("enabled", True)),
            "Range": f"{_format_plain_hz(start)} - {'Nyquist' if end == 0.0 else _format_plain_hz(end)}",
            "Smoothing": NO_SMOOTHING_LABEL if smoothing == 0.0 else f"1/{int(smoothing)} oct",
        }
        records.append(record)

    if records and show_overview:
        selected_index = item_ids.index(selected_id) if selected_id in item_ids else 0
        event = st.dataframe(
            pd.DataFrame(records),
            hide_index=True,
            width="stretch",
            height=min(210, 36 + 35 * len(records)),
            key=f"{prefix}_overview_selection_{selection_nonce}",
            on_select="rerun",
            selection_mode="single-row",
            selection_default={"selection": {"rows": [selected_index]}},
        )
        selected_rows = list(event.selection.rows)
        if selected_rows and 0 <= int(selected_rows[0]) < len(items):
            clicked_id = str(items[int(selected_rows[0])].get("id", ""))
            if clicked_id and clicked_id != selected_id:
                st.session_state[selected_state_key] = clicked_id
                st.rerun()
    elif not records:
        st.caption(ui_message('ui.fbc5a887a2dd06', p0=f'{page_label}'))

    with st.container(horizontal=True, gap="small"):
        if show_add and localized_button(st, ui_message('ui.9fd728c66c9a25'), key=f"{prefix}_list_add", disabled=len(items) >= list_policy(list_key).edit_limit):
            defaults = _indexed_group_item_defaults(prefix)
            defaults["enabled"] = False
            added = add_list_item(list_key, item_type=spec["item_type"], values=defaults, enabled=False)
            st.session_state[selected_state_key] = str(added.get("id", ""))
            st.session_state[pending_index_key] = len(items)
            st.session_state[selection_nonce_key] = selection_nonce + 1
            _clear_indexed_group_widget_keys(prefix, count_hint=len(items) + 1)
            _invalidate_live_result_cache()
            st.rerun()
        if show_overview and localized_button(st, ui_message('ui.02cdaabfca805d'), key=f"{prefix}_list_duplicate", disabled=not selected_id or len(items) >= list_policy(list_key).edit_limit):
            source_item = next((candidate for candidate in items if str(candidate.get("id", "")) == selected_id), None)
            if source_item is not None:
                live_source = _live_registry_item(list_key, source_item)
                duplicate_values = {
                    field: live_source.get(field, field_spec[1] if isinstance(field_spec, tuple) and len(field_spec) >= 2 else None)
                    for field, field_spec in spec.get("fields", {}).items()
                }
                duplicate_values["enabled"] = False
                duplicated = add_list_item(list_key, item_type=spec["item_type"], values=duplicate_values, enabled=False)
                st.session_state[selected_state_key] = str(duplicated.get("id", ""))
                if not show_overview:
                    st.session_state["fir_eq_overview_selected"] = f"{prefix}:{duplicated.get('id', '')}"
                st.session_state[pending_index_key] = len(items)
                st.session_state[selection_nonce_key] = selection_nonce + 1
                _clear_indexed_group_widget_keys(prefix, count_hint=len(items) + 1)
                _invalidate_live_result_cache()
                st.rerun()
        if show_overview and localized_button(st, ui_message('ui.e2d0a54968ead2'), key=f"{prefix}_list_delete", disabled=not selected_id or len(items) >= list_policy(list_key).edit_limit):
            selected_idx = item_ids.index(selected_id) if selected_id in item_ids else 0
            if delete_list_item(list_key, selected_id):
                remaining = [item_id for item_id in item_ids if item_id != selected_id]
                st.session_state[selected_state_key] = remaining[min(selected_idx, len(remaining) - 1)] if remaining else ""
                if not show_overview:
                    next_id = str(st.session_state[selected_state_key])
                    task = "Auto Gain" if is_gain_page else "Auto Phase"
                    st.session_state["fir_eq_overview_selected"] = f"{prefix}:{next_id}" if next_id else f"empty:{task}"
                st.session_state[pending_index_key] = min(selected_idx, max(len(remaining) - 1, 0))
                st.session_state[selection_nonce_key] = selection_nonce + 1
                _clear_indexed_group_widget_keys(prefix, count_hint=len(items))
                _invalidate_live_result_cache()
                st.rerun()
        if show_overview and localized_button(st, ui_message('ui.8fb4e0ad9ff347'), key=f"{prefix}_list_sort", disabled=len(items) < 2):
            _sort_indexed_group_by_numeric_field(prefix, "f_min")
            st.session_state[selection_nonce_key] = selection_nonce + 1
            st.rerun()

    selected_indices = [idx for idx, item in enumerate(items) if str(item.get("id", "")) == selected_id]
    if not selected_indices:
        return _collect_auto_gain_sections_state(nyquist) if is_gain_page else _collect_auto_phase_sections_state(nyquist)

    idx = selected_indices[0]
    item = items[idx]
    live_item = _live_registry_item(list_key, item)
    st.markdown(ui_message('ui.10445449d8f011', p0=f'{idx + 1}'))
    if is_gain_page:
        _registry_selectbox(
            "位相モード", ["lin", "min"], list_key=list_key, item=item,
            field="gain_phase_mode", default="lin", labels=["Lin", "Min. Phase"],
            help="Lin は従来の位相を維持します。Min. Phase は振幅補正に対応する最小位相を加えます。共通の FIR 遅延は変わりません。",
        )
    st.markdown(ui_message('ui.325ff7eb3dc330'))
    enabled_end_cols = st.columns(2, gap="small")
    with enabled_end_cols[0]:
        enabled = _registry_checkbox(
            ui_message('ui.e8a01133b1351e'),
            list_key=list_key,
            item=item,
            field="enabled",
            default=True,
            on_change=_sync_auto_eq_registry_field_and_overlaps,
            args=(list_key, selected_id, "enabled", "chk"),
        )
    current_end = float(live_item.get("f_max", 0.0) or 0.0)
    end_mode_key = f"{prefix}_{selected_id}_end_mode"
    desired_end_mode = "Nyquist" if current_end == 0.0 else "Frequency"
    # The registry value is authoritative. In particular, f_max=0 must never
    # be turned into a finite frequency by stale widget state from another
    # section or a loaded project.
    if st.session_state.get(end_mode_key) != desired_end_mode:
        st.session_state[end_mode_key] = desired_end_mode
    with enabled_end_cols[1]:
        end_mode = localized_segmented_control(
            ui_message('ui.74a478eb103f21'),
            ["Frequency", "Nyquist"],
            key=end_mode_key,
            width="stretch",
            on_change=_sync_auto_eq_end_mode,
            args=(list_key, selected_id, end_mode_key, float(nyquist)),
        ) or desired_end_mode

    range_cols = st.columns(2, gap="small")
    with range_cols[0]:
        start = _registry_number_input(
            "Start Hz", list_key=list_key, item=item, field="f_min",
            min_value=0.0, max_value=nyquist, default=200.0 if idx == 0 else 0.0, step=1.0, format="%.0f",
            on_change=_sync_auto_eq_registry_field_and_overlaps,
            args=(list_key, selected_id, "f_min", "num"),
        )
    with range_cols[1]:
        if end_mode == "Nyquist":
            end = 0.0
            _update_registry_item_value(list_key, item, "f_max", 0.0)
            st.number_input(ui_message('ui.3d9fb3c137e8ba'), value=float(nyquist), disabled=True, key=f"{prefix}_{selected_id}_nyquist_display")
        else:
            if current_end == 0.0:
                current_end = float(nyquist)
                _update_registry_item_value(list_key, item, "f_max", current_end)
            end = _registry_number_input(
                "End Hz", list_key=list_key, item=item, field="f_max",
                min_value=0.0, max_value=nyquist, default=current_end, step=1.0, format="%.0f",
                on_change=_sync_auto_eq_registry_field_and_overlaps,
                args=(list_key, selected_id, "f_max", "num"),
            )

    with st.container():
        _registry_selectbox(
            "Smoothing", SMOOTHING_FRACTION_OPTIONS, list_key=list_key, item=item,
            field="smoothing_fraction", default=12.0 if is_gain_page else 3.0,
            format_func=lambda value: NO_SMOOTHING_LABEL if value == 0.0 else f"1/{int(value)} oct",
        )

    effective_end = nyquist if float(end) == 0.0 else min(max(float(end), float(start)), nyquist)
    if float(end) != 0.0 and float(end) <= float(start):
        effective_end = min(nyquist, float(start) + 1.0)
        st.warning(ui_message('ui.d498a774bb7dba', p0=f'{start:.0f}', p1=f'{effective_end:.0f}'))
    if enabled and effective_end <= float(start):
        st.warning(ui_message('ui.24fb86d5692ceb'))

    return _collect_auto_gain_sections_state(nyquist) if is_gain_page else _collect_auto_phase_sections_state(nyquist)


def _auto_edge_smooth_selectbox(
    label: str,
    key: str,
    *,
    default: float = 1.0 / 3.0,
    options: list[float] | None = None,
) -> float:
    option_values = options or AUTO_EDGE_SMOOTH_OPTIONS
    current = _stored_auto_edge_smooth_value(key, default, options=option_values)
    widget_key = f"{key}_widget"
    if st.session_state.get(widget_key) not in option_values:
        st.session_state[widget_key] = current
    value = shared_selectbox(
        label,
        option_values,
        format_func=_format_auto_edge_smooth,
        key=widget_key,
    )
    st.session_state[key] = _nearest_auto_edge_option(float(value), option_values)
    return st.session_state[key]


def _linear_fir_eq_mask_smoothing_selectbox(*, disabled: bool = False) -> float:
    key = "linear_fir_eq_mask_smoothing_oct"
    widget_key = f"{key}_widget"
    current = _nearest_linear_fir_eq_mask_smoothing_option(
        float(st.session_state.get(key, LINEAR_FIR_EQ_MASK_SMOOTHING_DEFAULT))
    )
    if st.session_state.get(widget_key) not in LINEAR_FIR_EQ_MASK_SMOOTHING_OPTIONS:
        st.session_state[widget_key] = current
    value = shared_selectbox(
        ui_message('ui.51b39d4062fdb8'),
        LINEAR_FIR_EQ_MASK_SMOOTHING_OPTIONS,
        format_func=localized_formatter(_format_linear_fir_eq_mask_smoothing),
        key=widget_key,
        disabled=disabled,
        help=(
            ui_message('ui.e01f7c71c2cb30')
        ),
    )
    st.session_state[key] = _nearest_linear_fir_eq_mask_smoothing_option(float(value))
    return st.session_state[key]


def _nearest_linear_fir_eq_mask_smoothing_option(value: float) -> float:
    return min(LINEAR_FIR_EQ_MASK_SMOOTHING_OPTIONS, key=lambda option: abs(float(option) - float(value)))


def _format_linear_fir_eq_mask_smoothing(value: float) -> str:
    if np.isclose(float(value), 1.0 / 6.0):
        return "1/6 oct"
    if np.isclose(float(value), 1.0 / 3.0):
        return "1/3 oct"
    if np.isclose(float(value), 1.0 / 2.0):
        return "1/2 oct"
    return f"{float(value):g} oct"


TARGET_GAIN_ADD_TYPE_OPTIONS = (
    "Gain PEQ",
    "Gain High Shelf",
    "Gain Low Shelf",
    "Gain High Tilt",
    "Gain Low Tilt",
    "Linear High Pass",
    "Linear Low Pass",
    "IIR High Pass",
    "IIR Low Pass",
)

TARGET_PHASE_ADD_TYPE_OPTIONS = (
    "Phase PEQ",
    "Phase High Shelf",
    "Phase Low Shelf",
    "Phase Tilt",
    "All Pass",
)


def _target_gain_filter_rows() -> list[tuple[str, str, int, dict[str, Any]]]:
    rows: list[tuple[str, str, int, dict[str, Any]]] = []
    for prefix, base_type in (
        ("target_gain_peq", "Gain PEQ"),
        ("target_gain_shelf", "Gain Shelf"),
        ("target_gain_tilt", "Gain High Tilt"),
        ("target_gain_lo_tilt", "Gain Low Tilt"),
        ("target_gain_linear", "Linear Filter"),
    ):
        _list_key, _spec, items = _indexed_group_registry_items(prefix)
        for idx, item in enumerate(items):
            filter_type = base_type
            if prefix == "target_gain_shelf":
                filter_type = "Gain High Shelf" if str(item.get("mode", "high")) == "high" else "Gain Low Shelf"
            elif prefix == "target_gain_linear":
                filter_type = "Linear High Pass" if str(item.get("mode", "lp")) == "hp" else "Linear Low Pass"
            rows.append((filter_type, prefix, idx, item))
    _list_key, _spec, iir_items = _indexed_group_registry_items("target_iir_filter")
    for idx, item in enumerate(iir_items):
        kind = str(item.get("kind", "high_pass"))
        if kind in {"high_pass", "low_pass"}:
            rows.append(("IIR High Pass" if kind == "high_pass" else "IIR Low Pass", "target_iir_filter", idx, item))
    return rows


def _target_phase_filter_rows() -> list[tuple[str, str, int, dict[str, Any]]]:
    rows: list[tuple[str, str, int, dict[str, Any]]] = []
    for prefix, base_type in (
        ("target_phase_peq", "Phase PEQ"),
        ("target_phase_shelf", "Phase Shelf"),
        ("target_phase_tilt", "Phase Tilt"),
    ):
        _list_key, _spec, items = _indexed_group_registry_items(prefix)
        for idx, item in enumerate(items):
            filter_type = base_type
            if prefix == "target_phase_shelf":
                filter_type = "Phase High Shelf" if str(item.get("mode", "high")) == "high" else "Phase Low Shelf"
            rows.append((filter_type, prefix, idx, item))
    _list_key, _spec, iir_items = _indexed_group_registry_items("target_iir_filter")
    for idx, item in enumerate(iir_items):
        if str(item.get("kind", "high_pass")) == "allpass":
            rows.append(("All Pass", "target_iir_filter", idx, item))
    return rows


def _render_target_filter_controls(
    *,
    view: str,
    rows: list[tuple[str, str, int, dict[str, Any]]],
    add_options: tuple[str, ...],
) -> tuple[bool, str, str]:
    key_prefix = f"target_{view.lower()}_all"
    controls = st.columns([0.18, 0.42, 0.27, 0.13], gap="small", vertical_alignment="bottom")
    with controls[0]:
        add_clicked = localized_button(st, ui_message('ui.9fd728c66c9a25'), key=f"{key_prefix}_add", width="stretch")
    with controls[1]:
        add_type = selectbox_indexed(
            ui_message('ui.e520df698000f8'),
            list(add_options),
            settings_key=f"{key_prefix}_add_type",
            default=add_options[0],
            key=f"{key_prefix}_add_type_widget",
        )
    with controls[2]:
        sort_mode = selectbox_indexed(
            ui_message('ui.bec69036aa27e7'),
            ["None", "Frequency", "Type"],
            settings_key=f"{key_prefix}_display_sort",
            default="None",
            key=f"{key_prefix}_display_sort_widget",
        format_func=localized_formatter(str))
    with controls[3]:
        st.caption(ui_message('ui.a5fee16d31821b', p0=f'{len(rows)}') if len(rows) == 1 else ui_message('ui.53528979ac6e7b', p0=f'{len(rows)}'))
    return add_clicked, str(add_type), str(sort_mode)


def _add_target_filter(view: str, add_type: str) -> None:
    common_selection_key = f"target_{view.lower()}_all_selected_filter"
    prefix: str
    overrides: dict[str, Any] = {}
    if add_type == "Gain PEQ":
        prefix = "target_gain_peq"
    elif add_type in {"Gain High Shelf", "Gain Low Shelf"}:
        prefix = "target_gain_shelf"
        overrides["mode"] = "high" if add_type == "Gain High Shelf" else "low"
    elif add_type in {"Gain High Tilt", "Gain Low Tilt"}:
        prefix = "target_gain_tilt" if add_type == "Gain High Tilt" else "target_gain_lo_tilt"
        overrides.update(
            {
                "mode": "high" if add_type == "Gain High Tilt" else "low",
                "f_start": 100.0 if add_type == "Gain High Tilt" else 1.0,
                "f_end": 20_000.0 if add_type == "Gain High Tilt" else 1000.0,
            }
        )
    elif add_type in {"Linear High Pass", "Linear Low Pass"}:
        prefix = "target_gain_linear"
        overrides.update({"mode": "hp" if add_type == "Linear High Pass" else "lp", "response": "lr2"})
    elif add_type in {"IIR High Pass", "IIR Low Pass"}:
        prefix = "target_iir_filter"
        overrides.update(
            {
                "kind": "high_pass" if add_type == "IIR High Pass" else "low_pass",
                "origin": "manual",
                "family": "linkwitz_riley",
                "filter_order": 4,
            }
        )
    elif add_type == "Phase PEQ":
        prefix = "target_phase_peq"
    elif add_type in {"Phase High Shelf", "Phase Low Shelf"}:
        prefix = "target_phase_shelf"
        overrides["mode"] = "high" if add_type == "Phase High Shelf" else "low"
    elif add_type == "Phase Tilt":
        prefix = "target_phase_tilt"
        overrides.update({"f_start": 100.0, "f_end": 20_000.0})
    else:
        prefix = "target_iir_filter"
        overrides.update(
            {
                "kind": "allpass",
                "origin": "manual",
                "allpass_preset": "lr4",
                "filter_order": 2,
            }
        )
    added = _add_indexed_group_item(prefix, overrides, selection_key=common_selection_key)
    if added is not None:
        _set_filter_editor_selection(common_selection_key, f"{prefix}:{added.get('id', '')}")


def _render_target_gain_editor(
    nyquist: float,
) -> tuple[list[GainPEQ], list[GainShelf], list[GainLinearFilter], list[GainTilt], float]:
    rows = _target_gain_filter_rows()
    add_clicked, add_type, sort_mode = _render_target_filter_controls(
        view="Gain", rows=rows, add_options=TARGET_GAIN_ADD_TYPE_OPTIONS
    )
    if add_clicked:
        _add_target_filter("Gain", add_type)
        st.rerun()
    sort_settings_key = "target_gain_all_display_sort"
    sort_widget_key = "target_gain_all_display_sort_widget"
    apply_sort = len(rows) > 1 and sort_mode != "None"
    if apply_sort:
        _reset_sort_select(sort_settings_key, sort_widget_key)
    ordered_rows = _combined_one_frequency_rows(rows, sort_mode, cache_key="target_gain_all_display", refresh=apply_sort)
    if apply_sort:
        st.rerun()
    selected_row = _render_filter_overview_selector(
        ordered_rows,
        key="target_gain_all_selected_filter",
        include_q=True,
    )
    if selected_row is not None:
        _filter_type, prefix, _idx, item = selected_row
        option_id = f"{prefix}:{item.get('id', '')}"
        if prefix in {"target_gain_peq", "target_gain_shelf", "target_gain_linear"}:
            _set_filter_editor_selection("target_gain_eq_selected_filter", option_id)
            group = "Linear HP / LP" if prefix == "target_gain_linear" else "PEQ / Shelf"
            _render_target_gain_one_frequency_eq(nyquist, filter_group=group, show_add=False, show_overview=False)
        elif prefix in {"target_gain_tilt", "target_gain_lo_tilt"}:
            _set_filter_editor_selection("target_gain_tilt_selected_filter", option_id)
            with st.container(border=True):
                _auto_edge_smooth_selectbox(
                    "Target Gain Tilt total smoothing",
                    key="target_gain_tilt_smoothing_oct",
                    options=GAIN_TILT_SMOOTH_OPTIONS,
                )
                st.caption(
                    ui_message('ui.3856881698e5b8')
                )
                _render_gain_tilt_combined_items(
                    "target_gain_tilt",
                    hi_prefix="target_gain_tilt",
                    hi_label="Target Gain High Tilt",
                    hi_default_start=100.0,
                    hi_default_end=min(20_000.0, nyquist),
                    lo_prefix="target_gain_lo_tilt",
                    lo_label="Target Gain Low Tilt",
                    lo_default_start=1.0,
                    lo_default_end=min(1000.0, nyquist),
                    nyquist=nyquist,
                    show_add=False,
                    show_overview=False,
                )
        else:
            _set_filter_editor_selection("target_iir_gain_selected_filter", option_id)
            _render_target_iir_editor(nyquist, view="Gain", show_add=False, show_overview=False)
    return _collect_target_gain_state(nyquist)


def _render_target_iir_editor(
    nyquist: float,
    *,
    view: str,
    show_add: bool = True,
    show_overview: bool = True,
) -> None:
    if show_add or show_overview:
        _function_section_heading(view.lower(), ui_message('ui.eb4a1459754370') if view == "Gain" else ui_message('ui.80afa43e9d8db1'))
    st.caption(
        ui_message('ui.5fc7695c608352')
        + (ui_message('ui.9d22c1e5e94476') if view == "Gain" else ui_message('ui.ea3ff2b26c7079'))
    )
    list_key = "target_iir_filter_items"
    _, _, items = _indexed_group_registry_items("target_iir_filter")
    visible_kinds = ("high_pass", "low_pass") if view == "Gain" else ("allpass",)
    rows = [
        (IIR_KIND_LABELS.get(str(item.get("kind", "high_pass")), "High Pass"), "target_iir_filter", idx, item)
        for idx, item in enumerate(items)
        if str(item.get("kind", "high_pass")) in visible_kinds
    ]
    add_clicked = False
    add_type = IIR_KIND_LABELS[visible_kinds[0]]
    sort_mode = "None"
    if show_add or show_overview:
        controls = st.columns([0.38, 0.22, 0.20, 0.20], gap="small")
        with controls[0]:
            add_type = shared_selectbox(
                ui_message('ui.a59fcccbd13e44'),
                [IIR_KIND_LABELS[kind] for kind in visible_kinds],
                index=0,
                key=f"target_iir_{view.lower()}_add_type",
            )
        with controls[1]:
            add_clicked = show_add and st.button(ui_message('ui.9fd728c66c9a25'), key=f"target_iir_{view.lower()}_add", icon=":material/add:", width="stretch")
        with controls[2]:
            sort_mode = selectbox_indexed(
                ui_message('ui.bec69036aa27e7'),
                ["None", "Frequency", "Type"],
                settings_key=f"target_iir_{view.lower()}_display_sort",
                default="None",
                key=f"target_iir_{view.lower()}_display_sort_widget",
            format_func=localized_formatter(str))
        with controls[3]:
            st.caption(ui_message('ui.53528979ac6e7b', p0=f'{len(rows)}'))
    if add_clicked:
        kind = IIR_LABEL_KINDS[str(add_type)]
        defaults: dict[str, Any] = {"kind": kind, "origin": "manual"}
        if kind in {"high_pass", "low_pass"}:
            defaults.update({"family": "linkwitz_riley", "filter_order": 4})
        else:
            defaults.update({"allpass_preset": "lr4", "filter_order": 2})
        _add_indexed_group_item("target_iir_filter", defaults, selection_key=f"target_iir_{view.lower()}_selected_filter")
        st.rerun()
    apply_sort = len(rows) > 1 and sort_mode != "None"
    if apply_sort:
        _reset_sort_select(f"target_iir_{view.lower()}_display_sort", f"target_iir_{view.lower()}_display_sort_widget")
    ordered_rows = _combined_one_frequency_rows(rows, str(sort_mode), cache_key=f"target_iir_{view.lower()}_display", refresh=apply_sort)
    if apply_sort:
        st.rerun()
    identifiers = _iir_overview_identifiers(ordered_rows)
    selected_row = _render_filter_overview_selector(
        ordered_rows,
        key=f"target_iir_{view.lower()}_selected_filter",
        include_q=True,
        identifiers=identifiers,
        show_table=show_overview,
    )
    if selected_row is None:
        return
    display_idx = ordered_rows.index(selected_row)
    _, prefix, idx, item = selected_row
    with st.container(border=True, key="target_iir_selected_card"):
        header_slot = st.empty()
        kind = str(_registry_current_item_value(list_key, item, "kind", "allpass"))
        base_cols = st.columns([0.14, 0.38, 0.48], gap="small")
        with base_cols[0]:
            enabled = _registry_checkbox(ui_message('ui.e8a01133b1351e'), list_key=list_key, item=item, field="enabled", default=True)
        with base_cols[1]:
            kinds = list(visible_kinds)
            kind = _registry_selectbox(
                "Target IIR type",
                kinds,
                list_key=list_key,
                item=item,
                field="kind",
                default=kind,
                labels=[IIR_KIND_LABELS[value] for value in kinds],
                help="IIR EQと同じ実フィルター係数をTargetへ適用します。",
            )
        with base_cols[2]:
            _registry_number_input(
                "Target IIR Frequency Hz",
                list_key=list_key,
                item=item,
                field="fc",
                min_value=1.0,
                max_value=max(nyquist - 1.0, 1.0),
                default=1000.0,
                step=1.0,
                format="%.0f",
            )
        if kind == "allpass":
            _render_iir_allpass_controls(
                list_key=list_key,
                item=item,
                default_preset="lr4",
                label_prefix="Target ",
            )
        else:
            crossover_cols = st.columns(2, gap="small")
            with crossover_cols[0]:
                family = _registry_selectbox(
                    "Target IIR Family",
                    list(IIR_FAMILY_LABELS),
                    list_key=list_key,
                    item=item,
                    field="family",
                    default="linkwitz_riley",
                    labels=list(IIR_FAMILY_LABELS.values()),
                )
            with crossover_cols[1]:
                orders = [2] if family == "variable_q" else list(range(1, 9)) if family == "elliptic" else list(IIR_LINKWITZ_RILEY_ORDERS if family == "linkwitz_riley" else IIR_CROSSOVER_ORDERS)
                _registry_selectbox(
                    "Target IIR Order",
                    orders,
                    list_key=list_key,
                    item=item,
                    field="filter_order",
                    default=4 if family == "linkwitz_riley" else 2,
                    format_func=lambda value, family=family: str(value) if family == "elliptic" else f"{value} ({int(value) * 6} dB/oct)",
                )
            _render_iir_prototype_parameters(list_key, item, family, nyquist)
        with header_slot.container():
            _render_eq_card_header(
                f"{identifiers[display_idx]} | {'ON' if enabled else 'OFF'}",
                prefix,
                idx,
                show_delete=show_overview,
            )


def _render_target_phase_editor(
    nyquist: float,
) -> tuple[list[PhasePEQ], list[PhaseShelf], list[PhaseTilt], float, list[PhaseAllPass]]:
    rows = _target_phase_filter_rows()
    add_clicked, add_type, sort_mode = _render_target_filter_controls(
        view="Phase", rows=rows, add_options=TARGET_PHASE_ADD_TYPE_OPTIONS
    )
    if add_clicked:
        _add_target_filter("Phase", add_type)
        st.rerun()
    sort_settings_key = "target_phase_all_display_sort"
    sort_widget_key = "target_phase_all_display_sort_widget"
    apply_sort = len(rows) > 1 and sort_mode != "None"
    if apply_sort:
        _reset_sort_select(sort_settings_key, sort_widget_key)
    ordered_rows = _combined_one_frequency_rows(rows, sort_mode, cache_key="target_phase_all_display", refresh=apply_sort)
    if apply_sort:
        st.rerun()
    selected_row = _render_filter_overview_selector(
        ordered_rows,
        key="target_phase_all_selected_filter",
        include_q=True,
    )
    if selected_row is not None:
        _filter_type, prefix, _idx, item = selected_row
        option_id = f"{prefix}:{item.get('id', '')}"
        if prefix in {"target_phase_peq", "target_phase_shelf"}:
            _set_filter_editor_selection("target_phase_eq_selected_filter", option_id)
            _render_target_phase_one_frequency_eq(nyquist, show_add=False, show_overview=False)
        elif prefix == "target_phase_tilt":
            _set_filter_editor_selection("target_phase_tilt_selected_filter", option_id)
            with st.container(border=True, key="target_phase_tilt_selected_card"):
                _render_phase_tilt_items(
                    prefix="target_phase_tilt",
                    label="Target Phase Tilt",
                    smoothing_label="Target Phase Tilt total smoothing",
                    smoothing_key="target_phase_tilt_smoothing_oct",
                    nyquist=nyquist,
                    show_add=False,
                    show_overview=False,
                )
        else:
            _set_filter_editor_selection("target_iir_phase_selected_filter", option_id)
            _render_target_iir_editor(nyquist, view="Phase", show_add=False, show_overview=False)
    return _collect_target_phase_state(nyquist)


