@st.fragment(run_every=2.0)
def _publish_phaseeq_session_heartbeat() -> None:
    from ui.phaseeq_target_navigation import receive_target_menu_request
    receive_target_menu_request(STORAGE_PATHS["composite_exchange"])
    assignment = active_composite_assignment
    target_session = _active_target_edit_session
    mode = (
        "TargetEdit" if target_session is not None
        else "Assignment" if assignment is not None
        else "Standalone"
    )
    try:
        write_phaseeq_session_status(
            STORAGE_PATHS["composite_exchange"],
            session_id=_browser_session_id,
            mode=mode,
            active_page=str(st.session_state.get("active_page", "")),
            assignment_id=active_assignment_id if assignment is not None else "",
            channel_id=str(getattr(assignment, "channel_id", "")),
            channel_name=str(getattr(assignment, "channel_name", "")),
            group=(
                str(target_session.group) if target_session is not None
                else str(getattr(assignment, "group", ""))
            ),
            target_edit_session_id=(
                str(target_session.session_id) if target_session is not None else ""
            ),
        )
    except (OSError, ValueError):
        return

    from ui.measurement_input_sync import refresh_measurement_input_if_updated
    refresh_measurement_input_if_updated(
        STORAGE_PATHS["composite_exchange"], assignment, target_edit=target_session is not None,
    )
    from ui.assignment_watch import refresh_assignment_if_updated
    refresh_assignment_if_updated(
        STORAGE_PATHS["composite_exchange"], assignment,
        target_edit=target_session is not None,
    )


