if raw_target_response is not None and raw_target_response is restored_target_response:
    input_messages.append(
        f"Target Response: {target_source_name} (restored) / {len(raw_target_response.frequency)} rows"
    )
elif raw_target_response is not None:
    st.session_state["_restored_target_response_raw"] = raw_target_response
    st.session_state["_restored_target_source_name"] = target_source_name
    # Remember the URL field seen when the snapshot was accepted. If a file
