st.session_state["_speaker_source_name"] = speaker_source_name if raw_speaker_response is not None else ""
st.session_state["_target_source_name"] = target_source_name if raw_target_response is not None else ""
st.session_state["_mic_cal_source_name"] = mic_cal_source_name if mic_cal_source_name else ""

# Imports finish after the editor header is rendered. Refresh its save status
