if assignment_switcher_slot is not None:
    try:
        _system_assignments = list_switchable_composite_assignments(
            STORAGE_PATHS["composite_exchange"], assignment=active_composite_assignment,
        )
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        _system_assignments = ()
        st.warning(ui_message('ui.8cd5ac91f4f081', p0=f'{exc}'))
    _assignment_by_id = {
        item.assignment_id: item for item in _system_assignments
        if item.assignment_id
    }
    if active_composite_assignment is not None:
        _assignment_by_id[active_assignment_id] = active_composite_assignment
    _assignment_options = ["", *_assignment_by_id]
    if (
        "composite_phaseeq_channel_switcher" not in st.session_state
        or st.session_state.get("composite_phaseeq_channel_switcher") is None
        or st.session_state.get("composite_phaseeq_channel_switcher") not in _assignment_options
        or st.session_state.get("_composite_channel_switcher_context")
        != active_assignment_id
    ):
        # Editor actions such as EQ delete may call st.rerun() before this
        # late-rendered widget is reached. Streamlit then removes the widget
        # key because it was not rendered in that pass. Re-seed the UI from
        # the durable active Assignment instead of allowing selectbox option 0
        # to select and reset another Composite channel.
        st.session_state["composite_phaseeq_channel_switcher"] = active_assignment_id
        st.session_state["_composite_channel_switcher_context"] = active_assignment_id
    with assignment_switcher_slot:
        _selected_assignment_id = active_assignment_id
        _link_toggle_host = _link_detail_host = None
        if len(_assignment_options) > 1:
            if active_composite_assignment is not None:
                _channel_label, _channel_control, _link_toggle_host, _link_detail_host = st.columns(
                    [0.10, 0.52, 0.32, 0.06], gap="small", vertical_alignment="center", wrap=False,
                )
            else:
                _channel_label, _channel_control = st.columns([0.14, 0.86], gap="small", vertical_alignment="center")
            _channel_label.markdown(display_text("編集対象"))
            # This selector must send programmatic rollback values to the browser.
            # The generic choice wrapper consumes Session State as a default only.
            _selected_assignment_id = _channel_control.selectbox(
                ui_message('ui.e3a1ac8c9dfeec'),
                _assignment_options,
                index=0,
                format_func=lambda assignment_id: "Standalone" if not assignment_id else (
                    f"{_assignment_by_id[assignment_id].group} / {_assignment_by_id[assignment_id].channel_name}"
                    + (f"（{_assignment_by_id[assignment_id].way}）" if _assignment_by_id[assignment_id].way != _assignment_by_id[assignment_id].channel_name else "")
                    + f" · {_assignment_by_id[assignment_id].sample_rate_hz / 1000:g} kHz"
                    + (f" · {_assignment_by_id[assignment_id].tap_count:,} taps" if _assignment_by_id[assignment_id].tap_count > 0 else " · FIR OFF")
                    + (" · " + display_text("更新あり") if assignment_id == active_assignment_id and _latest_same_channel_id and _latest_same_channel_id != active_assignment_id else "")
                ),
                key="composite_phaseeq_channel_switcher",
                on_change=queue_channel_switch,
                args=(st.session_state,),
                label_visibility="collapsed",
                help=(
                    ui_message('ui.ea9968221d0a7c')
                    + (ui_message('ui.6627794a7e1fd5', p0=f'{active_assignment_id[:8]}', p1=f'{_active_assignment_state}') if active_assignment_id else "")
                    + (ui_message('ui.8b42ed255244a4') if _latest_same_channel_id and _latest_same_channel_id != active_assignment_id else "")
                ),
            )
        def _stereo_other_payload(channel_id):
            item = next(item for item in _stereo_assignments if item.channel_id == channel_id)
            draft = st.session_state.get("_composite_channel_drafts", {}).get(item.assignment_id)
            if draft is not None:
                return draft
            path = assignment_working_session_path(STORAGE_PATHS["composite_exchange"], item.assignment_id)
            if path is None:
                previous = latest_published_assignment_working_session(
                    STORAGE_PATHS["composite_exchange"], channel_id=channel_id,
                    system_id=item.system_id, exclude_assignment_id=item.assignment_id)
                path = previous[1] if previous else None
            return config_payload_from_project_zip(io.BytesIO(path.read_bytes())) if path else _stereo_default
        stereo_link.render(st.session_state, STORAGE_PATHS["composite_exchange"],
                           lambda payload: _queue_config_payload(payload, "Stereo Link"),
                           _stereo_other_payload, toggle_host=_link_toggle_host,
                           detail_host=_link_detail_host)
        _context_notice = str(st.session_state.get("_settings_notice", ""))
        if _context_notice.startswith(("切替できません", "設定を読み込めません", "Composite Workspaceを復元できません")):
            st.warning(_context_notice)
    _refresh_key = (active_assignment_id, _latest_same_channel_id)
    if (_selected_assignment_id == active_assignment_id and _latest_same_channel_id
        and _latest_same_channel_id != active_assignment_id
        and _latest_same_channel_id in _assignment_by_id
        and st.session_state.get("_composite_auto_refresh_attempt") != _refresh_key):
        st.session_state["_composite_auto_refresh_attempt"] = _refresh_key
        _selected_assignment_id = _latest_same_channel_id
        st.session_state["_pending_composite_context"] = {
            "assignment_id": _selected_assignment_id,
            "payload": _config_payload(
                config,
                raw_speaker_response=raw_speaker_response_for_export,
                raw_target_response=raw_target_response_for_export,
                mic_cal_response=mic_cal_response_for_export,
            ),
        }
        st.rerun()

# Histories observe settled input/Target/config pipelines, never editor callbacks.
from utils import design_history as design_history
from utils.design_history_ui import render_history as render_design_history
if active_page != "Measure":
    if active_page == "Target" and not target_locked:
        _history_scope, _history_owner = "target", _history_target_owner()
        _history_factory = lambda: _target_editor_record(str(st.session_state.get("_target_preset_editing_id", "")))
        _history_generation = _target_editor_signature()
        _history_restore = _history_restore_target
    elif active_composite_assignment is None:
        _history_scope, _history_owner = "standalone", _history_standalone_owner()
        _history_factory = lambda: design_history.compact_settings(_config_payload(
            config, raw_speaker_response=raw_speaker_response_for_export,
            raw_target_response=raw_target_response_for_export,
            mic_cal_response=mic_cal_response_for_export))
        _history_generation = _config_signature(config, raw_speaker_response, raw_target_response) + str(_cache_coordinator().revision(CacheDomain.DESIGN_RESULT))
        _history_restore = _history_restore_settings
    else:
        _history_scope = ""
    if _history_scope:
        with editor_window:
            _history_tick(_history_scope, _history_owner, _history_generation, _history_factory)
            _history_show_controls = _history_scope != "target" or unified_target_workspace
            if _history_show_controls:
                # Keep acquisition after pipeline settlement; only move its UI.
                with target_save_host if _history_scope == "target" else editor_window:
                    if st.session_state.get("_history_error"):
                        with st.expander(display_text("履歴 ⚠"), expanded=False):
                            st.caption(st.session_state["_history_error"])
                    render_design_history(_history_path(), _history_scope, _history_owner,
                                          _history_factory, _history_restore,
                                          app_version=APP_VERSION, target=_history_scope == "target",
                                          ready=not any(session.active_page == "Measure" for session in list_active_phaseeq_sessions(STORAGE_PATHS["composite_exchange"])),
                                          clone=_history_clone_target if _history_scope == "target" else _history_clone_settings)
            _restored_history = st.session_state.get("_history_restore_pending")
            if _restored_history:
                try:
                    design_history.save(_history_path(), _history_scope, _history_owner,
                                        _history_factory(), kind="restore", app_version=APP_VERSION,
                                        restored_from=_restored_history)
                except (OSError, ValueError, sqlite3.Error) as exc:
                    st.session_state["_history_error"] = str(exc)
                else:
                    st.session_state.pop("_history_restore_pending", None)

